var e={id:`k1-46-mesane-hastaliklari-ve-tumorleri`,sira:46,kurul:1,ders:`Tıbbi Patoloji`,konu:`Mesane Hastalıkları ve Tümörleri`,ogretim_uyesi:`Prof. Dr. Hikmet Keleş`,tarih:`2026-10-06`,soru_sayisi:166,kazanimlar:[{no:1,metin:`Alt idrar yolu ürotelyumunun yapısını ve patoloji gruplarını açıklayabilmek`,sorular:[{id:`k1-46-q01`,kazanim:1,zorluk:`kolay`,soru:`Böbrek pelvisi, üreter, mesane ve üretrayı döşeyen epitel hangisidir?`,secenekler:{A:`Tek katlı silindirik epitel`,B:`Çok katlı keratinize yassı epitel`,C:`Ürotelyum (geçiş epiteli)`,D:`Psödostratifiye silli epitel`,E:`Tek katlı yassı epitel`},dogru:`C`,aciklama:`Alt idrar yolu ürotelyum (geçiş epiteli) ile kaplıdır; altında lamina propria ve muskularis propria bulunur.`,sik_aciklamalari:{A:`Tek katlı silindirik epitel bağırsak mukozasında bulunur.`,B:`Keratinize yassı epitel deri epitelidir; mesanede ancak metaplazi ile görülür.`,C:`Doğru: ürotelyum alt idrar yolunun normal döşeyici epitelidir.`,D:`Psödostratifiye silli epitel solunum yollarını döşer.`,E:`Tek katlı yassı epitel damar endotelinde ve alveollerde görülür.`},bilgi:[1],benzer_cikmis:[]},{id:`k1-46-q02`,kazanim:1,zorluk:`orta`,soru:`Mesanede muskularis propria tabakasının diğer adı aşağıdakilerden hangisidir?`,secenekler:{A:`Lamina propria`,B:`Detrusor kası`,C:`Muskularis mukoza`,D:`Adventisya`,E:`Trigon epiteli`},dogru:`B`,aciklama:`Mesanede muskularis propria detrusor kası olarak adlandırılır; tümör evrelemesinde invazyonu belirleyicidir.`,sik_aciklamalari:{A:`Lamina propria ürotelyumun altındaki bağ dokusudur.`,B:`Doğru: detrusor mesanenin kas tabakasıdır.`,C:`Muskularis mukoza ince ve düzensiz bir tabakadır, detrusor değildir.`,D:`Adventisya en dış bağ dokusu katmanıdır.`,E:`Trigon mesane tabanındaki bölgedir, kas tabakasının adı değildir.`},bilgi:[1],benzer_cikmis:[]},{id:`k1-46-q03`,kazanim:1,zorluk:`zor`,soru:`Alt idrar yolu patolojileri gruplandırıldığında aşağıdaki eşleştirmelerden hangisi yanlıştır?`,secenekler:{A:`UPJ tıkanıklığı – doğuştan anomali`,B:`Hemorajik sistit – enfeksiyon/inflamasyon`,C:`Ürotelyal karsinom – neoplazma`,D:`Mesane divertikülü – her zaman neoplastik süreç`,E:`Retroperitoneal fibrozis – reaktif süreç`},dogru:`D`,aciklama:`Mesane divertikülü konjenital veya edinilmiş bir yapısal anomalidir; neoplazm değildir, nadiren zemininde tümör gelişebilir.`,sik_aciklamalari:{A:`Doğru eşleştirme: UPJ tıkanıklığı konjenitaldir.`,B:`Doğru eşleştirme: hemorajik sistit inflamatuar bir tablodur.`,C:`Doğru eşleştirme: ürotelyal karsinom en sık mesane neoplazmıdır.`,D:`Yanlış eşleştirme (aranan cevap): divertikül neoplazm değildir.`,E:`Doğru eşleştirme: retroperitoneal fibrozis reaktif bir süreçtir.`},bilgi:[1,2,6,7],benzer_cikmis:[]},{id:`k1-46-mesane-hastaliklari-ve-tumorleri-k01-q04`,kazanim:1,zorluk:`orta`,soru:`Mesane biyopsisinde geçiş epiteli altında lamina propria ve detrusor kası izleniyor. Aşağıdakilerden hangisi doğrudur?`,secenekler:{A:`Mesane skuamöz epitelle döşelidir`,B:`Detrusor kası böbrekte bulunur`,C:`Ürotelyum yalnızca üreterde vardır`,D:`Böbrek pelvisi, üreter, mesane ve üretra ürotelyum ile kaplıdır; altında lamina propria ve muskularis propria (mesanede detrusor) bulunur`,E:`Patolojiler yalnızca neoplazmalardan oluşur`},dogru:`D`,aciklama:`Alt idrar yolu ürotelyum ile kaplıdır; patolojiler anomali, inflamasyon ve neoplazma olarak gruplanır.`,sik_aciklamalari:{A:`Yanlış: bu seçenek vakadaki tabloyla uyumlu değildir; doğru yanıt 'Böbrek pelvisi, üreter, mesane ve üretra ürotelyum ile kaplıdır; altında lamina propria ve muskularis propria (mesanede detrusor) bulunur' seçeneğidir.`,B:`Yanlış: bu seçenek vakadaki tabloyla uyumlu değildir; doğru yanıt 'Böbrek pelvisi, üreter, mesane ve üretra ürotelyum ile kaplıdır; altında lamina propria ve muskularis propria (mesanede detrusor) bulunur' seçeneğidir.`,C:`Yanlış: bu seçenek vakadaki tabloyla uyumlu değildir; doğru yanıt 'Böbrek pelvisi, üreter, mesane ve üretra ürotelyum ile kaplıdır; altında lamina propria ve muskularis propria (mesanede detrusor) bulunur' seçeneğidir.`,D:`Doğru: Alt idrar yolu ürotelyum ile kaplıdır; patolojiler anomali, inflamasyon ve neoplazma olarak gruplanır.`,E:`Yanlış: bu seçenek vakadaki tabloyla uyumlu değildir; doğru yanıt 'Böbrek pelvisi, üreter, mesane ve üretra ürotelyum ile kaplıdır; altında lamina propria ve muskularis propria (mesanede detrusor) bulunur' seçeneğidir.`},bilgi:[1],benzer_cikmis:[]},{id:`k1-46-mesane-hastaliklari-ve-tumorleri-k01-q05`,kazanim:1,zorluk:`zor`,soru:`Alt idrar yolu patoloji grupları sayılıyor. Aşağıdakilerden hangisi yanlıştır?`,secenekler:{A:`Patolojiler doğuştan anomali, enfeksiyon/inflamasyon ve neoplazma olarak gruplanır`,B:`Ürotelyum geçiş epitelidir`,C:`Mesanede muskularis propria detrusor adını alır`,D:`Ürotelyum kolumnar müsinöz epiteldir ve detrusor böbrek pelvisindedir`,E:`Lamina propria ürotelyumun altındadır`},dogru:`A`,aciklama:`Ürotelyum geçiş epitelidir; detrusor mesanededir. Son ifade yanlıştır.`,sik_aciklamalari:{A:`Doğru: Ürotelyum geçiş epitelidir; detrusor mesanededir. Son ifade yanlıştır.`,B:`Yanlış: bu seçenek vakadaki tabloyla uyumlu değildir; doğru yanıt 'Patolojiler doğuştan anomali, enfeksiyon/inflamasyon ve neoplazma olarak gruplanır' seçeneğidir.`,C:`Yanlış: bu seçenek vakadaki tabloyla uyumlu değildir; doğru yanıt 'Patolojiler doğuştan anomali, enfeksiyon/inflamasyon ve neoplazma olarak gruplanır' seçeneğidir.`,D:`Yanlış: bu seçenek vakadaki tabloyla uyumlu değildir; doğru yanıt 'Patolojiler doğuştan anomali, enfeksiyon/inflamasyon ve neoplazma olarak gruplanır' seçeneğidir.`,E:`Yanlış: bu seçenek vakadaki tabloyla uyumlu değildir; doğru yanıt 'Patolojiler doğuştan anomali, enfeksiyon/inflamasyon ve neoplazma olarak gruplanır' seçeneğidir.`},bilgi:[1],benzer_cikmis:[]},{id:`k1-46-mesane-hastaliklari-ve-tumorleri-k01-q06`,kazanim:1,zorluk:`orta`,soru:`Alt idrar yolunun duvar katmanları içten dışa nasıl sıralanır?`,secenekler:{A:`Skuamöz epitel ve seroza ile çevrilidir`,B:`Ürotelyum, lamina propria ve muskularis propria`,C:`Kolumnar epitel ve submukoza içermez`,D:`Yalnızca detrusor kasından oluşur`,E:`Keratinosit tabakası ve dermis içerir`},dogru:`B`,aciklama:`Böbrek pelvisi, üreter, mesane ve üretra ürotelyum (geçiş epiteli) ile döşelidir. Altında lamina propria, onun altında muskularis propria (mesanede detrusor) bulunur. Kas invazyonu evrelemede bu katman üzerinden değerlendirilir.`,sik_aciklamalari:{A:`Yanlış: Alt idrar yolunu geçiş epiteli döşer, skuamöz değil.`,B:`Doğru: Ürotelyum altında lamina propria ve kas tabakası bulunur.`,C:`Yanlış: Ürotelyum kolumnar değil, çok katlı geçiş epitelidir.`,D:`Yanlış: Kas tabakası yalnızca bir katmandır.`,E:`Yanlış: Keratinosit ve dermis deri bileşenleridir.`},bilgi:[1],benzer_cikmis:[]},{id:`k1-46-mesane-hastaliklari-ve-tumorleri-k01-q07`,kazanim:1,zorluk:`orta`,soru:`Ürotelyum ve detrusor kasının işlevsel katkısı nedir?`,secenekler:{A:`Ürotelyum gaz değişimi için özelleşmiştir`,B:`Detrusor kası idrar üretimini artırır`,C:`Lamina propria tümörü dışarı taşır`,D:`Ürotelyum esneklik; detrusor boşaltım sağlar`,E:`Muskularis propria filtrasyon yapar`},dogru:`D`,aciklama:`Ürotelyum değişen gerilmeye uyum sağlayan geçiş epiteli olduğundan idrar depolama ve iletiminde esneklik sağlar. Muskularis propria (detrusor) kasılması idrar boşaltımını gerçekleştirir. Bu yapı tümör invazyon derinliğinin ölçütüdür.`,sik_aciklamalari:{A:`Yanlış: Ürotelyum bariyer ve esneklik sağlar, gaz değişimi değil.`,B:`Yanlış: İdrar üretimi böbrekte olur, detrusor boşaltır.`,C:`Yanlış: Lamina propria destek dokusudur, tümör taşımaz.`,D:`Doğru: Geçiş epiteli gerilir, detrusor kasılarak boşaltır.`,E:`Yanlış: Filtrasyon glomerüllerde gerçekleşir.`},bilgi:[1],benzer_cikmis:[]},{id:`k1-46-mesane-hastaliklari-ve-tumorleri-k01-q08`,kazanim:1,zorluk:`kolay`,soru:`Aşağıdakilerden "Retroperitoneal fibrozis nedenleri" ile ilgili doğru olan seçeneği işaretleyiniz.`,secenekler:{A:`IgG4 ilişkili hastalık, maligniteler (lenfoma, ürotelyal karsinom), radyasyon, cerrahi ve bazı ilaçlar (ergot türevleri, adrenerjik blokerler, TNF inhibitörleri) ile ilişkilidir.`,C:`Mesane duvarında mukozanın kese benzeri invajinasyonudur; konjenital (kas tabakasında fokal zayıflık) veya edinilmiş (distal obstrüksiyon: BPH, üretra darlığı) olabilir.`,B:`En sık CYBE grubudur; başlıca etkenler C. trachomatis (en sık), M. genitalium, T. vaginalis ve U. urealyticum'dur.`,E:`Kronik pelvik ağrı ve Hunner ülseri ile seyreder; kültür negatiftir ve daha çok kadınlarda görülür.`,D:`En sık bulgu ağrısız makroskopik veya mikroskopik hematüridir; tanıda sistoskopi + biyopsi ve idrar sitolojisi (özellikle yüksek dereceli ve CIS) kullanılır.`},dogru:`A`,aciklama:`Doğru: IgG4 ilişkili hastalık, maligniteler (lenfoma, ürotelyal karsinom), radyasyon, cerrahi ve bazı ilaçlar (ergot türevleri, adrenerjik blokerler, TNF inhibitörleri) ile ilişkilidir.`,sik_aciklamalari:{A:`Doğru. IgG4 ilişkili hastalık, maligniteler (lenfoma, ürotelyal karsinom), radyasyon, cerrahi ve bazı ilaçlar (ergot türevleri, adrenerjik blokerler, TNF inhibitörleri) ile ilişkilidir.`,C:`Yanlış. Mesane duvarında mukozanın kese benzeri invajinasyonudur; konjenital (kas tabakasında fokal zayıflık) veya edinilmiş (distal obstrüksiyon: BPH, üretra darlığı) olabilir.`,B:`Yanlış. En sık CYBE grubudur; başlıca etkenler C. trachomatis (en sık), M. genitalium, T. vaginalis ve U. urealyticum'dur.`,E:`Yanlış. Kronik pelvik ağrı ve Hunner ülseri ile seyreder; kültür negatiftir ve daha çok kadınlarda görülür.`,D:`Yanlış. En sık bulgu ağrısız makroskopik veya mikroskopik hematüridir; tanıda sistoskopi + biyopsi ve idrar sitolojisi (özellikle yüksek dereceli ve CIS) kullanılır.`},bilgi:[5],benzer_cikmis:[]},{id:`k1-46-mesane-hastaliklari-ve-tumorleri-k01-q09`,kazanim:1,zorluk:`orta`,soru:`"HPV ve kondiloma akuminatum" ile ilgili aşağıdakilerden hangisi yanlıştır?`,secenekler:{D:`HPV genital sistemde kondiloma akuminatum, prekanseröz skuamöz lezyonlar ve karsinomlar (serviks, penis, vulva, orofaringeal tonsil, konjonktiva) yapar. Kondiloma akuminatum etkeni düşük riskli HPV tip 6 ve 11'dir.`,A:`Erkekte en sık koronal sulkus ve sünnet derisi iç yüzünde, kadında genellikle vulva ve perianal bölgede; küçük saplı poliplerden büyük papiller kitlelere kadar değişir. Mikroskopide papiller skuamöz proliferasyon ve koilositoz (perinükleer halo ve hafif nükleer atipi).`,E:`Primer dönemde genitalde spesifik olmayan üretrit, papül veya küçük ülser; sekonder dönemde şiş, hassas ve birleşip fistülize olabilen drenaj lenf düğümleri; uzun dönemde anogenital bölge ve rektumda fibrozis ve darlıklar.`,C:`Kronik pelvik ağrı ve Hunner ülseri ile seyreder; kültür negatiftir ve daha çok kadınlarda görülür.`,B:`Uzun süreli enfeksiyon, taş, kateter ve şistozomiyazis ürotelyumda reaktif değişikliklere ve skuamöz metaplaziye yol açar.`},dogru:`D`,aciklama:`Doğru: HPV genital sistemde kondiloma akuminatum, prekanseröz skuamöz lezyonlar ve karsinomlar (serviks, penis, vulva, orofaringeal tonsil, konjonktiva) yapar. Kondiloma akuminatum etkeni düşük riskli HPV tip 6 ve 11'dir.`,sik_aciklamalari:{D:`Doğru. HPV genital sistemde kondiloma akuminatum, prekanseröz skuamöz lezyonlar ve karsinomlar (serviks, penis, vulva, orofaringeal tonsil, konjonktiva) yapar. Kondiloma akuminatum etkeni düşük riskli HPV tip 6 ve 11'dir.`,A:`Yanlış. Erkekte en sık koronal sulkus ve sünnet derisi iç yüzünde, kadında genellikle vulva ve perianal bölgede; küçük saplı poliplerden büyük papiller kitlelere kadar değişir. Mikroskopide papiller skuamöz proliferasyon ve koilositoz (perinükleer halo ve hafif nükleer atipi).`,E:`Yanlış. Primer dönemde genitalde spesifik olmayan üretrit, papül veya küçük ülser; sekonder dönemde şiş, hassas ve birleşip fistülize olabilen drenaj lenf düğümleri; uzun dönemde anogenital bölge ve rektumda fibrozis ve darlıklar.`,C:`Yanlış. Kronik pelvik ağrı ve Hunner ülseri ile seyreder; kültür negatiftir ve daha çok kadınlarda görülür.`,B:`Yanlış. Uzun süreli enfeksiyon, taş, kateter ve şistozomiyazis ürotelyumda reaktif değişikliklere ve skuamöz metaplaziye yol açar.`},bilgi:[38],benzer_cikmis:[]},{id:`k1-46-mesane-hastaliklari-ve-tumorleri-k01-q10`,kazanim:1,zorluk:`orta`,soru:`"Konjenital sifilis" kavramı hakkında verilen aşağıdakilerden hangisi doğrudur?`,secenekler:{E:`Gebeliğin herhangi bir döneminde plasenta yoluyla bulaşır; intrauterin/perinatal ölüm ~%25 olabilir. Erken form hepatosplenomegali, snuffles, döküntü ve iskelet lezyonları; geç form Hutchinson triadı (interstisyel keratit, Hutchinson dişleri, sinir işitme kaybı).`,B:`Etken Treponema pallidum (spiroket); bulaş erken evre deri/mukoza lezyonlarıyla temasla ve konjenital olarak plasenta yoluyla olur.`,C:`Etken penisiline son derece duyarlıdır. Nontreponemal testler (RPR, VDRL; antikardiyolipin) tedavi izleminde kullanılır ve titre düşer; treponemal testler (T. pallidum spesifik antikor) genellikle ömür boyu pozitif kalır.`,A:`Retroperitoneal yapıları saran fibroinflamatuar doku tablosudur; üreter daralması veya tıkanıklığına yol açabilir; orta-ileri yaşta ve erkeklerde daha sık görülür.`,D:`Enfeksiyondan ortalama 21 gün sonra gelişir; erkekte penis/skrotum (%70), kadında vulva/serviks (~%50) yerleşir; tabanda belirgin indürasyonlu sert şankr oluşur.`},dogru:`E`,aciklama:`Doğru: Gebeliğin herhangi bir döneminde plasenta yoluyla bulaşır; intrauterin/perinatal ölüm ~%25 olabilir. Erken form hepatosplenomegali, snuffles, döküntü ve iskelet lezyonları; geç form Hutchinson triadı (interstisyel keratit, Hutchinson dişleri, sinir işitme kaybı).`,sik_aciklamalari:{E:`Doğru. Gebeliğin herhangi bir döneminde plasenta yoluyla bulaşır; intrauterin/perinatal ölüm ~%25 olabilir. Erken form hepatosplenomegali, snuffles, döküntü ve iskelet lezyonları; geç form Hutchinson triadı (interstisyel keratit, Hutchinson dişleri, sinir işitme kaybı).`,B:`Yanlış. Etken Treponema pallidum (spiroket); bulaş erken evre deri/mukoza lezyonlarıyla temasla ve konjenital olarak plasenta yoluyla olur.`,C:`Yanlış. Etken penisiline son derece duyarlıdır. Nontreponemal testler (RPR, VDRL; antikardiyolipin) tedavi izleminde kullanılır ve titre düşer; treponemal testler (T. pallidum spesifik antikor) genellikle ömür boyu pozitif kalır.`,A:`Yanlış. Retroperitoneal yapıları saran fibroinflamatuar doku tablosudur; üreter daralması veya tıkanıklığına yol açabilir; orta-ileri yaşta ve erkeklerde daha sık görülür.`,D:`Yanlış. Enfeksiyondan ortalama 21 gün sonra gelişir; erkekte penis/skrotum (%70), kadında vulva/serviks (~%50) yerleşir; tabanda belirgin indürasyonlu sert şankr oluşur.`},bilgi:[21],benzer_cikmis:[]},{id:`k1-46-mesane-hastaliklari-ve-tumorleri-k01-q11`,kazanim:1,zorluk:`zor`,soru:`"Sifilisin patognomonik lezyonu" ile ilgili bir hastada bulunacak aşağıdaki bulgulardan hangisi beklenmez?`,secenekler:{C:`Tüm evrelerde proliferatif endarterit ve plazma hücre zengin infiltrat vardır.`,E:`Histolojide yüzeyde nötrofiller ve fibrin kaplı ülser, altta granülasyon dokusu, nekroz ve tromboze damarlar, periferde lenfoplazmasitik infiltrat; lenf nodlarında nekrotizan inflamasyon, apse ve drenaj ülserleri.`,A:`Etken Trichomonas vaginalis (kamçılı protozoon); genellikle cinsel temasla bulaşır. Kadında pruritus, bol köpüklü sarı-yeşil vajinal akıntı, üretral kolonizasyona bağlı dizüri; erkekte genelde hafif üretrit.`,D:`HPV genital sistemde kondiloma akuminatum, prekanseröz skuamöz lezyonlar ve karsinomlar (serviks, penis, vulva, orofaringeal tonsil, konjonktiva) yapar. Kondiloma akuminatum etkeni düşük riskli HPV tip 6 ve 11'dir.`,B:`Mesane kanserlerinin ~%90'ı ürotelyal karsinomdur; majör risk faktörleri sigara, aromatik aminler (boya, kauçuk, tekstil), siklofosfamid ve pelvik radyoterapidir.`},dogru:`C`,aciklama:`Doğru: Tüm evrelerde proliferatif endarterit ve plazma hücre zengin infiltrat vardır.`,sik_aciklamalari:{C:`Doğru. Tüm evrelerde proliferatif endarterit ve plazma hücre zengin infiltrat vardır.`,E:`Yanlış. Histolojide yüzeyde nötrofiller ve fibrin kaplı ülser, altta granülasyon dokusu, nekroz ve tromboze damarlar, periferde lenfoplazmasitik infiltrat; lenf nodlarında nekrotizan inflamasyon, apse ve drenaj ülserleri.`,A:`Yanlış. Etken Trichomonas vaginalis (kamçılı protozoon); genellikle cinsel temasla bulaşır. Kadında pruritus, bol köpüklü sarı-yeşil vajinal akıntı, üretral kolonizasyona bağlı dizüri; erkekte genelde hafif üretrit.`,D:`Yanlış. HPV genital sistemde kondiloma akuminatum, prekanseröz skuamöz lezyonlar ve karsinomlar (serviks, penis, vulva, orofaringeal tonsil, konjonktiva) yapar. Kondiloma akuminatum etkeni düşük riskli HPV tip 6 ve 11'dir.`,B:`Yanlış. Mesane kanserlerinin ~%90'ı ürotelyal karsinomdur; majör risk faktörleri sigara, aromatik aminler (boya, kauçuk, tekstil), siklofosfamid ve pelvik radyoterapidir.`},bilgi:[18],benzer_cikmis:[]}],ilgili_cikmis:[]},{no:2,metin:`Üreter bozukluklarını (UPJ tıkanıklığı, neoplazm, retroperitoneal fibrozis) tanımlayabilmek`,sorular:[{id:`k1-46-q04`,kazanim:2,zorluk:`kolay`,soru:`Bebek ve çocuklarda hidronefrozun en sık nedeni hangisidir?`,secenekler:{A:`Retroperitoneal fibrozis`,B:`Üreteropelvik bileşke (UPJ) tıkanıklığı`,C:`Ürotelyal karsinom`,D:`Benign prostat hiperplazisi`,E:`Strüvit taşı`},dogru:`B`,aciklama:`UPJ tıkanıklığı konjenitaldir; bebek/çocukta hidronefrozun en sık nedenidir ve erkek çocuklarda daha sıktır.`,sik_aciklamalari:{A:`Retroperitoneal fibrozis orta-ileri yaş erişkinlerde görülür.`,B:`Doğru: proksimal basınç artışı pelvis-kaliks dilatasyonu yapar.`,C:`Ürotelyal karsinom erişkin hastalığıdır.`,D:`BPH yaşlı erkeklerde görülür.`,E:`Taşlar çocuklukta hidronefrozun en sık nedeni değildir.`},bilgi:[3],benzer_cikmis:[]},{id:`k1-46-q05`,kazanim:2,zorluk:`orta`,soru:`Retroperitoneal fibrozis ile ilgili aşağıdakilerden hangisi yanlıştır?`,secenekler:{A:`Üreter daralmasına ve hidronefroza yol açabilir`,B:`IgG4 ilişkili hastalık ile ilişkili olabilir`,C:`Ergot türevleri gibi ilaçlar neden olabilir`,D:`Çoğu olgu idiyopatiktir (Ormond hastalığı)`,E:`En sık çocukluk çağında ve kızlarda görülür`},dogru:`E`,aciklama:`Retroperitoneal fibrozis orta-ileri yaşta ve erkeklerde daha sık görülür.`,sik_aciklamalari:{A:`Doğru ifade: üreterleri saran fibrozis obstrüksiyon yapar.`,B:`Doğru ifade: IgG4 ilişkili hastalık nedenlerden biridir.`,C:`Doğru ifade: ergot türevleri, adrenerjik blokerler ve TNF inhibitörleri sayılır.`,D:`Doğru ifade: idiyopatik form Ormond hastalığıdır.`,E:`Yanlış ifade (aranan cevap): erişkin erkeklerde daha sıktır.`},bilgi:[4,5],benzer_cikmis:[]},{id:`k1-46-q06`,kazanim:2,zorluk:`zor`,soru:`Migren nedeniyle uzun süre ergot türevi kullanan 58 yaşında erkekte iki taraflı hidronefroz saptanıyor. Görüntülemede üreterleri saran fibroinflamatuar doku izleniyor.

Bu tabloyla ilgili hangisi doğrudur?`,secenekler:{A:`Üreterin primer skuamöz hücreli karsinomudur`,B:`Konjenital UPJ tıkanıklığıdır`,C:`Retroperitoneal fibrozistir; lenfoma ve ürotelyal karsinom gibi maligniteler de ayırıcı tanıda/etiyolojide yer alır`,D:`İlaç ile ilişkisi yoktur`,E:`Tek taraflı tutulum zorunludur`},dogru:`C`,aciklama:`İlaç (ergot) öyküsü ve üreteri saran fibrozis retroperitoneal fibrozisi düşündürür; malignite ve IgG4 hastalığı da nedenler arasındadır.`,sik_aciklamalari:{A:`Üreter neoplazmları genellikle ürotelyal karsinomdur ve kitle yapar.`,B:`UPJ tıkanıklığı konjenital olup çocuklarda görülür.`,C:`Doğru: retroperitoneal fibrozis obstrüktif üropati ayırıcı tanısındadır.`,D:`Ergot türevleri bilinen ilaç nedenleridir.`,E:`Fibrozis her iki üreteri tutabilir.`},bilgi:[4,5],benzer_cikmis:[]},{id:`k1-46-mesane-hastaliklari-ve-tumorleri-k02-q04`,kazanim:2,zorluk:`orta`,soru:`2 yaşındaki erkek çocukta hidronefroz saptanıyor; obstrüksiyon düzeyi araştırılıyor. Aşağıdakilerden hangisi doğrudur?`,secenekler:{A:`UPJ tıkanıklığı konjenitaldir ve bebek/çocukta hidronefrozun en sık nedenidir; erkek çocuklarda daha sıktır`,B:`Hidronefrozun en sık nedeni mesane taşıdır`,C:`UPJ tıkanıklığı erişkinde sıktır`,D:`Retroperitoneal fibrozis yalnızca çocukta görülür`,E:`Üreter neoplazmları konjenitaldir`},dogru:`A`,aciklama:`UPJ tıkanıklığı bebek/çocuk hidronefrozunun en sık konjenital nedenidir.`,sik_aciklamalari:{A:`Doğru: UPJ tıkanıklığı bebek/çocuk hidronefrozunun en sık konjenital nedenidir.`,B:`Yanlış: bu seçenek vakadaki tabloyla uyumlu değildir; doğru yanıt 'UPJ tıkanıklığı konjenitaldir ve bebek/çocukta hidronefrozun en sık nedenidir; erkek çocuklarda daha sıktır' seçeneğidir.`,C:`Yanlış: bu seçenek vakadaki tabloyla uyumlu değildir; doğru yanıt 'UPJ tıkanıklığı konjenitaldir ve bebek/çocukta hidronefrozun en sık nedenidir; erkek çocuklarda daha sıktır' seçeneğidir.`,D:`Yanlış: bu seçenek vakadaki tabloyla uyumlu değildir; doğru yanıt 'UPJ tıkanıklığı konjenitaldir ve bebek/çocukta hidronefrozun en sık nedenidir; erkek çocuklarda daha sıktır' seçeneğidir.`,E:`Yanlış: bu seçenek vakadaki tabloyla uyumlu değildir; doğru yanıt 'UPJ tıkanıklığı konjenitaldir ve bebek/çocukta hidronefrozun en sık nedenidir; erkek çocuklarda daha sıktır' seçeneğidir.`},bilgi:[2,3],benzer_cikmis:[]},{id:`k1-46-mesane-hastaliklari-ve-tumorleri-k02-q05`,kazanim:2,zorluk:`zor`,soru:`Orta yaşlı erkekte hidronefroz ve retroperitoneal fibrozis düşünülüyor. Aşağıdakilerden hangisi yanlıştır?`,secenekler:{A:`Çoğu olgu idiyopatiktir (Ormond hastalığı)`,B:`IgG4 ilişkili hastalıkla birlikte olabilir`,C:`Retroperitoneal fibrozis üreteri genişletir ve hidronefrozu önler; UPJ tıkanıklığı kızlarda sıktır`,D:`Retroperitoneal fibrozis üreter darlığı/tıkanıklığı yapabilir ve hidronefrozla başvurabilir`,E:`Üreter neoplazmları genellikle ürotelyal karsinomdur`},dogru:`D`,aciklama:`Fibrozis darlık yapar; UPJ erkek çocuklarda sıktır. Son ifade terstir.`,sik_aciklamalari:{A:`Yanlış: bu seçenek vakadaki tabloyla uyumlu değildir; doğru yanıt 'Retroperitoneal fibrozis üreter darlığı/tıkanıklığı yapabilir ve hidronefrozla başvurabilir' seçeneğidir.`,B:`Yanlış: bu seçenek vakadaki tabloyla uyumlu değildir; doğru yanıt 'Retroperitoneal fibrozis üreter darlığı/tıkanıklığı yapabilir ve hidronefrozla başvurabilir' seçeneğidir.`,C:`Yanlış: bu seçenek vakadaki tabloyla uyumlu değildir; doğru yanıt 'Retroperitoneal fibrozis üreter darlığı/tıkanıklığı yapabilir ve hidronefrozla başvurabilir' seçeneğidir.`,D:`Doğru: Fibrozis darlık yapar; UPJ erkek çocuklarda sıktır. Son ifade terstir.`,E:`Yanlış: bu seçenek vakadaki tabloyla uyumlu değildir; doğru yanıt 'Retroperitoneal fibrozis üreter darlığı/tıkanıklığı yapabilir ve hidronefrozla başvurabilir' seçeneğidir.`},bilgi:[2,3,4,5],benzer_cikmis:[]},{id:`k1-46-mesane-hastaliklari-ve-tumorleri-k02-q06`,kazanim:2,zorluk:`orta`,soru:`Üreteropelvik bileşke tıkanıklığının klinik önemi nedir?`,secenekler:{A:`Bebek-çocukta hidronefrozun en sık konjenital nedeni`,B:`Yaşlıda taş düşürmenin en sık nedeni`,C:`Gebelikte fizyolojik hidronefrozun nedeni`,D:`Erişkinde tümör invazyonunun ilk bulgusu`,E:`Kadında sistitin en sık komplikasyonu`},dogru:`A`,aciklama:`Üreteropelvik bileşke tıkanıklığı konjenital bir darlıktır ve bebek-çocukta hidronefrozun en sık nedenidir. Darlık idrar akımını engelleyip pelvis basıncını artırır. Erkek çocuklarda daha sık görülür.`,sik_aciklamalari:{A:`Doğru: UPJ darlığı pediatrik hidronefrozun başlıca nedenidir.`,B:`Yanlış: Taşlar edinilmiş obstrüksiyon nedenidir.`,C:`Yanlış: Gebelik hidronefrozu hormonal ve basısaldir.`,D:`Yanlış: Tümör invazyonu ayrı bir üreter patolojisidir.`,E:`Yanlış: Sistit mesane patolojisidir, UPJ ile ilişkisizdir.`},bilgi:[3],benzer_cikmis:[]},{id:`k1-46-mesane-hastaliklari-ve-tumorleri-k02-q07`,kazanim:2,zorluk:`orta`,soru:`Retroperitoneal fibrozisin üreter üzerindeki etkisi nedir?`,secenekler:{A:`Üreteri genişleten konjenital anomalidir`,B:`Yalnızca enfeksiyonla oluşan geçici ödemdir`,C:`Üreteri saran fibroinflamatuar doku tıkanıklık yapar`,D:`Mesane içinde gelişen benign poliptir`,E:`Böbrek parankiminin primer tümörüdür`},dogru:`C`,aciklama:`Retroperitoneal fibrozis üreterleri saran fibroinflamatuar dokudur ve daralma-tıkanıklığa yol açar. IgG4 ilişkili hastalık, lenfoma, radyasyon ve bazı ilaçlar tetikleyebilir. Orta-ileri yaş erkeklerde daha sıktır.`,sik_aciklamalari:{A:`Yanlış: Fibrozis lümeni daraltır, genişletmez.`,B:`Yanlış: Kronik fibroinflamatuar süreçtir, geçici ödem değildir.`,C:`Doğru: Çevreleyen fibrozis üreteri daraltıp tıkar.`,D:`Yanlış: Retroperitoneal yerleşimlidir, mesane polibi değildir.`,E:`Yanlış: Parankim tümörü değil, üreter çevresi patolojisidir.`},bilgi:[4,5],benzer_cikmis:[]},{id:`k1-46-mesane-hastaliklari-ve-tumorleri-k02-q08`,kazanim:2,zorluk:`kolay`,soru:`"Klamidya komplikasyonları ve tanısı" kavramının tanımı aşağıdakilerden hangisidir?`,secenekler:{B:`Erkekte epididimit ve prostatit; kadında infertilite ve ektopik gebelik; yenidoğanda konjonktivit ve pnömoni (vajinal doğumda bulaş).`,D:`Semptomatik olguda ağrılı vezikül/ülserler, dizüri, akıntı, lenfadenopati, ateş ve miyalji; histolojide intraepitelyal veziküller, Cowdry tip A intranükleer inklüzyon ve çok çekirdekli dev hücreler.`,C:`Primer dönemde genitalde spesifik olmayan üretrit, papül veya küçük ülser; sekonder dönemde şiş, hassas ve birleşip fistülize olabilen drenaj lenf düğümleri; uzun dönemde anogenital bölge ve rektumda fibrozis ve darlıklar.`,A:`Etken Trichomonas vaginalis (kamçılı protozoon); genellikle cinsel temasla bulaşır. Kadında pruritus, bol köpüklü sarı-yeşil vajinal akıntı, üretral kolonizasyona bağlı dizüri; erkekte genelde hafif üretrit.`,E:`Erkekte üretrit (dizüri, sık idrara çıkma, mukopürülan akıntı), kadında çoğu zaman asemptomatik seyir; tedavi edilmezse PID, infertilite ve ektopik gebelik gelişir.`},dogru:`B`,aciklama:`Doğru: Erkekte epididimit ve prostatit; kadında infertilite ve ektopik gebelik; yenidoğanda konjonktivit ve pnömoni (vajinal doğumda bulaş).`,sik_aciklamalari:{B:`Doğru. Erkekte epididimit ve prostatit; kadında infertilite ve ektopik gebelik; yenidoğanda konjonktivit ve pnömoni (vajinal doğumda bulaş).`,D:`Yanlış. Semptomatik olguda ağrılı vezikül/ülserler, dizüri, akıntı, lenfadenopati, ateş ve miyalji; histolojide intraepitelyal veziküller, Cowdry tip A intranükleer inklüzyon ve çok çekirdekli dev hücreler.`,C:`Yanlış. Primer dönemde genitalde spesifik olmayan üretrit, papül veya küçük ülser; sekonder dönemde şiş, hassas ve birleşip fistülize olabilen drenaj lenf düğümleri; uzun dönemde anogenital bölge ve rektumda fibrozis ve darlıklar.`,A:`Yanlış. Etken Trichomonas vaginalis (kamçılı protozoon); genellikle cinsel temasla bulaşır. Kadında pruritus, bol köpüklü sarı-yeşil vajinal akıntı, üretral kolonizasyona bağlı dizüri; erkekte genelde hafif üretrit.`,E:`Yanlış. Erkekte üretrit (dizüri, sık idrara çıkma, mukopürülan akıntı), kadında çoğu zaman asemptomatik seyir; tedavi edilmezse PID, infertilite ve ektopik gebelik gelişir.`},bilgi:[28],benzer_cikmis:[]},{id:`k1-46-mesane-hastaliklari-ve-tumorleri-k02-q09`,kazanim:2,zorluk:`orta`,soru:`"Skuamöz hücreli karsinom patogenezi" ile ilgili eşleştirmelerden hangisi doğrudur?`,secenekler:{C:`Endemik şistozomiyazis bölgelerinde kronik sistit, skuamöz metaplazi ve skuamöz hücreli karsinom insidansı artar; patogenez kronik inflamasyon + metaplazi → displazi → karsinomdur.`,D:`Mesane mukozasının inflamasyonudur; etiyolojisi çoğunlukla bakteriyeldir, ayrıca kimyasal (ilaç), radyasyon, cihaz ve otoimmün nedenler olabilir.`,E:`Etken Neisseria gonorrhoeae (Gram negatif diplokok); Chlamydia trachomatis'ten sonra ikinci sık bakteriyel CYBE'dir; cinsel temasla ve enfekte mukozaya doğrudan temasla bulaşır.`,B:`Vajinal kazıntıdan ıslak preparatta hareketli organizmanın gösterilmesiyle konur; genellikle eşzamanlı klamidya ve gonore testleri yapılır.`,A:`En sık bulgu ağrısız makroskopik veya mikroskopik hematüridir; tanıda sistoskopi + biyopsi ve idrar sitolojisi (özellikle yüksek dereceli ve CIS) kullanılır.`},dogru:`C`,aciklama:`Doğru: Endemik şistozomiyazis bölgelerinde kronik sistit, skuamöz metaplazi ve skuamöz hücreli karsinom insidansı artar; patogenez kronik inflamasyon + metaplazi → displazi → karsinomdur.`,sik_aciklamalari:{C:`Doğru. Endemik şistozomiyazis bölgelerinde kronik sistit, skuamöz metaplazi ve skuamöz hücreli karsinom insidansı artar; patogenez kronik inflamasyon + metaplazi → displazi → karsinomdur.`,D:`Yanlış. Mesane mukozasının inflamasyonudur; etiyolojisi çoğunlukla bakteriyeldir, ayrıca kimyasal (ilaç), radyasyon, cihaz ve otoimmün nedenler olabilir.`,E:`Yanlış. Etken Neisseria gonorrhoeae (Gram negatif diplokok); Chlamydia trachomatis'ten sonra ikinci sık bakteriyel CYBE'dir; cinsel temasla ve enfekte mukozaya doğrudan temasla bulaşır.`,B:`Yanlış. Vajinal kazıntıdan ıslak preparatta hareketli organizmanın gösterilmesiyle konur; genellikle eşzamanlı klamidya ve gonore testleri yapılır.`,A:`Yanlış. En sık bulgu ağrısız makroskopik veya mikroskopik hematüridir; tanıda sistoskopi + biyopsi ve idrar sitolojisi (özellikle yüksek dereceli ve CIS) kullanılır.`},bilgi:[13],benzer_cikmis:[]},{id:`k1-46-mesane-hastaliklari-ve-tumorleri-k02-q10`,kazanim:2,zorluk:`orta`,soru:`"Lenfogranüloma venereum (LGV)" kavramı hakkında verilen aşağıdakilerden hangisi doğrudur?`,secenekler:{B:`C. trachomatis'in farklı (L1-L3) serovarlarına bağlı kronik, ülseratif CYBE; özellikle erkeklerle cinsel ilişkiye giren erkeklerde kasık lenfadenopatisi ve proktit görülür, HIV koinfeksiyonuyla güçlü ilişkilidir.`,E:`Erkekte üretrit (dizüri, sık idrara çıkma, mukopürülan akıntı), kadında çoğu zaman asemptomatik seyir; tedavi edilmezse PID, infertilite ve ektopik gebelik gelişir.`,A:`Etken Treponema pallidum (spiroket); bulaş erken evre deri/mukoza lezyonlarıyla temasla ve konjenital olarak plasenta yoluyla olur.`,C:`Endemik şistozomiyazis bölgelerinde kronik sistit, skuamöz metaplazi ve skuamöz hücreli karsinom insidansı artar; patogenez kronik inflamasyon + metaplazi → displazi → karsinomdur.`,D:`Konjenital bozukluktur; bebek/çocukta hidronefrozun en sık nedenidir ve erkek çocuklarda daha sık görülür.`},dogru:`B`,aciklama:`Doğru: C. trachomatis'in farklı (L1-L3) serovarlarına bağlı kronik, ülseratif CYBE; özellikle erkeklerle cinsel ilişkiye giren erkeklerde kasık lenfadenopatisi ve proktit görülür, HIV koinfeksiyonuyla güçlü ilişkilidir.`,sik_aciklamalari:{B:`Doğru. C. trachomatis'in farklı (L1-L3) serovarlarına bağlı kronik, ülseratif CYBE; özellikle erkeklerle cinsel ilişkiye giren erkeklerde kasık lenfadenopatisi ve proktit görülür, HIV koinfeksiyonuyla güçlü ilişkilidir.`,E:`Yanlış. Erkekte üretrit (dizüri, sık idrara çıkma, mukopürülan akıntı), kadında çoğu zaman asemptomatik seyir; tedavi edilmezse PID, infertilite ve ektopik gebelik gelişir.`,A:`Yanlış. Etken Treponema pallidum (spiroket); bulaş erken evre deri/mukoza lezyonlarıyla temasla ve konjenital olarak plasenta yoluyla olur.`,C:`Yanlış. Endemik şistozomiyazis bölgelerinde kronik sistit, skuamöz metaplazi ve skuamöz hücreli karsinom insidansı artar; patogenez kronik inflamasyon + metaplazi → displazi → karsinomdur.`,D:`Yanlış. Konjenital bozukluktur; bebek/çocukta hidronefrozun en sık nedenidir ve erkek çocuklarda daha sık görülür.`},bilgi:[29],benzer_cikmis:[]},{id:`k1-46-mesane-hastaliklari-ve-tumorleri-k02-q11`,kazanim:2,zorluk:`zor`,soru:`"Sistit tanımı ve sıklığı" bilgisini içeren doğru kurulum aşağıdakilerden hangisidir?`,secenekler:{D:`Mesane mukozasının inflamasyonudur; etiyolojisi çoğunlukla bakteriyeldir, ayrıca kimyasal (ilaç), radyasyon, cihaz ve otoimmün nedenler olabilir.`,C:`Erkekte en sık koronal sulkus ve sünnet derisi iç yüzünde, kadında genellikle vulva ve perianal bölgede; küçük saplı poliplerden büyük papiller kitlelere kadar değişir. Mikroskopide papiller skuamöz proliferasyon ve koilositoz (perinükleer halo ve hafif nükleer atipi).`,B:`Etken Trichomonas vaginalis (kamçılı protozoon); genellikle cinsel temasla bulaşır. Kadında pruritus, bol köpüklü sarı-yeşil vajinal akıntı, üretral kolonizasyona bağlı dizüri; erkekte genelde hafif üretrit.`,E:`Düşük dereceli papiller yol FGFR3 ve HRAS ile; yüksek dereceli CIS-invaziv yol TP53 ve RB ile ilişkilidir.`,A:`Gebeliğin herhangi bir döneminde plasenta yoluyla bulaşır; intrauterin/perinatal ölüm ~%25 olabilir. Erken form hepatosplenomegali, snuffles, döküntü ve iskelet lezyonları; geç form Hutchinson triadı (interstisyel keratit, Hutchinson dişleri, sinir işitme kaybı).`},dogru:`D`,aciklama:`Doğru: Mesane mukozasının inflamasyonudur; etiyolojisi çoğunlukla bakteriyeldir, ayrıca kimyasal (ilaç), radyasyon, cihaz ve otoimmün nedenler olabilir.`,sik_aciklamalari:{D:`Doğru. Mesane mukozasının inflamasyonudur; etiyolojisi çoğunlukla bakteriyeldir, ayrıca kimyasal (ilaç), radyasyon, cihaz ve otoimmün nedenler olabilir.`,C:`Yanlış. Erkekte en sık koronal sulkus ve sünnet derisi iç yüzünde, kadında genellikle vulva ve perianal bölgede; küçük saplı poliplerden büyük papiller kitlelere kadar değişir. Mikroskopide papiller skuamöz proliferasyon ve koilositoz (perinükleer halo ve hafif nükleer atipi).`,B:`Yanlış. Etken Trichomonas vaginalis (kamçılı protozoon); genellikle cinsel temasla bulaşır. Kadında pruritus, bol köpüklü sarı-yeşil vajinal akıntı, üretral kolonizasyona bağlı dizüri; erkekte genelde hafif üretrit.`,E:`Yanlış. Düşük dereceli papiller yol FGFR3 ve HRAS ile; yüksek dereceli CIS-invaziv yol TP53 ve RB ile ilişkilidir.`,A:`Yanlış. Gebeliğin herhangi bir döneminde plasenta yoluyla bulaşır; intrauterin/perinatal ölüm ~%25 olabilir. Erken form hepatosplenomegali, snuffles, döküntü ve iskelet lezyonları; geç form Hutchinson triadı (interstisyel keratit, Hutchinson dişleri, sinir işitme kaybı).`},bilgi:[8],benzer_cikmis:[]}],ilgili_cikmis:[]},{no:3,metin:`Mesane divertiküllerinin nedenlerini ve klinik önemini bilmek`,sorular:[{id:`k1-46-q07`,kazanim:3,zorluk:`kolay`,soru:`Mesane divertikülü aşağıdakilerden hangisini tanımlar?`,secenekler:{A:`Mesane mukozasının inflamasyonu`,B:`Mesane duvarında mukozanın kese benzeri invajinasyonu`,C:`Ürotelyumun skuamöz metaplazisi`,D:`Mesanede papiller tümör`,E:`Mesanede kalsiyum içeren makrofaj birikimi`},dogru:`B`,aciklama:`Divertikül, mesane duvarında mukozanın dışa doğru kese benzeri çıkıntısıdır.`,sik_aciklamalari:{A:`Mukoza inflamasyonu sistittir.`,B:`Doğru: divertikülün tanımıdır.`,C:`Skuamöz metaplazi kronik irritasyon sonucu gelişir.`,D:`Papiller tümör ürotelyal neoplazmdır.`,E:`Bu tanım malakoplakiyi çağrıştırır, divertikül değildir.`},bilgi:[6],benzer_cikmis:[]},{id:`k1-46-q08`,kazanim:3,zorluk:`orta`,soru:`Edinilmiş mesane divertikülünün en sık nedeni hangisidir?`,secenekler:{A:`HPV enfeksiyonu`,B:`Kas tabakasında doğuştan fokal zayıflık`,C:`Hemorajik sistit`,D:`Benign prostat hiperplazisi gibi distal obstrüksiyon`,E:`Ürotelyal karsinom`},dogru:`D`,aciklama:`Edinilmiş divertiküller BPH veya üretra darlığı gibi distal obstrüksiyona bağlı artan basınçla oluşur.`,sik_aciklamalari:{A:`HPV kondiloma ve karsinom ile ilişkilidir.`,B:`Kas tabakasında fokal zayıflık konjenital divertikül nedenidir.`,C:`Hemorajik sistit divertikül nedeni değildir.`,D:`Doğru: distal obstrüksiyon duvar zayıf noktalarından fıtıklaşmaya yol açar.`,E:`Ürotelyal karsinom divertikül nedeni değildir, nadiren divertikülde gelişir.`},bilgi:[6],benzer_cikmis:[]},{id:`k1-46-q09`,kazanim:3,zorluk:`zor`,soru:`Büyük mesane divertikülü olan hastada aşağıdaki komplikasyonlardan hangisinin gelişmesi beklenmez?`,secenekler:{A:`Tekrarlayan idrar yolu enfeksiyonu`,B:`Taş oluşumu`,C:`Nadiren divertikül içinde tümör gelişimi`,D:`İşeme sonrası dolgunluk hissi`,E:`Hiperkalsemiye bağlı nefrokalsinozis`},dogru:`E`,aciklama:`Divertikül içi idrar stazı enfeksiyon, taş ve nadiren tümöre zemin hazırlar; büyük divertiküller işeme sonrası dolgunluk verir.`,sik_aciklamalari:{A:`Beklenir: staz bakteri çoğalmasını kolaylaştırır.`,B:`Beklenir: staz kristalizasyonu artırır.`,C:`Beklenir: nadiren tümör gelişebilir.`,D:`Beklenir: divertikülde kalan idrar dolgunluk hissi yapar.`,E:`Doğru (beklenmez): nefrokalsinozis divertikül komplikasyonu değildir.`},bilgi:[7],benzer_cikmis:[]},{id:`k1-46-mesane-hastaliklari-ve-tumorleri-k03-q04`,kazanim:3,zorluk:`orta`,soru:`BPH'li yaşlı hastada mesane duvarında kese benzeri çıkıntı ve tekrarlayan İYE var. Aşağıdakilerden hangisi doğrudur?`,secenekler:{A:`Divertikül yalnızca maligndir`,B:`Konjenital divertikül obstrüksiyona bağlıdır`,C:`Edinilmiş divertikül distal obstrüksiyona (BPH, üretra darlığı) bağlıdır; idrar stazı tekrarlayan enfeksiyon, taş ve nadiren tümöre yol açar`,D:`Divertikül içi staz koruyucudur`,E:`Divertiküller idrar içermez`},dogru:`C`,aciklama:`Edinilmiş form distal obstrüksiyon sonucudur; staz enfeksiyon/taş/nadiren tümör getirir.`,sik_aciklamalari:{A:`Yanlış: bu seçenek vakadaki tabloyla uyumlu değildir; doğru yanıt 'Edinilmiş divertikül distal obstrüksiyona (BPH, üretra darlığı) bağlıdır; idrar stazı tekrarlayan enfeksiyon, taş ve nadiren tümöre yol açar' seçeneğidir.`,B:`Yanlış: bu seçenek vakadaki tabloyla uyumlu değildir; doğru yanıt 'Edinilmiş divertikül distal obstrüksiyona (BPH, üretra darlığı) bağlıdır; idrar stazı tekrarlayan enfeksiyon, taş ve nadiren tümöre yol açar' seçeneğidir.`,C:`Doğru: Edinilmiş form distal obstrüksiyon sonucudur; staz enfeksiyon/taş/nadiren tümör getirir.`,D:`Yanlış: bu seçenek vakadaki tabloyla uyumlu değildir; doğru yanıt 'Edinilmiş divertikül distal obstrüksiyona (BPH, üretra darlığı) bağlıdır; idrar stazı tekrarlayan enfeksiyon, taş ve nadiren tümöre yol açar' seçeneğidir.`,E:`Yanlış: bu seçenek vakadaki tabloyla uyumlu değildir; doğru yanıt 'Edinilmiş divertikül distal obstrüksiyona (BPH, üretra darlığı) bağlıdır; idrar stazı tekrarlayan enfeksiyon, taş ve nadiren tümöre yol açar' seçeneğidir.`},bilgi:[6,7],benzer_cikmis:[]},{id:`k1-46-mesane-hastaliklari-ve-tumorleri-k03-q05`,kazanim:3,zorluk:`zor`,soru:`Küçük asemptomatik divertikül izleniyor. Aşağıdakilerden hangisi yanlıştır?`,secenekler:{A:`Konjenital formda kas tabakasında fokal zayıflık vardır`,B:`Çoğu divertikül küçük ve asemptomatiktir`,C:`Staz tekrarlayan İYE ve taş yapabilir`,D:`Divertikül içi staz tümör riskini artırır ve taş enfeksiyonu önler; divertiküller hep semptomatiktir`,E:`Büyük divertikül işeme sonrası dolgunluk verebilir`},dogru:`B`,aciklama:`Çoğu asemptomatiktir; staz riski artırır, önlemez. Son ifade yanlıştır.`,sik_aciklamalari:{A:`Yanlış: bu seçenek vakadaki tabloyla uyumlu değildir; doğru yanıt 'Çoğu divertikül küçük ve asemptomatiktir' seçeneğidir.`,B:`Doğru: Çoğu asemptomatiktir; staz riski artırır, önlemez. Son ifade yanlıştır.`,C:`Yanlış: bu seçenek vakadaki tabloyla uyumlu değildir; doğru yanıt 'Çoğu divertikül küçük ve asemptomatiktir' seçeneğidir.`,D:`Yanlış: bu seçenek vakadaki tabloyla uyumlu değildir; doğru yanıt 'Çoğu divertikül küçük ve asemptomatiktir' seçeneğidir.`,E:`Yanlış: bu seçenek vakadaki tabloyla uyumlu değildir; doğru yanıt 'Çoğu divertikül küçük ve asemptomatiktir' seçeneğidir.`},bilgi:[6,7],benzer_cikmis:[]},{id:`k1-46-mesane-hastaliklari-ve-tumorleri-k03-q06`,kazanim:3,zorluk:`orta`,soru:`Mesane divertiküllerinin temel oluşum mekanizmaları hangileridir?`,secenekler:{A:`Yalnızca malignite zemininde gelişir`,B:`Hep üreter orifisinde doğuştan bulunur`,C:`Düşük basınç mukozayı içeri çeker`,D:`Detrusor hipertrofisi divertikülü kapatır`,E:`Kas zayıflığı veya distal obstrüksiyondan gelişir`},dogru:`E`,aciklama:`Mesane divertikülü mukozanın kese benzeri invajinasyonudur. Konjenital form kas tabakasındaki fokal zayıflıktan, edinilmiş form distal obstrüksiyondan (BPH, üretra darlığı) kaynaklanır. Artmış intravezikal basınç mukozayı zayıf noktadan dışarı iter.`,sik_aciklamalari:{A:`Yanlış: Divertiküller genellikle benign mekanik nedenlidir.`,B:`Yanlış: Her yerde gelişebilir, orifise özgü değildir.`,C:`Yanlış: Yüksek basınç mukozayı dışarı doğru iter.`,D:`Yanlış: Hipertrofi basıncı artırarak oluşumu kolaylaştırır.`,E:`Doğru: Fokal kas zayıflığı veya çıkış obstrüksiyonu nedendir.`},bilgi:[6],benzer_cikmis:[]},{id:`k1-46-mesane-hastaliklari-ve-tumorleri-k03-q07`,kazanim:3,zorluk:`orta`,soru:`Mesane divertikülünün yol açtığı klinik sorunlar hangileridir?`,secenekler:{A:`İdrar akımını hızlandırarak korur`,B:`Stazla enfeksiyon, taş ve tümöre zemin hazırlar`,C:`Mesane kapasitesini artırarak inkontinansı önler`,D:`Bakteri üremesini tamamen engeller`,E:`Taş oluşumunu kimyasal olarak çözer`},dogru:`B`,aciklama:`Divertikül kesesinde idrar stazı olur; durgun idrar bakteri üremesini, taş oluşumunu kolaylaştırır ve nadiren tümör gelişimine zemin hazırlar. Kese kas içermediği için tam boşalamaz. Bu nedenle tekrarlayan enfeksiyonlarda divertikül araştırılır.`,sik_aciklamalari:{A:`Yanlış: Kasede idrar göllenir, akım yavaşlar.`,B:`Doğru: Staz enfeksiyon, taş ve nadiren tümöre yol açar.`,C:`Yanlış: Divertikül fonksiyonel kapasiteye katkı sağlamaz.`,D:`Yanlış: Durgun idrar bakteri üremesini kolaylaştırır.`,E:`Yanlış: Staz taş oluşumunu artırır, çözmez.`},bilgi:[7],benzer_cikmis:[]},{id:`k1-46-mesane-hastaliklari-ve-tumorleri-k03-q08`,kazanim:3,zorluk:`kolay`,soru:`"Trichomoniasis tanısı" ifadesi ile ilgili aşağıdakilerden hangisi doğrudur?`,secenekler:{D:`Vajinal kazıntıdan ıslak preparatta hareketli organizmanın gösterilmesiyle konur; genellikle eşzamanlı klamidya ve gonore testleri yapılır.`,E:`IgG4 ilişkili hastalık, maligniteler (lenfoma, ürotelyal karsinom), radyasyon, cerrahi ve bazı ilaçlar (ergot türevleri, adrenerjik blokerler, TNF inhibitörleri) ile ilişkilidir.`,C:`Sekonder şankr iyileşmesinden ~2 ay sonra döküntü, mukokutanöz lezyonlar ve lenfadenopati ile; kondiloma lata anogenital bölgede geniş tabanlı kabarık lezyonlardır. Tersiyer yıllar sonra (5-20 yıl) kardiyovasküler sifilis, nörosifilis ve gumma ile seyreder.`,B:`C. trachomatis'in farklı (L1-L3) serovarlarına bağlı kronik, ülseratif CYBE; özellikle erkeklerle cinsel ilişkiye giren erkeklerde kasık lenfadenopatisi ve proktit görülür, HIV koinfeksiyonuyla güçlü ilişkilidir.`,A:`Konjenital bozukluktur; bebek/çocukta hidronefrozun en sık nedenidir ve erkek çocuklarda daha sık görülür.`},dogru:`D`,aciklama:`Doğru: Vajinal kazıntıdan ıslak preparatta hareketli organizmanın gösterilmesiyle konur; genellikle eşzamanlı klamidya ve gonore testleri yapılır.`,sik_aciklamalari:{D:`Doğru. Vajinal kazıntıdan ıslak preparatta hareketli organizmanın gösterilmesiyle konur; genellikle eşzamanlı klamidya ve gonore testleri yapılır.`,E:`Yanlış. IgG4 ilişkili hastalık, maligniteler (lenfoma, ürotelyal karsinom), radyasyon, cerrahi ve bazı ilaçlar (ergot türevleri, adrenerjik blokerler, TNF inhibitörleri) ile ilişkilidir.`,C:`Yanlış. Sekonder şankr iyileşmesinden ~2 ay sonra döküntü, mukokutanöz lezyonlar ve lenfadenopati ile; kondiloma lata anogenital bölgede geniş tabanlı kabarık lezyonlardır. Tersiyer yıllar sonra (5-20 yıl) kardiyovasküler sifilis, nörosifilis ve gumma ile seyreder.`,B:`Yanlış. C. trachomatis'in farklı (L1-L3) serovarlarına bağlı kronik, ülseratif CYBE; özellikle erkeklerle cinsel ilişkiye giren erkeklerde kasık lenfadenopatisi ve proktit görülür, HIV koinfeksiyonuyla güçlü ilişkilidir.`,A:`Yanlış. Konjenital bozukluktur; bebek/çocukta hidronefrozun en sık nedenidir ve erkek çocuklarda daha sık görülür.`},bilgi:[34],benzer_cikmis:[]},{id:`k1-46-mesane-hastaliklari-ve-tumorleri-k03-q09`,kazanim:3,zorluk:`orta`,soru:`"Sifilis etken ve bulaş" kavramı hakkında verilen aşağıdakilerden hangisi doğrudur?`,secenekler:{A:`Etken Treponema pallidum (spiroket); bulaş erken evre deri/mukoza lezyonlarıyla temasla ve konjenital olarak plasenta yoluyla olur.`,D:`Erkekte en sık koronal sulkus ve sünnet derisi iç yüzünde, kadında genellikle vulva ve perianal bölgede; küçük saplı poliplerden büyük papiller kitlelere kadar değişir. Mikroskopide papiller skuamöz proliferasyon ve koilositoz (perinükleer halo ve hafif nükleer atipi).`,E:`Semptomatik olguda ağrılı vezikül/ülserler, dizüri, akıntı, lenfadenopati, ateş ve miyalji; histolojide intraepitelyal veziküller, Cowdry tip A intranükleer inklüzyon ve çok çekirdekli dev hücreler.`,B:`Gebeliğin herhangi bir döneminde plasenta yoluyla bulaşır; intrauterin/perinatal ölüm ~%25 olabilir. Erken form hepatosplenomegali, snuffles, döküntü ve iskelet lezyonları; geç form Hutchinson triadı (interstisyel keratit, Hutchinson dişleri, sinir işitme kaybı).`,C:`Dört veya dokuz değerliklidir; düşük riskli tip 6 ve 11'e karşı koruma sağlar, anogenital siğilleri önler ve HPV ilişkili karsinom insidansını (özellikle serviks) azaltır.`},dogru:`A`,aciklama:`Doğru: Etken Treponema pallidum (spiroket); bulaş erken evre deri/mukoza lezyonlarıyla temasla ve konjenital olarak plasenta yoluyla olur.`,sik_aciklamalari:{A:`Doğru. Etken Treponema pallidum (spiroket); bulaş erken evre deri/mukoza lezyonlarıyla temasla ve konjenital olarak plasenta yoluyla olur.`,D:`Yanlış. Erkekte en sık koronal sulkus ve sünnet derisi iç yüzünde, kadında genellikle vulva ve perianal bölgede; küçük saplı poliplerden büyük papiller kitlelere kadar değişir. Mikroskopide papiller skuamöz proliferasyon ve koilositoz (perinükleer halo ve hafif nükleer atipi).`,E:`Yanlış. Semptomatik olguda ağrılı vezikül/ülserler, dizüri, akıntı, lenfadenopati, ateş ve miyalji; histolojide intraepitelyal veziküller, Cowdry tip A intranükleer inklüzyon ve çok çekirdekli dev hücreler.`,B:`Yanlış. Gebeliğin herhangi bir döneminde plasenta yoluyla bulaşır; intrauterin/perinatal ölüm ~%25 olabilir. Erken form hepatosplenomegali, snuffles, döküntü ve iskelet lezyonları; geç form Hutchinson triadı (interstisyel keratit, Hutchinson dişleri, sinir işitme kaybı).`,C:`Yanlış. Dört veya dokuz değerliklidir; düşük riskli tip 6 ve 11'e karşı koruma sağlar, anogenital siğilleri önler ve HPV ilişkili karsinom insidansını (özellikle serviks) azaltır.`},bilgi:[17],benzer_cikmis:[]},{id:`k1-46-mesane-hastaliklari-ve-tumorleri-k03-q10`,kazanim:3,zorluk:`orta`,soru:`"Gonore etken ve bulaş" kavramı hakkında verilen aşağıdakilerden hangisi doğrudur?`,secenekler:{E:`Etken Neisseria gonorrhoeae (Gram negatif diplokok); Chlamydia trachomatis'ten sonra ikinci sık bakteriyel CYBE'dir; cinsel temasla ve enfekte mukozaya doğrudan temasla bulaşır.`,A:`HPV genital sistemde kondiloma akuminatum, prekanseröz skuamöz lezyonlar ve karsinomlar (serviks, penis, vulva, orofaringeal tonsil, konjonktiva) yapar. Kondiloma akuminatum etkeni düşük riskli HPV tip 6 ve 11'dir.`,C:`Siklofosfamidin akrolein metaboliti ve adenovirus enfeksiyonları ile ilişkilidir.`,B:`En sık bulgu ağrısız makroskopik veya mikroskopik hematüridir; tanıda sistoskopi + biyopsi ve idrar sitolojisi (özellikle yüksek dereceli ve CIS) kullanılır.`,D:`IgG4 ilişkili hastalık, maligniteler (lenfoma, ürotelyal karsinom), radyasyon, cerrahi ve bazı ilaçlar (ergot türevleri, adrenerjik blokerler, TNF inhibitörleri) ile ilişkilidir.`},dogru:`E`,aciklama:`Doğru: Etken Neisseria gonorrhoeae (Gram negatif diplokok); Chlamydia trachomatis'ten sonra ikinci sık bakteriyel CYBE'dir; cinsel temasla ve enfekte mukozaya doğrudan temasla bulaşır.`,sik_aciklamalari:{E:`Doğru. Etken Neisseria gonorrhoeae (Gram negatif diplokok); Chlamydia trachomatis'ten sonra ikinci sık bakteriyel CYBE'dir; cinsel temasla ve enfekte mukozaya doğrudan temasla bulaşır.`,A:`Yanlış. HPV genital sistemde kondiloma akuminatum, prekanseröz skuamöz lezyonlar ve karsinomlar (serviks, penis, vulva, orofaringeal tonsil, konjonktiva) yapar. Kondiloma akuminatum etkeni düşük riskli HPV tip 6 ve 11'dir.`,C:`Yanlış. Siklofosfamidin akrolein metaboliti ve adenovirus enfeksiyonları ile ilişkilidir.`,B:`Yanlış. En sık bulgu ağrısız makroskopik veya mikroskopik hematüridir; tanıda sistoskopi + biyopsi ve idrar sitolojisi (özellikle yüksek dereceli ve CIS) kullanılır.`,D:`Yanlış. IgG4 ilişkili hastalık, maligniteler (lenfoma, ürotelyal karsinom), radyasyon, cerrahi ve bazı ilaçlar (ergot türevleri, adrenerjik blokerler, TNF inhibitörleri) ile ilişkilidir.`},bilgi:[23],benzer_cikmis:[]},{id:`k1-46-mesane-hastaliklari-ve-tumorleri-k03-q11`,kazanim:3,zorluk:`zor`,soru:`"Kronik irritasyon ve metaplezi" bilgisini içeren doğru kurulum aşağıdakilerden hangisidir?`,secenekler:{B:`Uzun süreli enfeksiyon, taş, kateter ve şistozomiyazis ürotelyumda reaktif değişikliklere ve skuamöz metaplaziye yol açar.`,A:`Mesane kanserlerinin ~%90'ı ürotelyal karsinomdur; majör risk faktörleri sigara, aromatik aminler (boya, kauçuk, tekstil), siklofosfamid ve pelvik radyoterapidir.`,E:`Etken Haemophilus ducreyi (Gram negatif kokobasil); 4-7 gün inkübasyondan sonra dış genitalde papül hızla ağrılı ülsere dönüşür, çoklu ülserler sıktır ve sert indürasyon yoktur.`,D:`Konjenital bozukluktur; bebek/çocukta hidronefrozun en sık nedenidir ve erkek çocuklarda daha sık görülür.`,C:`En sık bulgu ağrısız makroskopik veya mikroskopik hematüridir; tanıda sistoskopi + biyopsi ve idrar sitolojisi (özellikle yüksek dereceli ve CIS) kullanılır.`},dogru:`B`,aciklama:`Doğru: Uzun süreli enfeksiyon, taş, kateter ve şistozomiyazis ürotelyumda reaktif değişikliklere ve skuamöz metaplaziye yol açar.`,sik_aciklamalari:{B:`Doğru. Uzun süreli enfeksiyon, taş, kateter ve şistozomiyazis ürotelyumda reaktif değişikliklere ve skuamöz metaplaziye yol açar.`,A:`Yanlış. Mesane kanserlerinin ~%90'ı ürotelyal karsinomdur; majör risk faktörleri sigara, aromatik aminler (boya, kauçuk, tekstil), siklofosfamid ve pelvik radyoterapidir.`,E:`Yanlış. Etken Haemophilus ducreyi (Gram negatif kokobasil); 4-7 gün inkübasyondan sonra dış genitalde papül hızla ağrılı ülsere dönüşür, çoklu ülserler sıktır ve sert indürasyon yoktur.`,D:`Yanlış. Konjenital bozukluktur; bebek/çocukta hidronefrozun en sık nedenidir ve erkek çocuklarda daha sık görülür.`,C:`Yanlış. En sık bulgu ağrısız makroskopik veya mikroskopik hematüridir; tanıda sistoskopi + biyopsi ve idrar sitolojisi (özellikle yüksek dereceli ve CIS) kullanılır.`},bilgi:[12],benzer_cikmis:[]}],ilgili_cikmis:[]},{no:4,metin:`Sistit tiplerini ve özelliklerini ayırt edebilmek`,sorular:[{id:`k1-46-q10`,kazanim:4,zorluk:`kolay`,soru:`Akut bakteriyel sistitin en sık etkeni hangisidir?`,secenekler:{A:`Schistosoma haematobium`,B:`Adenovirus`,C:`Escherichia coli`,D:`Treponema pallidum`,E:`Candida albicans`},dogru:`C`,aciklama:`Akut bakteriyel sistitte en sık etkenler E. coli başta olmak üzere koliformlar, Proteus, Klebsiella ve Enterobacter'dir.`,sik_aciklamalari:{A:`Şistozomiyazis kronik sistit ve skuamöz karsinomla ilişkilidir.`,B:`Adenovirus hemorajik sistitle ilişkilidir.`,C:`Doğru: E. coli en sık etkendir.`,D:`T. pallidum sifilis etkenidir.`,E:`Kandida nadir ve fırsatçı bir etkendir.`},bilgi:[9],benzer_cikmis:[]},{id:`k1-46-q11`,kazanim:4,zorluk:`orta`,soru:`Siklofosfamid tedavisi alan hastada gelişen kanlı idrar ve dizüri tablosunun en olası nedeni hangisidir?`,secenekler:{A:`Malakoplaki`,B:`İnterstisyel sistit`,C:`Gonokokal üretrit`,D:`Akrolein metabolitine bağlı hemorajik sistit`,E:`Mesane divertikülü`},dogru:`D`,aciklama:`Siklofosfamidin akrolein metaboliti ve adenovirus enfeksiyonları hemorajik sistite yol açar.`,sik_aciklamalari:{A:`Malakoplaki bu ilaçla ilişkili bir sistit tipi değildir.`,B:`İnterstisyel sistit kültür negatif, Hunner ülserli kronik tablodur.`,C:`Gonore cinsel yolla bulaşan üretrittir.`,D:`Doğru: ilaç etiyolojisi akılda tutulmalıdır.`,E:`Divertikül ilaçla gelişmez.`},bilgi:[10],benzer_cikmis:[]},{id:`k1-46-q12`,kazanim:4,zorluk:`zor`,soru:`42 yaşında kadın aylardır süren suprapubik ağrı, sık ve acil idrara çıkma yakınmasıyla başvuruyor. Tekrarlanan idrar kültürleri negatif; sistoskopide mukozada ağrılı ülseröz lezyon izleniyor.

En olası tanı hangisidir?`,secenekler:{A:`Akut bakteriyel sistit`,B:`Hunner ülserli interstisyel sistit`,C:`Hemorajik sistit`,D:`Ürotelyal karsinom in situ`,E:`Mesane divertikülü`},dogru:`B`,aciklama:`Kronik pelvik ağrı, kültür negatifliği, kadın cinsiyet ve Hunner ülseri interstisyel sistit (ağrılı mesane sendromu) için tipiktir.`,sik_aciklamalari:{A:`Bakteriyel sistitte kültür pozitiftir.`,B:`Doğru: Hunner ülseri ağrılı mesane sendromunun lezyonudur.`,C:`Hemorajik sistit ilaç veya adenovirüsle ilişkilidir ve hematüri ön plandadır.`,D:`Karsinom in situ ağrısız hematüri ve pozitif sitoloji ile seyreder.`,E:`Divertikül ülserle tanımlanmaz.`},bilgi:[8,11],benzer_cikmis:[]},{id:`k1-46-mesane-hastaliklari-ve-tumorleri-k04-q04`,kazanim:4,zorluk:`orta`,soru:`Genç kadın hastada dizüri, sık idrara çıkma ve suprapubik ağrı var; idrar kültürü isteniyor. Aşağıdakilerden hangisi doğrudur?`,secenekler:{A:`En sık etken Proteus'tur`,B:`Sistit erkeklerde daha sıktır`,C:`Sistitte dizüri görülmez`,D:`Kültürde üreme tanıyı dışlar`,E:`Akut bakteriyel sistitin en sık etkeni E. coli'dir; kadınlarda kısa üretra nedeniyle daha sıktır`},dogru:`E`,aciklama:`E. coli en sık etkendir; kısa üretra kadınlarda yatkınlık yaratır.`,sik_aciklamalari:{A:`Yanlış: bu seçenek vakadaki tabloyla uyumlu değildir; doğru yanıt 'Akut bakteriyel sistitin en sık etkeni E. coli'dir; kadınlarda kısa üretra nedeniyle daha sıktır' seçeneğidir.`,B:`Yanlış: bu seçenek vakadaki tabloyla uyumlu değildir; doğru yanıt 'Akut bakteriyel sistitin en sık etkeni E. coli'dir; kadınlarda kısa üretra nedeniyle daha sıktır' seçeneğidir.`,C:`Yanlış: bu seçenek vakadaki tabloyla uyumlu değildir; doğru yanıt 'Akut bakteriyel sistitin en sık etkeni E. coli'dir; kadınlarda kısa üretra nedeniyle daha sıktır' seçeneğidir.`,D:`Yanlış: bu seçenek vakadaki tabloyla uyumlu değildir; doğru yanıt 'Akut bakteriyel sistitin en sık etkeni E. coli'dir; kadınlarda kısa üretra nedeniyle daha sıktır' seçeneğidir.`,E:`Doğru: E. coli en sık etkendir; kısa üretra kadınlarda yatkınlık yaratır.`},bilgi:[8,9],benzer_cikmis:[]},{id:`k1-46-mesane-hastaliklari-ve-tumorleri-k04-q05`,kazanim:4,zorluk:`zor`,soru:`Siklofosfamid alan hastada hemorajik sistit ile kültür negatif ağrılı mesaneli hasta karşılaştırılıyor. Aşağıdakilerden hangisi yanlıştır?`,secenekler:{A:`İnterstisyel sistitte Hunner ülseri görülür; kültür negatiftir ve kadınlarda sıktır`,B:`Foliküler sistitte lamina propriada lenfoid folliküller vardır`,C:`Hemorajik sistit yalnızca bakteriyeldir ve Hunner ülseri akut bakteriyel sistitin bulgusudur`,D:`Eozinofilik sistit alerjik/ilaç ilişkili olabilir`,E:`Hemorajik sistit siklofosfamid (akrolein) ve adenovirus ile ilişkilidir`},dogru:`E`,aciklama:`Hunner ülseri interstisyel sistitindir; hemorajik sistit ilaç/viraldir. Son ifade yanlıştır.`,sik_aciklamalari:{A:`Yanlış: bu seçenek vakadaki tabloyla uyumlu değildir; doğru yanıt 'Hemorajik sistit siklofosfamid (akrolein) ve adenovirus ile ilişkilidir' seçeneğidir.`,B:`Yanlış: bu seçenek vakadaki tabloyla uyumlu değildir; doğru yanıt 'Hemorajik sistit siklofosfamid (akrolein) ve adenovirus ile ilişkilidir' seçeneğidir.`,C:`Yanlış: bu seçenek vakadaki tabloyla uyumlu değildir; doğru yanıt 'Hemorajik sistit siklofosfamid (akrolein) ve adenovirus ile ilişkilidir' seçeneğidir.`,D:`Yanlış: bu seçenek vakadaki tabloyla uyumlu değildir; doğru yanıt 'Hemorajik sistit siklofosfamid (akrolein) ve adenovirus ile ilişkilidir' seçeneğidir.`,E:`Doğru: Hunner ülseri interstisyel sistitindir; hemorajik sistit ilaç/viraldir. Son ifade yanlıştır.`},bilgi:[10,11],benzer_cikmis:[]},{id:`k1-46-mesane-hastaliklari-ve-tumorleri-k04-q06`,kazanim:4,zorluk:`orta`,soru:`Akut bakteriyel sistitin en sık etkenleri hangileridir?`,secenekler:{A:`En sık etken adenovirus ve CMV'dir`,B:`Mantarlar akut sistitin başlıca nedenidir`,C:`Steril idrarda otoimmünite tek nedendir`,D:`En sık etken E. coli ve koliformlardır`,E:`Mikobakteriler ilk sırada yer alır`},dogru:`D`,aciklama:`Akut bakteriyel sistitte en sık etkenler E. coli başta olmak üzere Proteus, Klebsiella ve Enterobacter gibi koliformlardır. Bu bakteriler üretral kolonizasyon sonrası asendan yolla mesaneye ulaşır. Kadınlarda kısa üretra riski artırır.`,sik_aciklamalari:{A:`Yanlış: Viruslar hemorajik sistitte rol alır, akut bakteriyelde değil.`,B:`Yanlış: Mantar sistiti nadir ve immunsuprese özgüdür.`,C:`Yanlış: Otoimmün nedenler nadirdir; bakteriler baskındır.`,D:`Doğru: Koliformlar, özellikle E. coli, ilk sıradadır.`,E:`Yanlış: Mikobakteriler steril piyüride akla gelir.`},bilgi:[8,9],benzer_cikmis:[]},{id:`k1-46-mesane-hastaliklari-ve-tumorleri-k04-q07`,kazanim:4,zorluk:`orta`,soru:`Hemorajik ve interstisyel sistitin ayırt edici özellikleri nelerdir?`,secenekler:{A:`Hemorajik sistit akrolein ve adenovirusa bağlıdır`,B:`İnterstisyel sistitte kültür hep pozitiftir`,C:`Hunner ülseri akut bakteriyelde tipiktir`,D:`Siklofosfamid sistite karşı koruyucudur`,E:`İnterstisyel sistit erkeklerde daha sıktır`},dogru:`A`,aciklama:`Hemorajik sistit siklofosfamidin akrolein metaboliti ve adenovirus ile ilişkilidir. Akrolein mesane mukozasında hemorajik inflamasyon yapar. İnterstisyel sistit ise kültür negatif kronik pelvik ağrı ve Hunner ülseriyle seyreder.`,sik_aciklamalari:{A:`Doğru: Akrolein toksisitesi ve adenovirus hemorajik sistit yapar.`,B:`Yanlış: İnterstisyel sistitte kültür negatiftir.`,C:`Yanlış: Hunner ülseri interstisyel sistitin bulgusudur.`,D:`Yanlış: Siklofosfamid metaboliti mesaneye toksiktir.`,E:`Yanlış: İnterstisyel sistit daha çok kadınlarda görülür.`},bilgi:[10,11],benzer_cikmis:[`eac9503f2c68`]},{id:`k1-46-mesane-hastaliklari-ve-tumorleri-k04-q08`,kazanim:4,zorluk:`kolay`,soru:`Aşağıdakilerden "Sistit tanımı ve sıklığı" ile ilgili doğru olan seçeneği işaretleyiniz.`,secenekler:{A:`Mesane mukozasının inflamasyonudur; etiyolojisi çoğunlukla bakteriyeldir, ayrıca kimyasal (ilaç), radyasyon, cihaz ve otoimmün nedenler olabilir.`,D:`Siklofosfamidin akrolein metaboliti ve adenovirus enfeksiyonları ile ilişkilidir.`,C:`Etken Haemophilus ducreyi (Gram negatif kokobasil); 4-7 gün inkübasyondan sonra dış genitalde papül hızla ağrılı ülsere dönüşür, çoklu ülserler sıktır ve sert indürasyon yoktur.`,E:`Erkekte en sık koronal sulkus ve sünnet derisi iç yüzünde, kadında genellikle vulva ve perianal bölgede; küçük saplı poliplerden büyük papiller kitlelere kadar değişir. Mikroskopide papiller skuamöz proliferasyon ve koilositoz (perinükleer halo ve hafif nükleer atipi).`,B:`En sık etkenler E. coli (koliformlar), Proteus, Klebsiella ve Enterobacter türleridir.`},dogru:`A`,aciklama:`Doğru: Mesane mukozasının inflamasyonudur; etiyolojisi çoğunlukla bakteriyeldir, ayrıca kimyasal (ilaç), radyasyon, cihaz ve otoimmün nedenler olabilir.`,sik_aciklamalari:{A:`Doğru. Mesane mukozasının inflamasyonudur; etiyolojisi çoğunlukla bakteriyeldir, ayrıca kimyasal (ilaç), radyasyon, cihaz ve otoimmün nedenler olabilir.`,D:`Yanlış. Siklofosfamidin akrolein metaboliti ve adenovirus enfeksiyonları ile ilişkilidir.`,C:`Yanlış. Etken Haemophilus ducreyi (Gram negatif kokobasil); 4-7 gün inkübasyondan sonra dış genitalde papül hızla ağrılı ülsere dönüşür, çoklu ülserler sıktır ve sert indürasyon yoktur.`,E:`Yanlış. Erkekte en sık koronal sulkus ve sünnet derisi iç yüzünde, kadında genellikle vulva ve perianal bölgede; küçük saplı poliplerden büyük papiller kitlelere kadar değişir. Mikroskopide papiller skuamöz proliferasyon ve koilositoz (perinükleer halo ve hafif nükleer atipi).`,B:`Yanlış. En sık etkenler E. coli (koliformlar), Proteus, Klebsiella ve Enterobacter türleridir.`},bilgi:[8],benzer_cikmis:[]},{id:`k1-46-mesane-hastaliklari-ve-tumorleri-k04-q09`,kazanim:4,zorluk:`orta`,soru:`"Sifilisin patognomonik lezyonu" kavramı hakkında verilen aşağıdakilerden hangisi doğrudur?`,secenekler:{A:`Tüm evrelerde proliferatif endarterit ve plazma hücre zengin infiltrat vardır.`,C:`Düşük dereceli papiller yol FGFR3 ve HRAS ile; yüksek dereceli CIS-invaziv yol TP53 ve RB ile ilişkilidir.`,D:`Etken penisiline son derece duyarlıdır. Nontreponemal testler (RPR, VDRL; antikardiyolipin) tedavi izleminde kullanılır ve titre düşer; treponemal testler (T. pallidum spesifik antikor) genellikle ömür boyu pozitif kalır.`,B:`Sekonder şankr iyileşmesinden ~2 ay sonra döküntü, mukokutanöz lezyonlar ve lenfadenopati ile; kondiloma lata anogenital bölgede geniş tabanlı kabarık lezyonlardır. Tersiyer yıllar sonra (5-20 yıl) kardiyovasküler sifilis, nörosifilis ve gumma ile seyreder.`,E:`En sık bulgu ağrısız makroskopik veya mikroskopik hematüridir; tanıda sistoskopi + biyopsi ve idrar sitolojisi (özellikle yüksek dereceli ve CIS) kullanılır.`},dogru:`A`,aciklama:`Doğru: Tüm evrelerde proliferatif endarterit ve plazma hücre zengin infiltrat vardır.`,sik_aciklamalari:{A:`Doğru. Tüm evrelerde proliferatif endarterit ve plazma hücre zengin infiltrat vardır.`,C:`Yanlış. Düşük dereceli papiller yol FGFR3 ve HRAS ile; yüksek dereceli CIS-invaziv yol TP53 ve RB ile ilişkilidir.`,D:`Yanlış. Etken penisiline son derece duyarlıdır. Nontreponemal testler (RPR, VDRL; antikardiyolipin) tedavi izleminde kullanılır ve titre düşer; treponemal testler (T. pallidum spesifik antikor) genellikle ömür boyu pozitif kalır.`,B:`Yanlış. Sekonder şankr iyileşmesinden ~2 ay sonra döküntü, mukokutanöz lezyonlar ve lenfadenopati ile; kondiloma lata anogenital bölgede geniş tabanlı kabarık lezyonlardır. Tersiyer yıllar sonra (5-20 yıl) kardiyovasküler sifilis, nörosifilis ve gumma ile seyreder.`,E:`Yanlış. En sık bulgu ağrısız makroskopik veya mikroskopik hematüridir; tanıda sistoskopi + biyopsi ve idrar sitolojisi (özellikle yüksek dereceli ve CIS) kullanılır.`},bilgi:[18],benzer_cikmis:[]},{id:`k1-46-mesane-hastaliklari-ve-tumorleri-k04-q10`,kazanim:4,zorluk:`orta`,soru:`"Skuamöz hücreli karsinom patogenezi" ile ilgili aşağıdakilerden hangisi yanlıştır?`,secenekler:{E:`Endemik şistozomiyazis bölgelerinde kronik sistit, skuamöz metaplazi ve skuamöz hücreli karsinom insidansı artar; patogenez kronik inflamasyon + metaplazi → displazi → karsinomdur.`,C:`Histolojide yüzeyde nötrofiller ve fibrin kaplı ülser, altta granülasyon dokusu, nekroz ve tromboze damarlar, periferde lenfoplazmasitik infiltrat; lenf nodlarında nekrotizan inflamasyon, apse ve drenaj ülserleri.`,B:`Erkekte en sık koronal sulkus ve sünnet derisi iç yüzünde, kadında genellikle vulva ve perianal bölgede; küçük saplı poliplerden büyük papiller kitlelere kadar değişir. Mikroskopide papiller skuamöz proliferasyon ve koilositoz (perinükleer halo ve hafif nükleer atipi).`,D:`Tüm evrelerde proliferatif endarterit ve plazma hücre zengin infiltrat vardır.`,A:`C. trachomatis'in farklı (L1-L3) serovarlarına bağlı kronik, ülseratif CYBE; özellikle erkeklerle cinsel ilişkiye giren erkeklerde kasık lenfadenopatisi ve proktit görülür, HIV koinfeksiyonuyla güçlü ilişkilidir.`},dogru:`E`,aciklama:`Doğru: Endemik şistozomiyazis bölgelerinde kronik sistit, skuamöz metaplazi ve skuamöz hücreli karsinom insidansı artar; patogenez kronik inflamasyon + metaplazi → displazi → karsinomdur.`,sik_aciklamalari:{E:`Doğru. Endemik şistozomiyazis bölgelerinde kronik sistit, skuamöz metaplazi ve skuamöz hücreli karsinom insidansı artar; patogenez kronik inflamasyon + metaplazi → displazi → karsinomdur.`,C:`Yanlış. Histolojide yüzeyde nötrofiller ve fibrin kaplı ülser, altta granülasyon dokusu, nekroz ve tromboze damarlar, periferde lenfoplazmasitik infiltrat; lenf nodlarında nekrotizan inflamasyon, apse ve drenaj ülserleri.`,B:`Yanlış. Erkekte en sık koronal sulkus ve sünnet derisi iç yüzünde, kadında genellikle vulva ve perianal bölgede; küçük saplı poliplerden büyük papiller kitlelere kadar değişir. Mikroskopide papiller skuamöz proliferasyon ve koilositoz (perinükleer halo ve hafif nükleer atipi).`,D:`Yanlış. Tüm evrelerde proliferatif endarterit ve plazma hücre zengin infiltrat vardır.`,A:`Yanlış. C. trachomatis'in farklı (L1-L3) serovarlarına bağlı kronik, ülseratif CYBE; özellikle erkeklerle cinsel ilişkiye giren erkeklerde kasık lenfadenopatisi ve proktit görülür, HIV koinfeksiyonuyla güçlü ilişkilidir.`},bilgi:[13],benzer_cikmis:[]},{id:`k1-46-mesane-hastaliklari-ve-tumorleri-k04-q11`,kazanim:4,zorluk:`zor`,soru:`"Genital HSV morfoloji ve kliniği" klinik bağlamda aşağıdakilerden hangisi doğrudur?`,secenekler:{C:`Semptomatik olguda ağrılı vezikül/ülserler, dizüri, akıntı, lenfadenopati, ateş ve miyalji; histolojide intraepitelyal veziküller, Cowdry tip A intranükleer inklüzyon ve çok çekirdekli dev hücreler.`,B:`Böbrek pelvisi, üreter, mesane ve üretra ürotelyum (geçiş epiteli) ile kaplıdır; altında lamina propria ve muskularis propria (mesanede detrusor kası) vardır.`,D:`HPV genital sistemde kondiloma akuminatum, prekanseröz skuamöz lezyonlar ve karsinomlar (serviks, penis, vulva, orofaringeal tonsil, konjonktiva) yapar. Kondiloma akuminatum etkeni düşük riskli HPV tip 6 ve 11'dir.`,A:`Enfeksiyondan ortalama 21 gün sonra gelişir; erkekte penis/skrotum (%70), kadında vulva/serviks (~%50) yerleşir; tabanda belirgin indürasyonlu sert şankr oluşur.`,E:`Mesane kanserlerinin ~%90'ı ürotelyal karsinomdur; majör risk faktörleri sigara, aromatik aminler (boya, kauçuk, tekstil), siklofosfamid ve pelvik radyoterapidir.`},dogru:`C`,aciklama:`Doğru: Semptomatik olguda ağrılı vezikül/ülserler, dizüri, akıntı, lenfadenopati, ateş ve miyalji; histolojide intraepitelyal veziküller, Cowdry tip A intranükleer inklüzyon ve çok çekirdekli dev hücreler.`,sik_aciklamalari:{C:`Doğru. Semptomatik olguda ağrılı vezikül/ülserler, dizüri, akıntı, lenfadenopati, ateş ve miyalji; histolojide intraepitelyal veziküller, Cowdry tip A intranükleer inklüzyon ve çok çekirdekli dev hücreler.`,B:`Yanlış. Böbrek pelvisi, üreter, mesane ve üretra ürotelyum (geçiş epiteli) ile kaplıdır; altında lamina propria ve muskularis propria (mesanede detrusor kası) vardır.`,D:`Yanlış. HPV genital sistemde kondiloma akuminatum, prekanseröz skuamöz lezyonlar ve karsinomlar (serviks, penis, vulva, orofaringeal tonsil, konjonktiva) yapar. Kondiloma akuminatum etkeni düşük riskli HPV tip 6 ve 11'dir.`,A:`Yanlış. Enfeksiyondan ortalama 21 gün sonra gelişir; erkekte penis/skrotum (%70), kadında vulva/serviks (~%50) yerleşir; tabanda belirgin indürasyonlu sert şankr oluşur.`,E:`Yanlış. Mesane kanserlerinin ~%90'ı ürotelyal karsinomdur; majör risk faktörleri sigara, aromatik aminler (boya, kauçuk, tekstil), siklofosfamid ve pelvik radyoterapidir.`},bilgi:[36],benzer_cikmis:[]}],ilgili_cikmis:[]},{no:5,metin:`Kronik irritasyon, skuamöz metaplazi ve skuamöz hücreli karsinom ilişkisini açıklayabilmek`,sorular:[{id:`k1-46-q13`,kazanim:5,zorluk:`kolay`,soru:`Ürotelyumda uzun süreli kronik irritasyon sonucu gelişen ve skuamöz hücreli karsinoma zemin hazırlayabilen değişiklik hangisidir?`,secenekler:{A:`Hipoplazi`,B:`Atrofi`,C:`Skuamöz metaplazi`,D:`Agenezi`,E:`Hiyalinizasyon`},dogru:`C`,aciklama:`Kronik enfeksiyon, taş, kateter ve şistozomiyazis skuamöz metaplaziye ve karsinom gelişimine zemin oluşturur.`,sik_aciklamalari:{A:`Hipoplazi gelişimsel yetersizliktir.`,B:`Atrofi hücre boyut/sayı azalmasıdır, karsinom zemini olarak tanımlanmaz.`,C:`Doğru: metaplazi → displazi → karsinom zinciri vardır.`,D:`Agenezi organın hiç gelişmemesidir.`,E:`Hiyalinizasyon bu süreçle ilişkili değildir.`},bilgi:[12],benzer_cikmis:[]},{id:`k1-46-q14`,kazanim:5,zorluk:`orta`,soru:`Aşağıdakilerden hangisi mesanede skuamöz metaplaziye yol açan kronik irritasyon nedenlerinden biri değildir?`,secenekler:{A:`Uzun süreli kateter kullanımı`,B:`Mesane taşı`,C:`Şistozomiyazis`,D:`Kronik enfeksiyon`,E:`Tek seferlik akut viral üretrit`},dogru:`E`,aciklama:`Skuamöz metaplazi uzun süreli irritasyonla gelişir; tek seferlik akut süreç beklenen neden değildir.`,sik_aciklamalari:{A:`Kateter kronik mekanik irritasyon yapar.`,B:`Taş kronik irritasyon kaynağıdır.`,C:`Şistozomiyazis en önemli nedenlerden biridir.`,D:`Kronik enfeksiyon metaplaziye yol açar.`,E:`Doğru: kısa süreli akut enfeksiyon metaplazi zemini oluşturmaz.`},bilgi:[12],benzer_cikmis:[]},{id:`k1-46-q15`,kazanim:5,zorluk:`zor`,soru:`Mısır'da tarım işçisi olarak çalışmış ve yıllarca tekrarlayan hematürisi olan hastada mesane biyopsisinde keratinleşen atipik yassı epitel adaları invaziv büyüme gösteriyor.

Bu tümörün patogenezini en iyi açıklayan sıra hangisidir?`,secenekler:{A:`FGFR3 mutasyonu → düşük dereceli papiller tümör`,B:`Kronik inflamasyon → skuamöz metaplazi → displazi → skuamöz hücreli karsinom`,C:`VHL kaybı → HIF birikimi → karsinom`,D:`HPV 6/11 → kondiloma akuminata`,E:`Akrolein → hemorajik sistit → adenokarsinom`},dogru:`B`,aciklama:`Endemik şistozomiyazis bölgesinde kronik sistit skuamöz metaplazi ve displazi üzerinden skuamöz hücreli karsinoma ilerler.`,sik_aciklamalari:{A:`FGFR3 düşük dereceli papiller ürotelyal karsinom yoludur.`,B:`Doğru: kronik inflamatuar zeminin karsinojen olduğu modeldir.`,C:`VHL–HIF yolu berrak hücreli RHK'ya aittir.`,D:`HPV 6/11 benign anogenital siğil yapar.`,E:`Akrolein hemorajik sistit yapar; bu dizi tanımlanmış değildir.`},bilgi:[12,13],benzer_cikmis:[]},{id:`k1-46-mesane-hastaliklari-ve-tumorleri-k05-q04`,kazanim:5,zorluk:`orta`,soru:`Endemik şistozomiyazis bölgesinde kronik sistitli hastada mesane biyopsisi planlanıyor. Aşağıdakilerden hangisi doğrudur?`,secenekler:{A:`Metaplazi maligniteyi önler`,B:`Kronik irritasyon (taş, kateter, şistozomiyazis) skuamöz metaplaziye, bu zemin skuamöz hücreli karsinoma yol açabilir`,C:`Şistozomiyazis ürotelyal karsinomu artırır`,D:`Kronik inflamasyon koruyucudur`,E:`Skuamöz metaplazi yalnızca böbrekte olur`},dogru:`B`,aciklama:`Patogenez: kronik inflamasyon + metaplazi → displazi → skuamöz karsinomdur.`,sik_aciklamalari:{A:`Yanlış: bu seçenek vakadaki tabloyla uyumlu değildir; doğru yanıt 'Kronik irritasyon (taş, kateter, şistozomiyazis) skuamöz metaplaziye, bu zemin skuamöz hücreli karsinoma yol açabilir' seçeneğidir.`,B:`Doğru: Patogenez: kronik inflamasyon + metaplazi → displazi → skuamöz karsinomdur.`,C:`Yanlış: bu seçenek vakadaki tabloyla uyumlu değildir; doğru yanıt 'Kronik irritasyon (taş, kateter, şistozomiyazis) skuamöz metaplaziye, bu zemin skuamöz hücreli karsinoma yol açabilir' seçeneğidir.`,D:`Yanlış: bu seçenek vakadaki tabloyla uyumlu değildir; doğru yanıt 'Kronik irritasyon (taş, kateter, şistozomiyazis) skuamöz metaplaziye, bu zemin skuamöz hücreli karsinoma yol açabilir' seçeneğidir.`,E:`Yanlış: bu seçenek vakadaki tabloyla uyumlu değildir; doğru yanıt 'Kronik irritasyon (taş, kateter, şistozomiyazis) skuamöz metaplaziye, bu zemin skuamöz hücreli karsinoma yol açabilir' seçeneğidir.`},bilgi:[12,13],benzer_cikmis:[]},{id:`k1-46-mesane-hastaliklari-ve-tumorleri-k05-q05`,kazanim:5,zorluk:`zor`,soru:`Patogenez zinciri soruluyor. Aşağıdakilerden hangisi yanlıştır?`,secenekler:{A:`Endemik şistozomiyaziste skuamöz hücreli karsinom insidansı artar`,B:`Zincir metaplazi → displazi → karsinomdur`,C:`Uzun süreli enfeksiyon/taş/kateter ürotelyumda reaktif değişiklik ve metaplazi yapar`,D:`Kronik irritasyon skuamöz karsinom riskini azaltır ve metaplazi invazyonu engeller`,E:`Skuamöz metaplazi skuamöz karsinom zeminidir`},dogru:`C`,aciklama:`Kronik irritasyon riski artırır; azalttığı ifadesi yanlıştır.`,sik_aciklamalari:{A:`Yanlış: bu seçenek vakadaki tabloyla uyumlu değildir; doğru yanıt 'Uzun süreli enfeksiyon/taş/kateter ürotelyumda reaktif değişiklik ve metaplazi yapar' seçeneğidir.`,B:`Yanlış: bu seçenek vakadaki tabloyla uyumlu değildir; doğru yanıt 'Uzun süreli enfeksiyon/taş/kateter ürotelyumda reaktif değişiklik ve metaplazi yapar' seçeneğidir.`,C:`Doğru: Kronik irritasyon riski artırır; azalttığı ifadesi yanlıştır.`,D:`Yanlış: bu seçenek vakadaki tabloyla uyumlu değildir; doğru yanıt 'Uzun süreli enfeksiyon/taş/kateter ürotelyumda reaktif değişiklik ve metaplazi yapar' seçeneğidir.`,E:`Yanlış: bu seçenek vakadaki tabloyla uyumlu değildir; doğru yanıt 'Uzun süreli enfeksiyon/taş/kateter ürotelyumda reaktif değişiklik ve metaplazi yapar' seçeneğidir.`},bilgi:[12,13],benzer_cikmis:[]},{id:`k1-46-mesane-hastaliklari-ve-tumorleri-k05-q06`,kazanim:5,zorluk:`orta`,soru:`Mesanede skuamöz metaplaziye yol açan temel süreç nedir?`,secenekler:{A:`Akut tek atak sistit metaplaziye yeterlidir`,B:`Steril idrar skuamöz dönüşümü tetikler`,C:`Kronik irritasyon skuamöz metaplaziye yol açar`,D:`Metaplazi yalnızca genetik geçişlidir`,E:`Taş ve kateter epiteli koruyarak önler`},dogru:`C`,aciklama:`Uzun süreli enfeksiyon, taş, kateter ve şistozomiyazis ürotelyumda reaktif değişiklik ve skuamöz metaplazi yapar. Kronik inflamasyon mediyatörleri epitel farklılaşmasını skuamöz yöne kaydırır. Metaplazi displazi-karsinom basamağının ilk halkasıdır.`,sik_aciklamalari:{A:`Yanlış: Metaplazi için uzun süreli irritasyon gerekir.`,B:`Yanlış: Tetikleyici kronik enfeksiyon, taş ve parazitlerdir.`,C:`Doğru: Süregen irritasyon ürotelyumu skuamöz yöne dönüştürür.`,D:`Yanlış: Metaplazi edinsel reaktif bir değişimdir.`,E:`Yanlış: Taş ve kateter kronik irritasyon kaynaklarıdır.`},bilgi:[12],benzer_cikmis:[]},{id:`k1-46-mesane-hastaliklari-ve-tumorleri-k05-q07`,kazanim:5,zorluk:`orta`,soru:`Şistozomiyazisin mesane skuamöz hücreli karsinomuyla ilişkisi nedir?`,secenekler:{A:`Şistozomiyazis ürotelyal karsinomu tamamen önler`,B:`Skuamöz karsinom hep HPV ile gelişir`,C:`Metaplazi displaziye hiç ilerlemez`,D:`Kronik inflamasyon tümörü geriletir`,E:`Şistozomiyazis skuamöz karsinom riskini artırır`},dogru:`E`,aciklama:`Endemik şistozomiyazis bölgelerinde kronik sistit skuamöz metaplazi üzerinden skuamöz hücreli karsinom insidansını artırır. Patogenetik sıra kronik inflamasyon, metaplazi, displazi ve karsinomdur. Parazit yumurtalarına karşı granülomatöz yanıt süregen hasarı sürdürür.`,sik_aciklamalari:{A:`Yanlış: Şistozomiyazis skuamöz karsinom riskini artırır.`,B:`Yanlış: Mesane skuamöz karsinomu kronik irritasyon zeminlidir.`,C:`Yanlış: Metaplazi displazi ve karsinoma ilerleyebilir.`,D:`Yanlış: Süregen inflamasyon karsinogenezi destekler.`,E:`Doğru: Paraziter kronik sistit skuamöz karsinoma yol açar.`},bilgi:[13],benzer_cikmis:[]},{id:`k1-46-mesane-hastaliklari-ve-tumorleri-k05-q08`,kazanim:5,zorluk:`kolay`,soru:`"Ürotelyal karsinom genetik yolları" ifadesi ile ilgili aşağıdakilerden hangisi doğrudur?`,secenekler:{A:`Düşük dereceli papiller yol FGFR3 ve HRAS ile; yüksek dereceli CIS-invaziv yol TP53 ve RB ile ilişkilidir.`,D:`C. trachomatis'in farklı (L1-L3) serovarlarına bağlı kronik, ülseratif CYBE; özellikle erkeklerle cinsel ilişkiye giren erkeklerde kasık lenfadenopatisi ve proktit görülür, HIV koinfeksiyonuyla güçlü ilişkilidir.`,B:`En sık bulgu ağrısız makroskopik veya mikroskopik hematüridir; tanıda sistoskopi + biyopsi ve idrar sitolojisi (özellikle yüksek dereceli ve CIS) kullanılır.`,C:`Etken Neisseria gonorrhoeae (Gram negatif diplokok); Chlamydia trachomatis'ten sonra ikinci sık bakteriyel CYBE'dir; cinsel temasla ve enfekte mukozaya doğrudan temasla bulaşır.`,E:`Etken Treponema pallidum (spiroket); bulaş erken evre deri/mukoza lezyonlarıyla temasla ve konjenital olarak plasenta yoluyla olur.`},dogru:`A`,aciklama:`Doğru: Düşük dereceli papiller yol FGFR3 ve HRAS ile; yüksek dereceli CIS-invaziv yol TP53 ve RB ile ilişkilidir.`,sik_aciklamalari:{A:`Doğru. Düşük dereceli papiller yol FGFR3 ve HRAS ile; yüksek dereceli CIS-invaziv yol TP53 ve RB ile ilişkilidir.`,D:`Yanlış. C. trachomatis'in farklı (L1-L3) serovarlarına bağlı kronik, ülseratif CYBE; özellikle erkeklerle cinsel ilişkiye giren erkeklerde kasık lenfadenopatisi ve proktit görülür, HIV koinfeksiyonuyla güçlü ilişkilidir.`,B:`Yanlış. En sık bulgu ağrısız makroskopik veya mikroskopik hematüridir; tanıda sistoskopi + biyopsi ve idrar sitolojisi (özellikle yüksek dereceli ve CIS) kullanılır.`,C:`Yanlış. Etken Neisseria gonorrhoeae (Gram negatif diplokok); Chlamydia trachomatis'ten sonra ikinci sık bakteriyel CYBE'dir; cinsel temasla ve enfekte mukozaya doğrudan temasla bulaşır.`,E:`Yanlış. Etken Treponema pallidum (spiroket); bulaş erken evre deri/mukoza lezyonlarıyla temasla ve konjenital olarak plasenta yoluyla olur.`},bilgi:[15],benzer_cikmis:[]},{id:`k1-46-mesane-hastaliklari-ve-tumorleri-k05-q09`,kazanim:5,zorluk:`orta`,soru:`"Mesane divertikülü" kavramı hakkında verilen aşağıdakilerden hangisi doğrudur?`,secenekler:{C:`Mesane duvarında mukozanın kese benzeri invajinasyonudur; konjenital (kas tabakasında fokal zayıflık) veya edinilmiş (distal obstrüksiyon: BPH, üretra darlığı) olabilir.`,E:`Divertikül içindeki idrar stazı tekrarlayan idrar yolu enfeksiyonu, taş oluşumu ve nadiren tümör gelişimine yol açar.`,B:`Dört veya dokuz değerliklidir; düşük riskli tip 6 ve 11'e karşı koruma sağlar, anogenital siğilleri önler ve HPV ilişkili karsinom insidansını (özellikle serviks) azaltır.`,D:`Erkekte epididimit ve prostatit; kadında infertilite ve ektopik gebelik; yenidoğanda konjonktivit ve pnömoni (vajinal doğumda bulaş).`,A:`Histolojide yüzeyde nötrofiller ve fibrin kaplı ülser, altta granülasyon dokusu, nekroz ve tromboze damarlar, periferde lenfoplazmasitik infiltrat; lenf nodlarında nekrotizan inflamasyon, apse ve drenaj ülserleri.`},dogru:`C`,aciklama:`Doğru: Mesane duvarında mukozanın kese benzeri invajinasyonudur; konjenital (kas tabakasında fokal zayıflık) veya edinilmiş (distal obstrüksiyon: BPH, üretra darlığı) olabilir.`,sik_aciklamalari:{C:`Doğru. Mesane duvarında mukozanın kese benzeri invajinasyonudur; konjenital (kas tabakasında fokal zayıflık) veya edinilmiş (distal obstrüksiyon: BPH, üretra darlığı) olabilir.`,E:`Yanlış. Divertikül içindeki idrar stazı tekrarlayan idrar yolu enfeksiyonu, taş oluşumu ve nadiren tümör gelişimine yol açar.`,B:`Yanlış. Dört veya dokuz değerliklidir; düşük riskli tip 6 ve 11'e karşı koruma sağlar, anogenital siğilleri önler ve HPV ilişkili karsinom insidansını (özellikle serviks) azaltır.`,D:`Yanlış. Erkekte epididimit ve prostatit; kadında infertilite ve ektopik gebelik; yenidoğanda konjonktivit ve pnömoni (vajinal doğumda bulaş).`,A:`Yanlış. Histolojide yüzeyde nötrofiller ve fibrin kaplı ülser, altta granülasyon dokusu, nekroz ve tromboze damarlar, periferde lenfoplazmasitik infiltrat; lenf nodlarında nekrotizan inflamasyon, apse ve drenaj ülserleri.`},bilgi:[6],benzer_cikmis:[]},{id:`k1-46-mesane-hastaliklari-ve-tumorleri-k05-q10`,kazanim:5,zorluk:`orta`,soru:`"Üreter bozuklukları sınıflaması" ile ilgili aşağıdakilerden hangisi yanlıştır?`,secenekler:{C:`Nadir fakat önemli üç grup: konjenital darlık (UPJ tıkanıklığı), neoplazmlar (genellikle ürotelyal karsinom) ve reaktif süreçler (retroperitoneal fibrozis).`,B:`Divertikül içindeki idrar stazı tekrarlayan idrar yolu enfeksiyonu, taş oluşumu ve nadiren tümör gelişimine yol açar.`,E:`Endemik şistozomiyazis bölgelerinde kronik sistit, skuamöz metaplazi ve skuamöz hücreli karsinom insidansı artar; patogenez kronik inflamasyon + metaplazi → displazi → karsinomdur.`,A:`Mesane mukozasının inflamasyonudur; etiyolojisi çoğunlukla bakteriyeldir, ayrıca kimyasal (ilaç), radyasyon, cihaz ve otoimmün nedenler olabilir.`,D:`Kronik pelvik ağrı ve Hunner ülseri ile seyreder; kültür negatiftir ve daha çok kadınlarda görülür.`},dogru:`C`,aciklama:`Doğru: Nadir fakat önemli üç grup: konjenital darlık (UPJ tıkanıklığı), neoplazmlar (genellikle ürotelyal karsinom) ve reaktif süreçler (retroperitoneal fibrozis).`,sik_aciklamalari:{C:`Doğru. Nadir fakat önemli üç grup: konjenital darlık (UPJ tıkanıklığı), neoplazmlar (genellikle ürotelyal karsinom) ve reaktif süreçler (retroperitoneal fibrozis).`,B:`Yanlış. Divertikül içindeki idrar stazı tekrarlayan idrar yolu enfeksiyonu, taş oluşumu ve nadiren tümör gelişimine yol açar.`,E:`Yanlış. Endemik şistozomiyazis bölgelerinde kronik sistit, skuamöz metaplazi ve skuamöz hücreli karsinom insidansı artar; patogenez kronik inflamasyon + metaplazi → displazi → karsinomdur.`,A:`Yanlış. Mesane mukozasının inflamasyonudur; etiyolojisi çoğunlukla bakteriyeldir, ayrıca kimyasal (ilaç), radyasyon, cihaz ve otoimmün nedenler olabilir.`,D:`Yanlış. Kronik pelvik ağrı ve Hunner ülseri ile seyreder; kültür negatiftir ve daha çok kadınlarda görülür.`},bilgi:[2],benzer_cikmis:[]},{id:`k1-46-mesane-hastaliklari-ve-tumorleri-k05-q11`,kazanim:5,zorluk:`zor`,soru:`"Trichomoniasis tanısı" klinik bağlamda aşağıdakilerden hangisi doğrudur?`,secenekler:{C:`Vajinal kazıntıdan ıslak preparatta hareketli organizmanın gösterilmesiyle konur; genellikle eşzamanlı klamidya ve gonore testleri yapılır.`,A:`Mesane kanserlerinin ~%90'ı ürotelyal karsinomdur; majör risk faktörleri sigara, aromatik aminler (boya, kauçuk, tekstil), siklofosfamid ve pelvik radyoterapidir.`,E:`Mesane mukozasının inflamasyonudur; etiyolojisi çoğunlukla bakteriyeldir, ayrıca kimyasal (ilaç), radyasyon, cihaz ve otoimmün nedenler olabilir.`,D:`C. trachomatis'in farklı (L1-L3) serovarlarına bağlı kronik, ülseratif CYBE; özellikle erkeklerle cinsel ilişkiye giren erkeklerde kasık lenfadenopatisi ve proktit görülür, HIV koinfeksiyonuyla güçlü ilişkilidir.`,B:`En sık etkenler E. coli (koliformlar), Proteus, Klebsiella ve Enterobacter türleridir.`},dogru:`C`,aciklama:`Doğru: Vajinal kazıntıdan ıslak preparatta hareketli organizmanın gösterilmesiyle konur; genellikle eşzamanlı klamidya ve gonore testleri yapılır.`,sik_aciklamalari:{C:`Doğru. Vajinal kazıntıdan ıslak preparatta hareketli organizmanın gösterilmesiyle konur; genellikle eşzamanlı klamidya ve gonore testleri yapılır.`,A:`Yanlış. Mesane kanserlerinin ~%90'ı ürotelyal karsinomdur; majör risk faktörleri sigara, aromatik aminler (boya, kauçuk, tekstil), siklofosfamid ve pelvik radyoterapidir.`,E:`Yanlış. Mesane mukozasının inflamasyonudur; etiyolojisi çoğunlukla bakteriyeldir, ayrıca kimyasal (ilaç), radyasyon, cihaz ve otoimmün nedenler olabilir.`,D:`Yanlış. C. trachomatis'in farklı (L1-L3) serovarlarına bağlı kronik, ülseratif CYBE; özellikle erkeklerle cinsel ilişkiye giren erkeklerde kasık lenfadenopatisi ve proktit görülür, HIV koinfeksiyonuyla güçlü ilişkilidir.`,B:`Yanlış. En sık etkenler E. coli (koliformlar), Proteus, Klebsiella ve Enterobacter türleridir.`},bilgi:[34],benzer_cikmis:[]}],ilgili_cikmis:[]},{no:6,metin:`Ürotelyal karsinomun risk faktörlerini, genetik yollarını ve morfolojik paternlerini açıklayabilmek`,sorular:[{id:`k1-46-q16`,kazanim:6,zorluk:`kolay`,soru:`Mesanenin en sık malign tümörü hangisidir?`,secenekler:{A:`Rabdomiyosarkom`,B:`Skuamöz hücreli karsinom`,C:`Adenokarsinom`,D:`Ürotelyal karsinom`,E:`Lenfoma`},dogru:`D`,aciklama:`Mesane kanserlerinin yaklaşık %90'ı ürotelyal karsinomdur.`,sik_aciklamalari:{A:`Rabdomiyosarkom çocuklarda nadir görülür.`,B:`Skuamöz hücreli karsinom daha çok şistozomiyazis zemininde görülür.`,C:`Adenokarsinom nadirdir.`,D:`Doğru: mesanenin en sık malign tümörüdür.`,E:`Mesane lenfoması nadirdir.`},bilgi:[14],benzer_cikmis:[]},{id:`k1-46-q17`,kazanim:6,zorluk:`orta`,soru:`Aşağıdakilerden hangisi ürotelyal karsinom için majör risk faktörü değildir?`,secenekler:{A:`Sigara`,B:`Boya, kauçuk ve tekstil endüstrisindeki aromatik aminler`,C:`Siklofosfamid`,D:`Pelvik radyoterapi`,E:`HPV 6 ve 11 enfeksiyonu`},dogru:`E`,aciklama:`Ürotelyal karsinomun majör risk faktörleri sigara, aromatik aminler, siklofosfamid ve pelvik radyoterapidir.`,sik_aciklamalari:{A:`Sigara en önemli risk faktörüdür.`,B:`Aromatik aminler mesleki karsinojenlerdir.`,C:`Siklofosfamid risk faktörüdür.`,D:`Pelvik radyoterapi riski artırır.`,E:`Doğru: HPV 6/11 düşük riskli tiplerdir ve kondiloma yapar.`},bilgi:[14,38],benzer_cikmis:[]},{id:`k1-46-q19`,kazanim:6,zorluk:`orta`,soru:`Ürotelyal karsinom tanısında kullanılan yöntemlerle ilgili hangisi doğrudur?`,secenekler:{A:`İdrar sitolojisi düşük dereceli papiller tümörlerde en duyarlı yöntemdir`,B:`Sistoskopi ve biyopsi temel tanı yöntemidir; idrar sitolojisi özellikle yüksek dereceli tümör ve CIS'te değerlidir`,C:`Tanı yalnızca serum tümör belirteçleri ile konur`,D:`Biyopsi gereksizdir`,E:`En sık bulgu ağrılı hematüridir`},dogru:`B`,aciklama:`Tanı sistoskopi + biyopsi ile konur; idrar sitolojisi yüksek dereceli tümör ve CIS'te daha yararlıdır. En sık bulgu ağrısız hematüridir.`,sik_aciklamalari:{A:`Sitoloji düşük dereceli tümörlerde duyarlılığı düşüktür.`,B:`Doğru: tanı yaklaşımı doğru tanımlanmıştır.`,C:`Serum belirteçleri tanı koydurmaz.`,D:`Histopatolojik tanı ve evreleme için biyopsi gereklidir.`,E:`Tipik bulgu ağrısız hematüridir.`},bilgi:[16],benzer_cikmis:[]},{id:`k1-46-q18`,kazanim:6,zorluk:`zor`,soru:`Ürotelyal karsinomun iki genetik yolu karşılaştırıldığında hangisi doğrudur?`,secenekler:{A:`Her iki yol da VHL kaybı ile başlar`,B:`Düşük dereceli papiller yol TP53 ve RB; invaziv yol FGFR3 ile ilişkilidir`,C:`Düşük dereceli papiller yol FGFR3 ve HRAS; yüksek dereceli CIS-invaziv yol TP53 ve RB ile ilişkilidir`,D:`İki yolun klinik davranışı ve prognozu aynıdır`,E:`Karsinom in situ yalnızca düşük dereceli papiller tümörden gelişir`},dogru:`C`,aciklama:`FGFR3/HRAS düşük dereceli papiller tümörlerle; TP53/RB yüksek dereceli CIS ve invaziv karsinomla ilişkilidir ve prognozları farklıdır.`,sik_aciklamalari:{A:`VHL kaybı berrak hücreli RHK'ya aittir.`,B:`Genler yer değiştirilmiştir.`,C:`Doğru: iki yolun genetik temeli doğru verilmiştir.`,D:`İki yolun klinik davranışı farklıdır.`,E:`CIS yüksek dereceli yolun öncülüdür.`},bilgi:[15],benzer_cikmis:[]},{id:`k1-46-mesane-hastaliklari-ve-tumorleri-k06-q05`,kazanim:6,zorluk:`orta`,soru:`Sigara içen 65 yaşında hastada ağrısız makroskopik hematüri var; sistoskopi planlanıyor. Aşağıdakilerden hangisi doğrudur?`,secenekler:{A:`En sık tip skuamöz karsinomdur`,B:`Majör risk faktörü HPV'dir`,C:`Düşük dereceli yol TP53 ile ilişkilidir`,D:`Mesane kanserlerinin ~%90'ı ürotelyal karsinomdur; majör risk faktörü sigaradır; düşük dereceli yol FGFR3/HRAS, yüksek dereceli yol TP53/RB ile ilişkilidir`,E:`Yüksek dereceli yol FGFR3 ile ilişkilidir`},dogru:`D`,aciklama:`~%90 ürotelyal karsinom; sigara majör risk; FGFR3/HRAS düşük, TP53/RB yüksek derece yoludur.`,sik_aciklamalari:{A:`Yanlış: bu seçenek vakadaki tabloyla uyumlu değildir; doğru yanıt 'Mesane kanserlerinin ~%90'ı ürotelyal karsinomdur; majör risk faktörü sigaradır; düşük dereceli yol FGFR3/HRAS, yüksek dereceli yol TP53/RB ile ilişkilidir' seçeneğidir.`,B:`Yanlış: bu seçenek vakadaki tabloyla uyumlu değildir; doğru yanıt 'Mesane kanserlerinin ~%90'ı ürotelyal karsinomdur; majör risk faktörü sigaradır; düşük dereceli yol FGFR3/HRAS, yüksek dereceli yol TP53/RB ile ilişkilidir' seçeneğidir.`,C:`Yanlış: bu seçenek vakadaki tabloyla uyumlu değildir; doğru yanıt 'Mesane kanserlerinin ~%90'ı ürotelyal karsinomdur; majör risk faktörü sigaradır; düşük dereceli yol FGFR3/HRAS, yüksek dereceli yol TP53/RB ile ilişkilidir' seçeneğidir.`,D:`Doğru: ~%90 ürotelyal karsinom; sigara majör risk; FGFR3/HRAS düşük, TP53/RB yüksek derece yoludur.`,E:`Yanlış: bu seçenek vakadaki tabloyla uyumlu değildir; doğru yanıt 'Mesane kanserlerinin ~%90'ı ürotelyal karsinomdur; majör risk faktörü sigaradır; düşük dereceli yol FGFR3/HRAS, yüksek dereceli yol TP53/RB ile ilişkilidir' seçeneğidir.`},bilgi:[14,15],benzer_cikmis:[]},{id:`k1-46-mesane-hastaliklari-ve-tumorleri-k06-q06`,kazanim:6,zorluk:`zor`,soru:`Patolojide CIS ve kas invazyonu tartışılıyor. Aşağıdakilerden hangisi yanlıştır?`,secenekler:{A:`CIS flat noninvaziv yüksek dereceli lezyondur; büyümüş hiperkromatik çekirdek ve mitoz gösterir`,B:`Tanıda sistoskopi + biyopsi ve idrar sitolojisi kullanılır`,C:`Prognozda evre (özellikle kas invazyonu) belirleyicidir`,D:`CIS benign düşük dereceli papillomdur ve kas invazyonu prognozu iyileştirir`,E:`En sık bulgu ağrısız hematüridir`},dogru:`A`,aciklama:`CIS yüksek derecelidir; kas invazyonu kötü prognostiktir. Son ifade yanlıştır.`,sik_aciklamalari:{A:`Doğru: CIS yüksek derecelidir; kas invazyonu kötü prognostiktir. Son ifade yanlıştır.`,B:`Yanlış: bu seçenek vakadaki tabloyla uyumlu değildir; doğru yanıt 'CIS flat noninvaziv yüksek dereceli lezyondur; büyümüş hiperkromatik çekirdek ve mitoz gösterir' seçeneğidir.`,C:`Yanlış: bu seçenek vakadaki tabloyla uyumlu değildir; doğru yanıt 'CIS flat noninvaziv yüksek dereceli lezyondur; büyümüş hiperkromatik çekirdek ve mitoz gösterir' seçeneğidir.`,D:`Yanlış: bu seçenek vakadaki tabloyla uyumlu değildir; doğru yanıt 'CIS flat noninvaziv yüksek dereceli lezyondur; büyümüş hiperkromatik çekirdek ve mitoz gösterir' seçeneğidir.`,E:`Yanlış: bu seçenek vakadaki tabloyla uyumlu değildir; doğru yanıt 'CIS flat noninvaziv yüksek dereceli lezyondur; büyümüş hiperkromatik çekirdek ve mitoz gösterir' seçeneğidir.`},bilgi:[15,16],benzer_cikmis:[]},{id:`k1-46-mesane-hastaliklari-ve-tumorleri-k06-q07`,kazanim:6,zorluk:`orta`,soru:`Ürotelyal karsinomun majör risk faktörleri hangileridir?`,secenekler:{A:`Başlıca risk sebze ağırlıklı diyettir`,B:`Sigara ve aromatik aminler majör risklerdir`,C:`Mesane kanseri hep viral kökenlidir`,D:`Siklofosfamid koruyucu etki gösterir`,E:`Radyoterapi riski tamamen ortadan kaldırır`},dogru:`B`,aciklama:`Mesane kanserlerinin yaklaşık %90'ı ürotelyal karsinomdur. Majör riskler sigara, aromatik aminler (boya, kauçuk, tekstil), siklofosfamid ve pelvik radyoterapidir. Karsinojenler idrarla atılırken ürotelyumu uzun süre maruz bırakır.`,sik_aciklamalari:{A:`Yanlış: Diyet majör risk olarak tanımlanmaz.`,B:`Doğru: Sigara ve aromatik aminler ürotelyumu karsinojene maruz bırakır.`,C:`Yanlış: Baskın riskler kimyasal karsinojenlerdir.`,D:`Yanlış: Siklofosfamid metaboliti mesaneye toksik ve karsinojeniktir.`,E:`Yanlış: Pelvik radyoterapi riski artırır.`},bilgi:[14],benzer_cikmis:[]},{id:`k1-46-mesane-hastaliklari-ve-tumorleri-k06-q08`,kazanim:6,zorluk:`orta`,soru:`Ürotelyal karsinomun iki genetik ilerleme yolu nasıl ayrılır?`,secenekler:{A:`Her iki yol da yalnızca HPV ile başlar`,B:`Düşük derece TP53, yüksek derece FGFR3 taşır`,C:`Genetik yol ayrımı prognozu etkilemez`,D:`Papiller yol FGFR3; invaziv yol TP53-RB`,E:`Her iki yolda da VHL kaybı esastır`},dogru:`D`,aciklama:`Düşük dereceli papiller yol FGFR3 ve HRAS değişiklikleriyle, yüksek dereceli CIS-invaziv yol TP53 ve RB kaybıyla ilerler. FGFR3 sinyali papiller büyümeyi, TP53-RB kaybı genomik instabiliteyi destekler. İki yol farklı klinik seyir gösterir.`,sik_aciklamalari:{A:`Yanlış: HPV ürotelyal karsinomun sürücüsü değildir.`,B:`Yanlış: İlişki tersinedir; FGFR3 papiller, TP53 invaziv yoldadır.`,C:`Yanlış: Genetik yol seyir ve tedavi kararını belirler.`,D:`Doğru: FGFR3 papiller büyümeyi, TP53-RB invazyonu destekler.`,E:`Yanlış: VHL kaybı böbrek berrak hücreli yoluna aittir.`},bilgi:[15],benzer_cikmis:[]},{id:`k1-46-mesane-hastaliklari-ve-tumorleri-k06-q09`,kazanim:6,zorluk:`kolay`,soru:`"Gonore morfolojisi, tanısı ve profilaksisi" ifadesi ile ilgili aşağıdakilerden hangisi doğrudur?`,secenekler:{C:`Pürülan inflamasyon; erkekte ödemli hiperemik üretral meatus; Gram boyasında nötrofiller içinde Gram negatif diplokoklar. Tanıda NAAT tercih edilir; kültür antibiyotik duyarlılığı için kullanılır.`,E:`Enfeksiyondan ortalama 21 gün sonra gelişir; erkekte penis/skrotum (%70), kadında vulva/serviks (~%50) yerleşir; tabanda belirgin indürasyonlu sert şankr oluşur.`,A:`Etken Haemophilus ducreyi (Gram negatif kokobasil); 4-7 gün inkübasyondan sonra dış genitalde papül hızla ağrılı ülsere dönüşür, çoklu ülserler sıktır ve sert indürasyon yoktur.`,D:`En sık bulgu ağrısız makroskopik veya mikroskopik hematüridir; tanıda sistoskopi + biyopsi ve idrar sitolojisi (özellikle yüksek dereceli ve CIS) kullanılır.`,B:`Böbrek pelvisi, üreter, mesane ve üretra ürotelyum (geçiş epiteli) ile kaplıdır; altında lamina propria ve muskularis propria (mesanede detrusor kası) vardır.`},dogru:`C`,aciklama:`Doğru: Pürülan inflamasyon; erkekte ödemli hiperemik üretral meatus; Gram boyasında nötrofiller içinde Gram negatif diplokoklar. Tanıda NAAT tercih edilir; kültür antibiyotik duyarlılığı için kullanılır.`,sik_aciklamalari:{C:`Doğru. Pürülan inflamasyon; erkekte ödemli hiperemik üretral meatus; Gram boyasında nötrofiller içinde Gram negatif diplokoklar. Tanıda NAAT tercih edilir; kültür antibiyotik duyarlılığı için kullanılır.`,E:`Yanlış. Enfeksiyondan ortalama 21 gün sonra gelişir; erkekte penis/skrotum (%70), kadında vulva/serviks (~%50) yerleşir; tabanda belirgin indürasyonlu sert şankr oluşur.`,A:`Yanlış. Etken Haemophilus ducreyi (Gram negatif kokobasil); 4-7 gün inkübasyondan sonra dış genitalde papül hızla ağrılı ülsere dönüşür, çoklu ülserler sıktır ve sert indürasyon yoktur.`,D:`Yanlış. En sık bulgu ağrısız makroskopik veya mikroskopik hematüridir; tanıda sistoskopi + biyopsi ve idrar sitolojisi (özellikle yüksek dereceli ve CIS) kullanılır.`,B:`Yanlış. Böbrek pelvisi, üreter, mesane ve üretra ürotelyum (geçiş epiteli) ile kaplıdır; altında lamina propria ve muskularis propria (mesanede detrusor kası) vardır.`},bilgi:[25],benzer_cikmis:[]},{id:`k1-46-mesane-hastaliklari-ve-tumorleri-k06-q10`,kazanim:6,zorluk:`orta`,soru:`"Mesane divertikülü" ile ilgili aşağıdakilerden hangisi yanlıştır?`,secenekler:{C:`Mesane duvarında mukozanın kese benzeri invajinasyonudur; konjenital (kas tabakasında fokal zayıflık) veya edinilmiş (distal obstrüksiyon: BPH, üretra darlığı) olabilir.`,E:`Tüm evrelerde proliferatif endarterit ve plazma hücre zengin infiltrat vardır.`,A:`Erkekte üretrit (dizüri, sık idrara çıkma, mukopürülan akıntı), kadında çoğu zaman asemptomatik seyir; tedavi edilmezse PID, infertilite ve ektopik gebelik gelişir.`,D:`Etken Trichomonas vaginalis (kamçılı protozoon); genellikle cinsel temasla bulaşır. Kadında pruritus, bol köpüklü sarı-yeşil vajinal akıntı, üretral kolonizasyona bağlı dizüri; erkekte genelde hafif üretrit.`,B:`Mesane mukozasının inflamasyonudur; etiyolojisi çoğunlukla bakteriyeldir, ayrıca kimyasal (ilaç), radyasyon, cihaz ve otoimmün nedenler olabilir.`},dogru:`C`,aciklama:`Doğru: Mesane duvarında mukozanın kese benzeri invajinasyonudur; konjenital (kas tabakasında fokal zayıflık) veya edinilmiş (distal obstrüksiyon: BPH, üretra darlığı) olabilir.`,sik_aciklamalari:{C:`Doğru. Mesane duvarında mukozanın kese benzeri invajinasyonudur; konjenital (kas tabakasında fokal zayıflık) veya edinilmiş (distal obstrüksiyon: BPH, üretra darlığı) olabilir.`,E:`Yanlış. Tüm evrelerde proliferatif endarterit ve plazma hücre zengin infiltrat vardır.`,A:`Yanlış. Erkekte üretrit (dizüri, sık idrara çıkma, mukopürülan akıntı), kadında çoğu zaman asemptomatik seyir; tedavi edilmezse PID, infertilite ve ektopik gebelik gelişir.`,D:`Yanlış. Etken Trichomonas vaginalis (kamçılı protozoon); genellikle cinsel temasla bulaşır. Kadında pruritus, bol köpüklü sarı-yeşil vajinal akıntı, üretral kolonizasyona bağlı dizüri; erkekte genelde hafif üretrit.`,B:`Yanlış. Mesane mukozasının inflamasyonudur; etiyolojisi çoğunlukla bakteriyeldir, ayrıca kimyasal (ilaç), radyasyon, cihaz ve otoimmün nedenler olabilir.`},bilgi:[6],benzer_cikmis:[]},{id:`k1-46-mesane-hastaliklari-ve-tumorleri-k06-q11`,kazanim:6,zorluk:`orta`,soru:`"HPV aşısı" kavramı hakkında verilen aşağıdakilerden hangisi doğrudur?`,secenekler:{B:`Dört veya dokuz değerliklidir; düşük riskli tip 6 ve 11'e karşı koruma sağlar, anogenital siğilleri önler ve HPV ilişkili karsinom insidansını (özellikle serviks) azaltır.`,E:`Nadir fakat önemli üç grup: konjenital darlık (UPJ tıkanıklığı), neoplazmlar (genellikle ürotelyal karsinom) ve reaktif süreçler (retroperitoneal fibrozis).`,A:`Uzun süreli enfeksiyon, taş, kateter ve şistozomiyazis ürotelyumda reaktif değişikliklere ve skuamöz metaplaziye yol açar.`,D:`Tüm evrelerde proliferatif endarterit ve plazma hücre zengin infiltrat vardır.`,C:`Endemik şistozomiyazis bölgelerinde kronik sistit, skuamöz metaplazi ve skuamöz hücreli karsinom insidansı artar; patogenez kronik inflamasyon + metaplazi → displazi → karsinomdur.`},dogru:`B`,aciklama:`Doğru: Dört veya dokuz değerliklidir; düşük riskli tip 6 ve 11'e karşı koruma sağlar, anogenital siğilleri önler ve HPV ilişkili karsinom insidansını (özellikle serviks) azaltır.`,sik_aciklamalari:{B:`Doğru. Dört veya dokuz değerliklidir; düşük riskli tip 6 ve 11'e karşı koruma sağlar, anogenital siğilleri önler ve HPV ilişkili karsinom insidansını (özellikle serviks) azaltır.`,E:`Yanlış. Nadir fakat önemli üç grup: konjenital darlık (UPJ tıkanıklığı), neoplazmlar (genellikle ürotelyal karsinom) ve reaktif süreçler (retroperitoneal fibrozis).`,A:`Yanlış. Uzun süreli enfeksiyon, taş, kateter ve şistozomiyazis ürotelyumda reaktif değişikliklere ve skuamöz metaplaziye yol açar.`,D:`Yanlış. Tüm evrelerde proliferatif endarterit ve plazma hücre zengin infiltrat vardır.`,C:`Yanlış. Endemik şistozomiyazis bölgelerinde kronik sistit, skuamöz metaplazi ve skuamöz hücreli karsinom insidansı artar; patogenez kronik inflamasyon + metaplazi → displazi → karsinomdur.`},bilgi:[40],benzer_cikmis:[]},{id:`k1-46-mesane-hastaliklari-ve-tumorleri-k06-q12`,kazanim:6,zorluk:`zor`,soru:`"Mesane divertikülü" ile ilgili bir hastada bulunacak aşağıdaki bulgulardan hangisi beklenmez?`,secenekler:{C:`Mesane duvarında mukozanın kese benzeri invajinasyonudur; konjenital (kas tabakasında fokal zayıflık) veya edinilmiş (distal obstrüksiyon: BPH, üretra darlığı) olabilir.`,A:`Erkekte epididimit ve prostatit; kadında infertilite ve ektopik gebelik; yenidoğanda konjonktivit ve pnömoni (vajinal doğumda bulaş).`,E:`Etken penisiline son derece duyarlıdır. Nontreponemal testler (RPR, VDRL; antikardiyolipin) tedavi izleminde kullanılır ve titre düşer; treponemal testler (T. pallidum spesifik antikor) genellikle ömür boyu pozitif kalır.`,D:`Mesane kanserlerinin ~%90'ı ürotelyal karsinomdur; majör risk faktörleri sigara, aromatik aminler (boya, kauçuk, tekstil), siklofosfamid ve pelvik radyoterapidir.`,B:`Nadir fakat önemli üç grup: konjenital darlık (UPJ tıkanıklığı), neoplazmlar (genellikle ürotelyal karsinom) ve reaktif süreçler (retroperitoneal fibrozis).`},dogru:`C`,aciklama:`Doğru: Mesane duvarında mukozanın kese benzeri invajinasyonudur; konjenital (kas tabakasında fokal zayıflık) veya edinilmiş (distal obstrüksiyon: BPH, üretra darlığı) olabilir.`,sik_aciklamalari:{C:`Doğru. Mesane duvarında mukozanın kese benzeri invajinasyonudur; konjenital (kas tabakasında fokal zayıflık) veya edinilmiş (distal obstrüksiyon: BPH, üretra darlığı) olabilir.`,A:`Yanlış. Erkekte epididimit ve prostatit; kadında infertilite ve ektopik gebelik; yenidoğanda konjonktivit ve pnömoni (vajinal doğumda bulaş).`,E:`Yanlış. Etken penisiline son derece duyarlıdır. Nontreponemal testler (RPR, VDRL; antikardiyolipin) tedavi izleminde kullanılır ve titre düşer; treponemal testler (T. pallidum spesifik antikor) genellikle ömür boyu pozitif kalır.`,D:`Yanlış. Mesane kanserlerinin ~%90'ı ürotelyal karsinomdur; majör risk faktörleri sigara, aromatik aminler (boya, kauçuk, tekstil), siklofosfamid ve pelvik radyoterapidir.`,B:`Yanlış. Nadir fakat önemli üç grup: konjenital darlık (UPJ tıkanıklığı), neoplazmlar (genellikle ürotelyal karsinom) ve reaktif süreçler (retroperitoneal fibrozis).`},bilgi:[6],benzer_cikmis:[]}],ilgili_cikmis:[]},{no:7,metin:`Ürotelyal karsinomda evrenin (kas invazyonunun) prognoz açısından önemini kavramak`,sorular:[{id:`k1-46-q20`,kazanim:7,zorluk:`kolay`,soru:`Ürotelyal karsinomda tedavi ve prognozu en çok belirleyen özellik hangisidir?`,secenekler:{A:`İdrar pH'sı`,B:`Hastanın cinsiyeti`,C:`Hematürinin rengi`,D:`Tümör evresi, özellikle muskularis propria (detrusor) invazyonu`,E:`Tümörün mesanedeki yan duvar yerleşimi`},dogru:`D`,aciklama:`Kas invazyonunun varlığı tedavi seçimini ve prognozu en çok belirleyen faktördür.`,sik_aciklamalari:{A:`İdrar pH'sı prognostik bir ölçüt değildir.`,B:`Cinsiyet prognozun ana belirleyicisi değildir.`,C:`Hematüri rengi prognostik değildir.`,D:`Doğru: kas invaziv hastalık prognozu belirgin kötüleştirir.`,E:`Yerleşim tek başına evre kadar belirleyici değildir.`},bilgi:[16],benzer_cikmis:[]},{id:`k1-46-q21`,kazanim:7,zorluk:`orta`,soru:`Transüretral rezeksiyon materyalinin patolojik değerlendirmesinde muskularis propria bulunmasının önemi nedir?`,secenekler:{A:`HPV varlığını gösterir`,B:`Tümör derecesini tek başına belirler`,C:`Kas invazyonunun değerlendirilebilmesini, dolayısıyla evrelemeyi sağlar`,D:`Sitolojinin yerine geçer`,E:`Önemi yoktur`},dogru:`C`,aciklama:`Örnekte detrusor kası varsa invazyon değerlendirilebilir; kas invazyonu evreyi ve tedaviyi belirler.`,sik_aciklamalari:{A:`HPV mesane karsinomunda temel bir etken değildir.`,B:`Derece sitolojik/histolojik atipiye göre belirlenir.`,C:`Doğru: evreleme için kas tabakasının örneklenmesi gerekir.`,D:`Biyopsi ve sitoloji birbirini tamamlar.`,E:`Kas tabakasının varlığı evreleme için kritiktir.`},bilgi:[1,16],benzer_cikmis:[]},{id:`k1-46-q22`,kazanim:7,zorluk:`zor`,soru:`İki hastada mesane ürotelyal karsinomu saptanıyor: Hasta 1'de tümör lamina propriaya sınırlı, Hasta 2'de detrusor kasına invaziv.

Bu hastaların karşılaştırılmasında hangisi doğrudur?`,secenekler:{A:`İki hastanın prognozu aynıdır`,B:`Hasta 2'nin prognozu daha kötüdür ve daha agresif tedavi gerektirir`,C:`Hasta 1'de kas invazyonu olmadığı için tümör benigndir`,D:`Evre prognozu etkilemez; yalnızca derece önemlidir`,E:`Hasta 2'de idrar sitolojisi her zaman negatiftir`},dogru:`B`,aciklama:`Kas invazyonu (detrusor) ürotelyal karsinomda prognozu kötüleştiren ve tedaviyi değiştiren en önemli faktördür.`,sik_aciklamalari:{A:`Evre farkı prognozu belirgin değiştirir.`,B:`Doğru: kas invaziv hastalık daha kötü seyirlidir.`,C:`Lamina propria invazyonu da maligndir.`,D:`Evre, özellikle kas invazyonu, belirleyicidir.`,E:`Yüksek dereceli invaziv tümörlerde sitoloji sıklıkla pozitiftir.`},bilgi:[16],benzer_cikmis:[]},{id:`k1-46-mesane-hastaliklari-ve-tumorleri-k07-q04`,kazanim:7,zorluk:`orta`,soru:`TUR materyalinde tümörün muskularis propriaya invaze olduğu raporlanıyor. Aşağıdakilerden hangisi doğrudur?`,secenekler:{A:`Tedavi ve prognozda tümör evresi, özellikle kas (muskularis propria) invazyonu belirleyicidir`,B:`Kas invazyonu önemsizdir`,C:`Evre tedaviyi etkilemez`,D:`Yüzeyel tümörler hep ölümcüldür`,E:`Kas invazyonu iyi prognoz gösterir`},dogru:`A`,aciklama:`Kas invazyonu evrelemeyi ve tedaviyi belirleyen ana faktördür.`,sik_aciklamalari:{A:`Doğru: Kas invazyonu evrelemeyi ve tedaviyi belirleyen ana faktördür.`,B:`Yanlış: bu seçenek vakadaki tabloyla uyumlu değildir; doğru yanıt 'Tedavi ve prognozda tümör evresi, özellikle kas (muskularis propria) invazyonu belirleyicidir' seçeneğidir.`,C:`Yanlış: bu seçenek vakadaki tabloyla uyumlu değildir; doğru yanıt 'Tedavi ve prognozda tümör evresi, özellikle kas (muskularis propria) invazyonu belirleyicidir' seçeneğidir.`,D:`Yanlış: bu seçenek vakadaki tabloyla uyumlu değildir; doğru yanıt 'Tedavi ve prognozda tümör evresi, özellikle kas (muskularis propria) invazyonu belirleyicidir' seçeneğidir.`,E:`Yanlış: bu seçenek vakadaki tabloyla uyumlu değildir; doğru yanıt 'Tedavi ve prognozda tümör evresi, özellikle kas (muskularis propria) invazyonu belirleyicidir' seçeneğidir.`},bilgi:[16],benzer_cikmis:[]},{id:`k1-46-mesane-hastaliklari-ve-tumorleri-k07-q05`,kazanim:7,zorluk:`zor`,soru:`İnvaziv olmayan düşük dereceli papiller tümör ile invaziv tümör karşılaştırılıyor. Aşağıdakilerden hangisi yanlıştır?`,secenekler:{A:`İnvaziv papiller karsinom muskularis propriaya girebilir`,B:`Kas invazyonu prognozu kötüleştirir`,C:`Kas invazyonu prognozu düzeltir ve sistektomi gereksinimini ortadan kaldırır`,D:`Düşük dereceli noninvaziv papiller tümörde dağınık mitoz ve hafif atipi vardır`,E:`CIS invazyon göstermez ancak yüksek derecelidir`},dogru:`D`,aciklama:`Kas invazyonu kötü prognostiktir ve agresif tedavi gerektirir.`,sik_aciklamalari:{A:`Yanlış: bu seçenek vakadaki tabloyla uyumlu değildir; doğru yanıt 'Düşük dereceli noninvaziv papiller tümörde dağınık mitoz ve hafif atipi vardır' seçeneğidir.`,B:`Yanlış: bu seçenek vakadaki tabloyla uyumlu değildir; doğru yanıt 'Düşük dereceli noninvaziv papiller tümörde dağınık mitoz ve hafif atipi vardır' seçeneğidir.`,C:`Yanlış: bu seçenek vakadaki tabloyla uyumlu değildir; doğru yanıt 'Düşük dereceli noninvaziv papiller tümörde dağınık mitoz ve hafif atipi vardır' seçeneğidir.`,D:`Doğru: Kas invazyonu kötü prognostiktir ve agresif tedavi gerektirir.`,E:`Yanlış: bu seçenek vakadaki tabloyla uyumlu değildir; doğru yanıt 'Düşük dereceli noninvaziv papiller tümörde dağınık mitoz ve hafif atipi vardır' seçeneğidir.`},bilgi:[16],benzer_cikmis:[]},{id:`k1-46-mesane-hastaliklari-ve-tumorleri-k07-q06`,kazanim:7,zorluk:`orta`,soru:`Ürotelyal karsinomun en sık bulgusu ve tanı yöntemleri nelerdir?`,secenekler:{A:`Ağrısız hematüri; tanı sistoskopi ve sitolojidir`,B:`Ağrılı dizüri tek bulgu; tanı kan kültürüdür`,C:`Ateş başlıca bulgu; tanı akciğer grafisidir`,D:`Sarılık tipiktir; tanı karaciğer biyopsisidir`,E:`Kilo alımı tipiktir; tanı dışkı testidir`},dogru:`A`,aciklama:`En sık bulgu ağrısız makroskopik veya mikroskopik hematüridir. Tanıda sistoskopi ile biyopsi ve idrar sitolojisi (özellikle yüksek dereceli ve CIS) kullanılır. Sitoloji dökülen atipik ürotelyal hücreleri yakalar.`,sik_aciklamalari:{A:`Doğru: Hematüri en sık bulgudur; sistoskopi ve sitoloji tanı koydurur.`,B:`Yanlış: Kan kültürü ürotelyal tümör tanısında kullanılmaz.`,C:`Yanlış: Ateş ve grafi tanı algoritmasında yer almaz.`,D:`Yanlış: Sarılık ürotelyal karsinom bulgusu değildir.`,E:`Yanlış: Dışkı testi mesane tümörü tanısında kullanılmaz.`},bilgi:[16],benzer_cikmis:[]},{id:`k1-46-mesane-hastaliklari-ve-tumorleri-k07-q07`,kazanim:7,zorluk:`orta`,soru:`Ürotelyal karsinomda kas invazyonunun prognostik anlamı nedir?`,secenekler:{A:`Kas invazyonu prognozu hiç değiştirmez`,B:`Tümör boyutu evreyi tek başına belirler`,C:`Kas invazyonu prognozu kötüleştirip tedaviyi değiştirir`,D:`Non-invaziv tümörde sistektomi zorunludur`,E:`Evreleme yalnızca idrar rengiyle yapılır`},dogru:`C`,aciklama:`Kas (muskularis propria) invazyonu evrelemede kritik eşiktir; invaziv hastalıkta prognoz belirgin kötüleşir ve tedavi sistektomiye yönelir. Non-invaziv papiller tümörlerde endoskopik tedavi ve izlem yeterlidir. Bu ayrım sağkalımı belirleyen başlıca faktördür.`,sik_aciklamalari:{A:`Yanlış: Kas invazyonu prognozu belirgin kötüleştirir.`,B:`Yanlış: Belirleyici olan invazyon derinliğidir.`,C:`Doğru: Muskularis invazyonu ileri evre ve agresif tedavi gerektirir.`,D:`Yanlış: Non-invaziv hastalıkta endoskopik tedavi yeterlidir.`,E:`Yanlış: Evre histopatolojik invazyon derinliğiyle belirlenir.`},bilgi:[16],benzer_cikmis:[`fc3fe2282513`]},{id:`k1-46-mesane-hastaliklari-ve-tumorleri-k07-q08`,kazanim:7,zorluk:`kolay`,soru:`"Skuamöz hücreli karsinom patogenezi" kavramının tanımı aşağıdakilerden hangisidir?`,secenekler:{B:`Endemik şistozomiyazis bölgelerinde kronik sistit, skuamöz metaplazi ve skuamöz hücreli karsinom insidansı artar; patogenez kronik inflamasyon + metaplazi → displazi → karsinomdur.`,D:`Divertikül içindeki idrar stazı tekrarlayan idrar yolu enfeksiyonu, taş oluşumu ve nadiren tümör gelişimine yol açar.`,C:`Semptomatik olguda ağrılı vezikül/ülserler, dizüri, akıntı, lenfadenopati, ateş ve miyalji; histolojide intraepitelyal veziküller, Cowdry tip A intranükleer inklüzyon ve çok çekirdekli dev hücreler.`,A:`Zorunlu hücre içi Gram negatif bakteri; elementer cisim (enfeksiyöz, ekstraselüler) ve retiküler cisim (metabolik aktif, hücre içi) formları vardır; kolumnar epitel tropizmi gösterir.`,E:`C. trachomatis'in farklı (L1-L3) serovarlarına bağlı kronik, ülseratif CYBE; özellikle erkeklerle cinsel ilişkiye giren erkeklerde kasık lenfadenopatisi ve proktit görülür, HIV koinfeksiyonuyla güçlü ilişkilidir.`},dogru:`B`,aciklama:`Doğru: Endemik şistozomiyazis bölgelerinde kronik sistit, skuamöz metaplazi ve skuamöz hücreli karsinom insidansı artar; patogenez kronik inflamasyon + metaplazi → displazi → karsinomdur.`,sik_aciklamalari:{B:`Doğru. Endemik şistozomiyazis bölgelerinde kronik sistit, skuamöz metaplazi ve skuamöz hücreli karsinom insidansı artar; patogenez kronik inflamasyon + metaplazi → displazi → karsinomdur.`,D:`Yanlış. Divertikül içindeki idrar stazı tekrarlayan idrar yolu enfeksiyonu, taş oluşumu ve nadiren tümör gelişimine yol açar.`,C:`Yanlış. Semptomatik olguda ağrılı vezikül/ülserler, dizüri, akıntı, lenfadenopati, ateş ve miyalji; histolojide intraepitelyal veziküller, Cowdry tip A intranükleer inklüzyon ve çok çekirdekli dev hücreler.`,A:`Yanlış. Zorunlu hücre içi Gram negatif bakteri; elementer cisim (enfeksiyöz, ekstraselüler) ve retiküler cisim (metabolik aktif, hücre içi) formları vardır; kolumnar epitel tropizmi gösterir.`,E:`Yanlış. C. trachomatis'in farklı (L1-L3) serovarlarına bağlı kronik, ülseratif CYBE; özellikle erkeklerle cinsel ilişkiye giren erkeklerde kasık lenfadenopatisi ve proktit görülür, HIV koinfeksiyonuyla güçlü ilişkilidir.`},bilgi:[13],benzer_cikmis:[]},{id:`k1-46-mesane-hastaliklari-ve-tumorleri-k07-q09`,kazanim:7,zorluk:`orta`,soru:`"Ürotelyal karsinom temel noktaları" kavramı hakkında verilen aşağıdakilerden hangisi doğrudur?`,secenekler:{B:`Mesane kanserlerinin ~%90'ı ürotelyal karsinomdur; majör risk faktörleri sigara, aromatik aminler (boya, kauçuk, tekstil), siklofosfamid ve pelvik radyoterapidir.`,A:`Pürülan inflamasyon; erkekte ödemli hiperemik üretral meatus; Gram boyasında nötrofiller içinde Gram negatif diplokoklar. Tanıda NAAT tercih edilir; kültür antibiyotik duyarlılığı için kullanılır.`,E:`Retroperitoneal yapıları saran fibroinflamatuar doku tablosudur; üreter daralması veya tıkanıklığına yol açabilir; orta-ileri yaşta ve erkeklerde daha sık görülür.`,C:`Primer dönemde genitalde spesifik olmayan üretrit, papül veya küçük ülser; sekonder dönemde şiş, hassas ve birleşip fistülize olabilen drenaj lenf düğümleri; uzun dönemde anogenital bölge ve rektumda fibrozis ve darlıklar.`,D:`Nadir fakat önemli üç grup: konjenital darlık (UPJ tıkanıklığı), neoplazmlar (genellikle ürotelyal karsinom) ve reaktif süreçler (retroperitoneal fibrozis).`},dogru:`B`,aciklama:`Doğru: Mesane kanserlerinin ~%90'ı ürotelyal karsinomdur; majör risk faktörleri sigara, aromatik aminler (boya, kauçuk, tekstil), siklofosfamid ve pelvik radyoterapidir.`,sik_aciklamalari:{B:`Doğru. Mesane kanserlerinin ~%90'ı ürotelyal karsinomdur; majör risk faktörleri sigara, aromatik aminler (boya, kauçuk, tekstil), siklofosfamid ve pelvik radyoterapidir.`,A:`Yanlış. Pürülan inflamasyon; erkekte ödemli hiperemik üretral meatus; Gram boyasında nötrofiller içinde Gram negatif diplokoklar. Tanıda NAAT tercih edilir; kültür antibiyotik duyarlılığı için kullanılır.`,E:`Yanlış. Retroperitoneal yapıları saran fibroinflamatuar doku tablosudur; üreter daralması veya tıkanıklığına yol açabilir; orta-ileri yaşta ve erkeklerde daha sık görülür.`,C:`Yanlış. Primer dönemde genitalde spesifik olmayan üretrit, papül veya küçük ülser; sekonder dönemde şiş, hassas ve birleşip fistülize olabilen drenaj lenf düğümleri; uzun dönemde anogenital bölge ve rektumda fibrozis ve darlıklar.`,D:`Yanlış. Nadir fakat önemli üç grup: konjenital darlık (UPJ tıkanıklığı), neoplazmlar (genellikle ürotelyal karsinom) ve reaktif süreçler (retroperitoneal fibrozis).`},bilgi:[14],benzer_cikmis:[]},{id:`k1-46-mesane-hastaliklari-ve-tumorleri-k07-q10`,kazanim:7,zorluk:`orta`,soru:`"Sifilisin patognomonik lezyonu" kavramı hakkında verilen aşağıdakilerden hangisi doğrudur?`,secenekler:{E:`Tüm evrelerde proliferatif endarterit ve plazma hücre zengin infiltrat vardır.`,C:`Nadir fakat önemli üç grup: konjenital darlık (UPJ tıkanıklığı), neoplazmlar (genellikle ürotelyal karsinom) ve reaktif süreçler (retroperitoneal fibrozis).`,A:`Etken penisiline son derece duyarlıdır. Nontreponemal testler (RPR, VDRL; antikardiyolipin) tedavi izleminde kullanılır ve titre düşer; treponemal testler (T. pallidum spesifik antikor) genellikle ömür boyu pozitif kalır.`,B:`Dört veya dokuz değerliklidir; düşük riskli tip 6 ve 11'e karşı koruma sağlar, anogenital siğilleri önler ve HPV ilişkili karsinom insidansını (özellikle serviks) azaltır.`,D:`En sık etkenler E. coli (koliformlar), Proteus, Klebsiella ve Enterobacter türleridir.`},dogru:`E`,aciklama:`Doğru: Tüm evrelerde proliferatif endarterit ve plazma hücre zengin infiltrat vardır.`,sik_aciklamalari:{E:`Doğru. Tüm evrelerde proliferatif endarterit ve plazma hücre zengin infiltrat vardır.`,C:`Yanlış. Nadir fakat önemli üç grup: konjenital darlık (UPJ tıkanıklığı), neoplazmlar (genellikle ürotelyal karsinom) ve reaktif süreçler (retroperitoneal fibrozis).`,A:`Yanlış. Etken penisiline son derece duyarlıdır. Nontreponemal testler (RPR, VDRL; antikardiyolipin) tedavi izleminde kullanılır ve titre düşer; treponemal testler (T. pallidum spesifik antikor) genellikle ömür boyu pozitif kalır.`,B:`Yanlış. Dört veya dokuz değerliklidir; düşük riskli tip 6 ve 11'e karşı koruma sağlar, anogenital siğilleri önler ve HPV ilişkili karsinom insidansını (özellikle serviks) azaltır.`,D:`Yanlış. En sık etkenler E. coli (koliformlar), Proteus, Klebsiella ve Enterobacter türleridir.`},bilgi:[18],benzer_cikmis:[]},{id:`k1-46-mesane-hastaliklari-ve-tumorleri-k07-q11`,kazanim:7,zorluk:`zor`,soru:`"Sifilis tanı ve tedavi" bilgisini içeren doğru kurulum aşağıdakilerden hangisidir?`,secenekler:{A:`Etken penisiline son derece duyarlıdır. Nontreponemal testler (RPR, VDRL; antikardiyolipin) tedavi izleminde kullanılır ve titre düşer; treponemal testler (T. pallidum spesifik antikor) genellikle ömür boyu pozitif kalır.`,C:`Düşük dereceli papiller yol FGFR3 ve HRAS ile; yüksek dereceli CIS-invaziv yol TP53 ve RB ile ilişkilidir.`,B:`Konjenital bozukluktur; bebek/çocukta hidronefrozun en sık nedenidir ve erkek çocuklarda daha sık görülür.`,E:`Mesane duvarında mukozanın kese benzeri invajinasyonudur; konjenital (kas tabakasında fokal zayıflık) veya edinilmiş (distal obstrüksiyon: BPH, üretra darlığı) olabilir.`,D:`Primer dönemde genitalde spesifik olmayan üretrit, papül veya küçük ülser; sekonder dönemde şiş, hassas ve birleşip fistülize olabilen drenaj lenf düğümleri; uzun dönemde anogenital bölge ve rektumda fibrozis ve darlıklar.`},dogru:`A`,aciklama:`Doğru: Etken penisiline son derece duyarlıdır. Nontreponemal testler (RPR, VDRL; antikardiyolipin) tedavi izleminde kullanılır ve titre düşer; treponemal testler (T. pallidum spesifik antikor) genellikle ömür boyu pozitif kalır.`,sik_aciklamalari:{A:`Doğru. Etken penisiline son derece duyarlıdır. Nontreponemal testler (RPR, VDRL; antikardiyolipin) tedavi izleminde kullanılır ve titre düşer; treponemal testler (T. pallidum spesifik antikor) genellikle ömür boyu pozitif kalır.`,C:`Yanlış. Düşük dereceli papiller yol FGFR3 ve HRAS ile; yüksek dereceli CIS-invaziv yol TP53 ve RB ile ilişkilidir.`,B:`Yanlış. Konjenital bozukluktur; bebek/çocukta hidronefrozun en sık nedenidir ve erkek çocuklarda daha sık görülür.`,E:`Yanlış. Mesane duvarında mukozanın kese benzeri invajinasyonudur; konjenital (kas tabakasında fokal zayıflık) veya edinilmiş (distal obstrüksiyon: BPH, üretra darlığı) olabilir.`,D:`Yanlış. Primer dönemde genitalde spesifik olmayan üretrit, papül veya küçük ülser; sekonder dönemde şiş, hassas ve birleşip fistülize olabilen drenaj lenf düğümleri; uzun dönemde anogenital bölge ve rektumda fibrozis ve darlıklar.`},bilgi:[22],benzer_cikmis:[]}],ilgili_cikmis:[]},{no:8,metin:`Cinsel yolla bulaşan enfeksiyonların ortak özelliklerini ve risk davranışlarını açıklayabilmek`,sorular:[{id:`k1-46-q23`,kazanim:8,zorluk:`kolay`,soru:`En sık görülen bakteriyel cinsel yolla bulaşan enfeksiyon etkeni hangisidir?`,secenekler:{A:`Treponema pallidum`,B:`Neisseria gonorrhoeae`,C:`Chlamydia trachomatis`,D:`Haemophilus ducreyi`,E:`Ureaplasma urealyticum`},dogru:`C`,aciklama:`C. trachomatis en sık bakteriyel CYBE etkenidir; N. gonorrhoeae ikinci sıradadır.`,sik_aciklamalari:{A:`Sifilis daha seyrektir.`,B:`Gonore klamidyadan sonra ikinci sık bakteriyel CYBE'dir.`,C:`Doğru: gonokok dışı üretritin de en sık etkenidir.`,D:`Şankroid nadirdir: haemophilus ducreyi.`,E:`Ureaplasma NGU etkenlerinden biridir ama en sık değildir.`},bilgi:[23,26],benzer_cikmis:[]},{id:`k1-46-q24`,kazanim:8,zorluk:`orta`,soru:`Cinsel yolla bulaşan enfeksiyonların ortak özellikleri ile ilgili aşağıdakilerden hangisi doğrudur?`,secenekler:{A:`Yenidoğana hiçbir zaman bulaşmaz`,B:`Her zaman belirgin semptomlarla seyreder`,C:`Yalnızca erkekleri etkiler`,D:`Birden fazla etkenle koinfeksiyon sıktır; bu nedenle bir CYBE saptanınca diğerleri de araştırılmalıdır`,E:`Tanıda yalnızca kültür kullanılır`},dogru:`D`,aciklama:`Gonore–klamidya koinfeksiyonu sıktır, trichomoniasis tanısında eşzamanlı klamidya/gonore testleri yapılır; birçok CYBE asemptomatik seyreder.`,sik_aciklamalari:{A:`Sifilis, gonore, klamidya ve herpes yenidoğana bulaşabilir.`,B:`Klamidya, gonore (kadında) ve trichomoniasis sıklıkla asemptomatiktir.`,C:`Her iki cinsiyet etkilenir.`,D:`Doğru: koinfeksiyon ve birlikte test yaklaşımı ortak özelliktir.`,E:`NAAT gibi moleküler yöntemler yaygın kullanılır.`},bilgi:[24,28,34],benzer_cikmis:[]},{id:`k1-46-q25`,kazanim:8,zorluk:`zor`,soru:`Korunmasız cinsel ilişki sonrası üretral akıntı ile başvuran erkekte gonore saptanıyor.

Bu hastaya yaklaşımda aşağıdakilerden hangisi en uygundur?`,secenekler:{A:`Yalnızca gonoreyi tedavi edip başka test yapmamak`,B:`Sık eşlik eden Chlamydia trachomatis koinfeksiyonunu da araştırmak`,C:`Partner değerlendirmesini gereksiz saymak`,D:`Klamidyayı dışlamak için Gram boyamaya güvenmek`,E:`Semptom geçince takibi bırakmak`},dogru:`B`,aciklama:`Gonorede klamidya koinfeksiyonu sıktır; CYBE tanısında diğer etkenler de araştırılmalıdır.`,sik_aciklamalari:{A:`Koinfeksiyon atlanırsa komplikasyon riski sürer.`,B:`Doğru: koinfeksiyon taraması standart yaklaşımdır.`,C:`Partnerlerin değerlendirilmesi yeniden enfeksiyonu önler.`,D:`Klamidya hücre içi bakteri olup Gram boyama ile gösterilemez; NAAT gerekir.`,E:`Asemptomatik seyir bulaşı ve komplikasyonu sürdürebilir.`},bilgi:[24,27,28],benzer_cikmis:[`d3-b-032`]},{id:`k1-46-mesane-hastaliklari-ve-tumorleri-k08-q04`,kazanim:8,zorluk:`orta`,soru:`Genç erişkinlerde tekrarlayan CYBE görülüyor; korunma danışmanlığı veriliyor. Aşağıdakilerden hangisi doğrudur?`,secenekler:{A:`CYBE'de taşıyıcılık önemsizdir`,B:`PID yalnızca erkeklerde olur`,C:`Asemptomatik taşıyıcılık en önemli rezervuardır; yukarı yayılım kadında PID yapar; gebelikte konjenital risk vardır`,D:`Gebelikte bulaş riski yoktur`,E:`Prezervatif riski artırır`},dogru:`C`,aciklama:`Asemptomatik taşıyıcılık yayılımı sürdürür; PID ve yenidoğan riski ortak temadır.`,sik_aciklamalari:{A:`Yanlış: bu seçenek vakadaki tabloyla uyumlu değildir; doğru yanıt 'Asemptomatik taşıyıcılık en önemli rezervuardır; yukarı yayılım kadında PID yapar; gebelikte konjenital risk vardır' seçeneğidir.`,B:`Yanlış: bu seçenek vakadaki tabloyla uyumlu değildir; doğru yanıt 'Asemptomatik taşıyıcılık en önemli rezervuardır; yukarı yayılım kadında PID yapar; gebelikte konjenital risk vardır' seçeneğidir.`,C:`Doğru: Asemptomatik taşıyıcılık yayılımı sürdürür; PID ve yenidoğan riski ortak temadır.`,D:`Yanlış: bu seçenek vakadaki tabloyla uyumlu değildir; doğru yanıt 'Asemptomatik taşıyıcılık en önemli rezervuardır; yukarı yayılım kadında PID yapar; gebelikte konjenital risk vardır' seçeneğidir.`,E:`Yanlış: bu seçenek vakadaki tabloyla uyumlu değildir; doğru yanıt 'Asemptomatik taşıyıcılık en önemli rezervuardır; yukarı yayılım kadında PID yapar; gebelikte konjenital risk vardır' seçeneğidir.`},bilgi:[14,15,16],benzer_cikmis:[]},{id:`k1-46-mesane-hastaliklari-ve-tumorleri-k08-q05`,kazanim:8,zorluk:`zor`,soru:`Risk davranışları sıralanıyor (erken aktivite, çoklu partner, düzensiz prezervatif). Aşağıdakilerden hangisi yanlıştır?`,secenekler:{A:`Düzensiz prezervatif ve kısıtlı sağlık erişimi riski artırır`,B:`Erken cinsel aktivite ve çoklu partner riski artırır`,C:`Etkenler bakteri, spiroket, protozoon ve virüsleri içerir`,D:`Tek eşlilik ve düzenli prezervatif CYBE riskini artırır; asemptomatik taşıyıcılık bulaşmada rol oynamaz`,E:`Yerleşim üretral/vajinal/servikal/rektal/orofaringeal mukozalardır`},dogru:`B`,aciklama:`Korunma riski azaltır; taşıyıcılık ana rezervuardır. Son ifade yanlıştır.`,sik_aciklamalari:{A:`Yanlış: bu seçenek vakadaki tabloyla uyumlu değildir; doğru yanıt 'Erken cinsel aktivite ve çoklu partner riski artırır' seçeneğidir.`,B:`Doğru: Korunma riski azaltır; taşıyıcılık ana rezervuardır. Son ifade yanlıştır.`,C:`Yanlış: bu seçenek vakadaki tabloyla uyumlu değildir; doğru yanıt 'Erken cinsel aktivite ve çoklu partner riski artırır' seçeneğidir.`,D:`Yanlış: bu seçenek vakadaki tabloyla uyumlu değildir; doğru yanıt 'Erken cinsel aktivite ve çoklu partner riski artırır' seçeneğidir.`,E:`Yanlış: bu seçenek vakadaki tabloyla uyumlu değildir; doğru yanıt 'Erken cinsel aktivite ve çoklu partner riski artırır' seçeneğidir.`},bilgi:[14,15,16],benzer_cikmis:[]},{id:`k1-46-mesane-hastaliklari-ve-tumorleri-k08-q06`,kazanim:8,zorluk:`orta`,soru:`Cinsel yolla bulaşan enfeksiyonların ortak bulaş özelliği nedir?`,secenekler:{A:`Yalnızca kan transfüzyonuyla bulaşırlar`,B:`Solunum yoluyla toplumda yayılırlar`,C:`Vektör ısırığıyla bulaşma esastır`,D:`Su ve besinlerle salgın yaparlar`,E:`Mukoza temasıyla bulaşır; korunmasız ilişki risklidir`},dogru:`E`,aciklama:`CYBE'ler enfekte mukoza ve deri temasıyla bulaşır; çok eşlilik ve korunmasız ilişki riski artırır. Etkenler ürogenital mukozaya tropizm gösterir. Eş zamanlı birden fazla etken sık görüldüğünden tarama birlikte yapılır.`,sik_aciklamalari:{A:`Yanlış: Transfüzyon CYBE bulaş yolu değildir.`,B:`Yanlış: Solunum yolu bulaşı CYBE'lerde söz konusu değildir.`,C:`Yanlış: Vektörler CYBE etkenlerini taşımaz.`,D:`Yanlış: Su-besin bulaşı enterik enfeksiyonlara aittir.`,E:`Doğru: Doğrudan mukoza teması ve korunmasız ilişki bulaştırır.`},bilgi:[23,26],benzer_cikmis:[]},{id:`k1-46-mesane-hastaliklari-ve-tumorleri-k08-q07`,kazanim:8,zorluk:`orta`,soru:`CYBE'ler arasında sıklık açısından öne çıkan grup hangisidir?`,secenekler:{A:`Sifilis tüm CYBE'lerden daha sıktır`,B:`NGU en sık grup; klamidya başı çeker`,C:`Şankroid en yaygın bakteriyel CYBE'dir`,D:`LGV toplumda en sık görülendir`,E:`Gonore viral CYBE'lerden sayılır`},dogru:`B`,aciklama:`Gonore ikinci sık bakteriyel CYBE iken gonokok dışı üretrit-servisit grubu en sık CYBE grubudur. Klamidya bu grupta ilk sıradadır. Bu sıklık tarama stratejilerinin önceliğini belirler.`,sik_aciklamalari:{A:`Yanlış: Klamidya ve NGU grubu sifilisten sıktır.`,B:`Doğru: Gonokok dışı üretrit en sık gruptur.`,C:`Yanlış: Şankroid nadir görülen ülseratif CYBE'dir.`,D:`Yanlış: LGV belirli risk gruplarında yoğunlaşır.`,E:`Yanlış: Gonore bakteriyel bir CYBE'dir.`},bilgi:[23,26],benzer_cikmis:[]},{id:`k1-46-mesane-hastaliklari-ve-tumorleri-k08-q08`,kazanim:8,zorluk:`kolay`,soru:`"Klamidya komplikasyonları ve tanısı" ifadesi ile ilgili aşağıdakilerden hangisi doğrudur?`,secenekler:{E:`Erkekte epididimit ve prostatit; kadında infertilite ve ektopik gebelik; yenidoğanda konjonktivit ve pnömoni (vajinal doğumda bulaş).`,A:`Mesane kanserlerinin ~%90'ı ürotelyal karsinomdur; majör risk faktörleri sigara, aromatik aminler (boya, kauçuk, tekstil), siklofosfamid ve pelvik radyoterapidir.`,B:`Mesane mukozasının inflamasyonudur; etiyolojisi çoğunlukla bakteriyeldir, ayrıca kimyasal (ilaç), radyasyon, cihaz ve otoimmün nedenler olabilir.`,D:`Enfeksiyondan ortalama 21 gün sonra gelişir; erkekte penis/skrotum (%70), kadında vulva/serviks (~%50) yerleşir; tabanda belirgin indürasyonlu sert şankr oluşur.`,C:`IgG4 ilişkili hastalık, maligniteler (lenfoma, ürotelyal karsinom), radyasyon, cerrahi ve bazı ilaçlar (ergot türevleri, adrenerjik blokerler, TNF inhibitörleri) ile ilişkilidir.`},dogru:`E`,aciklama:`Doğru: Erkekte epididimit ve prostatit; kadında infertilite ve ektopik gebelik; yenidoğanda konjonktivit ve pnömoni (vajinal doğumda bulaş).`,sik_aciklamalari:{E:`Doğru. Erkekte epididimit ve prostatit; kadında infertilite ve ektopik gebelik; yenidoğanda konjonktivit ve pnömoni (vajinal doğumda bulaş).`,A:`Yanlış. Mesane kanserlerinin ~%90'ı ürotelyal karsinomdur; majör risk faktörleri sigara, aromatik aminler (boya, kauçuk, tekstil), siklofosfamid ve pelvik radyoterapidir.`,B:`Yanlış. Mesane mukozasının inflamasyonudur; etiyolojisi çoğunlukla bakteriyeldir, ayrıca kimyasal (ilaç), radyasyon, cihaz ve otoimmün nedenler olabilir.`,D:`Yanlış. Enfeksiyondan ortalama 21 gün sonra gelişir; erkekte penis/skrotum (%70), kadında vulva/serviks (~%50) yerleşir; tabanda belirgin indürasyonlu sert şankr oluşur.`,C:`Yanlış. IgG4 ilişkili hastalık, maligniteler (lenfoma, ürotelyal karsinom), radyasyon, cerrahi ve bazı ilaçlar (ergot türevleri, adrenerjik blokerler, TNF inhibitörleri) ile ilişkilidir.`},bilgi:[28],benzer_cikmis:[]},{id:`k1-46-mesane-hastaliklari-ve-tumorleri-k08-q09`,kazanim:8,zorluk:`orta`,soru:`"Sifilis etken ve bulaş" ile ilgili aşağıdakilerden hangisi yanlıştır?`,secenekler:{A:`Etken Treponema pallidum (spiroket); bulaş erken evre deri/mukoza lezyonlarıyla temasla ve konjenital olarak plasenta yoluyla olur.`,D:`Retroperitoneal yapıları saran fibroinflamatuar doku tablosudur; üreter daralması veya tıkanıklığına yol açabilir; orta-ileri yaşta ve erkeklerde daha sık görülür.`,C:`Uzun süreli enfeksiyon, taş, kateter ve şistozomiyazis ürotelyumda reaktif değişikliklere ve skuamöz metaplaziye yol açar.`,B:`Primer dönemde genitalde spesifik olmayan üretrit, papül veya küçük ülser; sekonder dönemde şiş, hassas ve birleşip fistülize olabilen drenaj lenf düğümleri; uzun dönemde anogenital bölge ve rektumda fibrozis ve darlıklar.`,E:`Konjenital bozukluktur; bebek/çocukta hidronefrozun en sık nedenidir ve erkek çocuklarda daha sık görülür.`},dogru:`A`,aciklama:`Doğru: Etken Treponema pallidum (spiroket); bulaş erken evre deri/mukoza lezyonlarıyla temasla ve konjenital olarak plasenta yoluyla olur.`,sik_aciklamalari:{A:`Doğru. Etken Treponema pallidum (spiroket); bulaş erken evre deri/mukoza lezyonlarıyla temasla ve konjenital olarak plasenta yoluyla olur.`,D:`Yanlış. Retroperitoneal yapıları saran fibroinflamatuar doku tablosudur; üreter daralması veya tıkanıklığına yol açabilir; orta-ileri yaşta ve erkeklerde daha sık görülür.`,C:`Yanlış. Uzun süreli enfeksiyon, taş, kateter ve şistozomiyazis ürotelyumda reaktif değişikliklere ve skuamöz metaplaziye yol açar.`,B:`Yanlış. Primer dönemde genitalde spesifik olmayan üretrit, papül veya küçük ülser; sekonder dönemde şiş, hassas ve birleşip fistülize olabilen drenaj lenf düğümleri; uzun dönemde anogenital bölge ve rektumda fibrozis ve darlıklar.`,E:`Yanlış. Konjenital bozukluktur; bebek/çocukta hidronefrozun en sık nedenidir ve erkek çocuklarda daha sık görülür.`},bilgi:[17],benzer_cikmis:[]},{id:`k1-46-mesane-hastaliklari-ve-tumorleri-k08-q10`,kazanim:8,zorluk:`orta`,soru:`"Ürotelyal karsinom genetik yolları" kavramı hakkında verilen aşağıdakilerden hangisi doğrudur?`,secenekler:{A:`Düşük dereceli papiller yol FGFR3 ve HRAS ile; yüksek dereceli CIS-invaziv yol TP53 ve RB ile ilişkilidir.`,D:`Enfeksiyondan ortalama 21 gün sonra gelişir; erkekte penis/skrotum (%70), kadında vulva/serviks (~%50) yerleşir; tabanda belirgin indürasyonlu sert şankr oluşur.`,C:`Siklofosfamidin akrolein metaboliti ve adenovirus enfeksiyonları ile ilişkilidir.`,B:`Erkekte epididimit ve prostatit; kadında infertilite ve ektopik gebelik; yenidoğanda konjonktivit ve pnömoni (vajinal doğumda bulaş).`,E:`Gebeliğin herhangi bir döneminde plasenta yoluyla bulaşır; intrauterin/perinatal ölüm ~%25 olabilir. Erken form hepatosplenomegali, snuffles, döküntü ve iskelet lezyonları; geç form Hutchinson triadı (interstisyel keratit, Hutchinson dişleri, sinir işitme kaybı).`},dogru:`A`,aciklama:`Doğru: Düşük dereceli papiller yol FGFR3 ve HRAS ile; yüksek dereceli CIS-invaziv yol TP53 ve RB ile ilişkilidir.`,sik_aciklamalari:{A:`Doğru. Düşük dereceli papiller yol FGFR3 ve HRAS ile; yüksek dereceli CIS-invaziv yol TP53 ve RB ile ilişkilidir.`,D:`Yanlış. Enfeksiyondan ortalama 21 gün sonra gelişir; erkekte penis/skrotum (%70), kadında vulva/serviks (~%50) yerleşir; tabanda belirgin indürasyonlu sert şankr oluşur.`,C:`Yanlış. Siklofosfamidin akrolein metaboliti ve adenovirus enfeksiyonları ile ilişkilidir.`,B:`Yanlış. Erkekte epididimit ve prostatit; kadında infertilite ve ektopik gebelik; yenidoğanda konjonktivit ve pnömoni (vajinal doğumda bulaş).`,E:`Yanlış. Gebeliğin herhangi bir döneminde plasenta yoluyla bulaşır; intrauterin/perinatal ölüm ~%25 olabilir. Erken form hepatosplenomegali, snuffles, döküntü ve iskelet lezyonları; geç form Hutchinson triadı (interstisyel keratit, Hutchinson dişleri, sinir işitme kaybı).`},bilgi:[15],benzer_cikmis:[]},{id:`k1-46-mesane-hastaliklari-ve-tumorleri-k08-q11`,kazanim:8,zorluk:`zor`,soru:`"Konjenital sifilis" klinik bağlamda aşağıdakilerden hangisi doğrudur?`,secenekler:{C:`Gebeliğin herhangi bir döneminde plasenta yoluyla bulaşır; intrauterin/perinatal ölüm ~%25 olabilir. Erken form hepatosplenomegali, snuffles, döküntü ve iskelet lezyonları; geç form Hutchinson triadı (interstisyel keratit, Hutchinson dişleri, sinir işitme kaybı).`,A:`Böbrek pelvisi, üreter, mesane ve üretra ürotelyum (geçiş epiteli) ile kaplıdır; altında lamina propria ve muskularis propria (mesanede detrusor kası) vardır.`,E:`IgG4 ilişkili hastalık, maligniteler (lenfoma, ürotelyal karsinom), radyasyon, cerrahi ve bazı ilaçlar (ergot türevleri, adrenerjik blokerler, TNF inhibitörleri) ile ilişkilidir.`,D:`En sık bulgu ağrısız makroskopik veya mikroskopik hematüridir; tanıda sistoskopi + biyopsi ve idrar sitolojisi (özellikle yüksek dereceli ve CIS) kullanılır.`,B:`Düşük dereceli papiller yol FGFR3 ve HRAS ile; yüksek dereceli CIS-invaziv yol TP53 ve RB ile ilişkilidir.`},dogru:`C`,aciklama:`Doğru: Gebeliğin herhangi bir döneminde plasenta yoluyla bulaşır; intrauterin/perinatal ölüm ~%25 olabilir. Erken form hepatosplenomegali, snuffles, döküntü ve iskelet lezyonları; geç form Hutchinson triadı (interstisyel keratit, Hutchinson dişleri, sinir işitme kaybı).`,sik_aciklamalari:{C:`Doğru. Gebeliğin herhangi bir döneminde plasenta yoluyla bulaşır; intrauterin/perinatal ölüm ~%25 olabilir. Erken form hepatosplenomegali, snuffles, döküntü ve iskelet lezyonları; geç form Hutchinson triadı (interstisyel keratit, Hutchinson dişleri, sinir işitme kaybı).`,A:`Yanlış. Böbrek pelvisi, üreter, mesane ve üretra ürotelyum (geçiş epiteli) ile kaplıdır; altında lamina propria ve muskularis propria (mesanede detrusor kası) vardır.`,E:`Yanlış. IgG4 ilişkili hastalık, maligniteler (lenfoma, ürotelyal karsinom), radyasyon, cerrahi ve bazı ilaçlar (ergot türevleri, adrenerjik blokerler, TNF inhibitörleri) ile ilişkilidir.`,D:`Yanlış. En sık bulgu ağrısız makroskopik veya mikroskopik hematüridir; tanıda sistoskopi + biyopsi ve idrar sitolojisi (özellikle yüksek dereceli ve CIS) kullanılır.`,B:`Yanlış. Düşük dereceli papiller yol FGFR3 ve HRAS ile; yüksek dereceli CIS-invaziv yol TP53 ve RB ile ilişkilidir.`},bilgi:[21],benzer_cikmis:[]}],ilgili_cikmis:[{id:`d3-b-032`,soru:`Otuz beş yaşında erkek hasta, 1 haftadır devam eden penis ucundan sarı renkli akıntı ve idrarda yanma şikâyeti ile polikliniğe başvuruyor. Hastanın üretral akıntı örneğinin Gram boyamasında her sahada 3 tane PMNL ve bu lökositlerin içinde gram negatif diplokoklar görülüyor. Bu olguda düşünülecek en olası klinik tablo ve etken mikroorganizma aşağıdakilerden hangisidir?`,secenekler:{A:`Epididimoorşit – Streptococcus pneumoniae`,B:`Prostatit – Chlamydia trachomatis`,C:`Üretrit – Neisseria gonorrhoeae`,D:`Epididimoorşit – Mycoplasma genitalium`,E:`Üretrit – Treponema pallidum`},cevap:`C`}]},{no:9,metin:`Sifilisin etkenini, evrelerini, patognomonik lezyonunu ve tanısını açıklayabilmek`,sorular:[{id:`k1-46-q26`,kazanim:9,zorluk:`kolay`,soru:`Sifilisin tüm evrelerinde görülen patognomonik histolojik lezyon hangisidir?`,secenekler:{A:`Cowdry tip A inklüzyon`,B:`Kazeifiye granülom`,C:`Koilositoz`,D:`Proliferatif endarterit ve plazma hücresinden zengin infiltrat`,E:`Yıldızsı apse`},dogru:`D`,aciklama:`Sifiliste tüm evrelerde proliferatif endarterit ve plazma hücresinden zengin infiltrat görülür; lümen daralması iskemiye yol açar.`,sik_aciklamalari:{A:`Cowdry A inklüzyonu herpes enfeksiyonunda görülür.`,B:`Kazeifiye granülom tüberkülozun bulgusudur.`,C:`Koilositoz HPV enfeksiyonunun bulgusudur.`,D:`Doğru: sifilisin patognomonik lezyonudur.`,E:`Yıldızsı apse lenfogranüloma venereumda görülür.`},bilgi:[18],benzer_cikmis:[]},{id:`k1-46-q27`,kazanim:9,zorluk:`orta`,soru:`Genital bölgede 1–2 cm çaplı, tabanı sert (indüre) ve ağrısız tek ülser saptanan hastada en olası tanı hangisidir?`,secenekler:{A:`Genital herpes`,B:`Şankroid`,C:`Primer sifilis (sert şankr)`,D:`Kondiloma akuminata`,E:`Trichomoniasis`},dogru:`C`,aciklama:`Primer sifiliste enfeksiyondan ~21 gün sonra tabanı belirgin indüre, ağrısız şankr gelişir ve kendiliğinden iyileşir.`,sik_aciklamalari:{A:`Herpes ağrılı vezikül ve ülserlerle seyreder.`,B:`Şankroid ağrılı, çoklu ve indürasyonsuz ülser yapar.`,C:`Doğru: ağrısız, indüre ülser sert şankrdır.`,D:`Kondiloma papiller siğil şeklindedir, ülser değildir.`,E:`Trichomoniasis ülser değil vajinit/üretrit yapar.`},bilgi:[19,31],benzer_cikmis:[`608fd8157f3b`]},{id:`k1-46-q28`,kazanim:9,zorluk:`zor`,soru:`Sifilis evreleri ve tanısı ile ilgili aşağıdakilerden hangisi yanlıştır?`,secenekler:{A:`Sekonder sifiliste anogenital bölgede kondiloma lata görülür`,B:`Tersiyer sifiliste gumma, kardiyovasküler sifilis ve nörosifilis gelişebilir`,C:`Nontreponemal testler (RPR, VDRL) tedavi izleminde kullanılır`,D:`Treponemal testler genellikle ömür boyu pozitif kalır`,E:`Serolojik testlerin duyarlılığı primer sifiliste sekonder sifilise göre daha yüksektir`},dogru:`E`,aciklama:`Serolojinin duyarlılığı primer sifiliste sınırlı, sekonder sifiliste çok yüksektir.`,sik_aciklamalari:{A:`Doğru ifade: kondiloma lata geniş tabanlı kabarık lezyonlardır (kondiloma akuminata ile karıştırılmamalıdır).`,B:`Doğru ifade: tersiyer evre 5–20 yıl sonra görülür.`,C:`Doğru ifade: tedaviyle titre düşer.`,D:`Doğru ifade: treponemal antikorlar kalıcıdır.`,E:`Yanlış ifade (aranan cevap): duyarlılık sekonder evrede en yüksektir.`},bilgi:[20,22],benzer_cikmis:[`84eda84539cb`,`14db0e045e06`]},{id:`k1-46-mesane-hastaliklari-ve-tumorleri-k09-q04`,kazanim:9,zorluk:`orta`,soru:`Genital bölgede ağrısız sert ülseri olan hastada dark-field incelemesi isteniyor. Aşağıdakilerden hangisi doğrudur?`,secenekler:{A:`Etken N. gonorrhoeae'dir`,B:`Şankr ağrılıdır ve 1 günde çıkar`,C:`Endarterit sifilizde görülmez`,D:`Sifiliz yalnızca kutanözdür`,E:`Etken Treponema pallidum'dur; patognomonik lezyon proliferatif endarterit + plazma hücre zengin infiltrattır; primer şankr ~21. günde ağrısızdır`},dogru:`E`,aciklama:`Sifilis spiroketaldir; endarterit + plazmositik infiltrat tipiktir; şankr ağrısız ve ~21 günde çıkar.`,sik_aciklamalari:{A:`Yanlış: bu seçenek vakadaki tabloyla uyumlu değildir; doğru yanıt 'Etken Treponema pallidum'dur; patognomonik lezyon proliferatif endarterit + plazma hücre zengin infiltrattır; primer şankr ~21. günde ağrısızdır' seçeneğidir.`,B:`Yanlış: bu seçenek vakadaki tabloyla uyumlu değildir; doğru yanıt 'Etken Treponema pallidum'dur; patognomonik lezyon proliferatif endarterit + plazma hücre zengin infiltrattır; primer şankr ~21. günde ağrısızdır' seçeneğidir.`,C:`Yanlış: bu seçenek vakadaki tabloyla uyumlu değildir; doğru yanıt 'Etken Treponema pallidum'dur; patognomonik lezyon proliferatif endarterit + plazma hücre zengin infiltrattır; primer şankr ~21. günde ağrısızdır' seçeneğidir.`,D:`Yanlış: bu seçenek vakadaki tabloyla uyumlu değildir; doğru yanıt 'Etken Treponema pallidum'dur; patognomonik lezyon proliferatif endarterit + plazma hücre zengin infiltrattır; primer şankr ~21. günde ağrısızdır' seçeneğidir.`,E:`Doğru: Sifilis spiroketaldir; endarterit + plazmositik infiltrat tipiktir; şankr ağrısız ve ~21 günde çıkar.`},bilgi:[17,18,19],benzer_cikmis:[]},{id:`k1-46-mesane-hastaliklari-ve-tumorleri-k09-q05`,kazanim:9,zorluk:`zor`,soru:`Sekonder döküntü ve tersiyer gumma ile seroloji (RPR/VDRL vs treponemal) tartışılıyor. Aşağıdakilerden hangisi yanlıştır?`,secenekler:{A:`Tersiyerde kardiyovasküler tutulum, nörosifilis ve gumma (kauçuksu kitle) görülür`,B:`Nontreponemal testler tedavi izleminde titre düşer; treponemal testler ömür boyu pozitif kalır`,C:`Sifilizde gumma bulaştırıcı şankrdır ve treponemal testler tedaviyle negatifleşir`,D:`Etken penisiline duyarlıdır`,E:`Sekonderde döküntü, mukokutanöz lezyonlar ve LAP; kondiloma lata görülür`},dogru:`E`,aciklama:`Gumma tersiyer steril granülomdur; treponemal testler pozitif kalır.`,sik_aciklamalari:{A:`Yanlış: bu seçenek vakadaki tabloyla uyumlu değildir; doğru yanıt 'Sekonderde döküntü, mukokutanöz lezyonlar ve LAP; kondiloma lata görülür' seçeneğidir.`,B:`Yanlış: bu seçenek vakadaki tabloyla uyumlu değildir; doğru yanıt 'Sekonderde döküntü, mukokutanöz lezyonlar ve LAP; kondiloma lata görülür' seçeneğidir.`,C:`Yanlış: bu seçenek vakadaki tabloyla uyumlu değildir; doğru yanıt 'Sekonderde döküntü, mukokutanöz lezyonlar ve LAP; kondiloma lata görülür' seçeneğidir.`,D:`Yanlış: bu seçenek vakadaki tabloyla uyumlu değildir; doğru yanıt 'Sekonderde döküntü, mukokutanöz lezyonlar ve LAP; kondiloma lata görülür' seçeneğidir.`,E:`Doğru: Gumma tersiyer steril granülomdur; treponemal testler pozitif kalır.`},bilgi:[20,22],benzer_cikmis:[]},{id:`k1-46-mesane-hastaliklari-ve-tumorleri-k09-q06`,kazanim:9,zorluk:`orta`,soru:`Sifilis etkeninin morfolojisi ve dokudaki tipik inflamatuar paterni nedir?`,secenekler:{A:`Etken Gram negatif diplokoktur`,B:`Etken kamçılı protozoondur`,C:`Etken zorunlu hücre içi kokobasildir`,D:`Spiroket; endarterit ve plazmositik infiltrat tipiktir`,E:`Etken zarfsız DNA virusudur`},dogru:`D`,aciklama:`Etken Treponema pallidum adlı spirokettir; erken evre deri-mukoza lezyonlarıyla temas ve plasenta yoluyla bulaşır. Tüm evrelerde proliferatif endarterit ve plazma hücrelerinden zengin infiltrat görülür. Bu vasküler-hücresel patern patognomoniktir.`,sik_aciklamalari:{A:`Yanlış: Diplokok tanımı gonokoklara aittir.`,B:`Yanlış: Kamçılı protozoon trikomonası tanımlar.`,C:`Yanlış: Bu tanım Haemophilus ducreyi'ye uyar.`,D:`Doğru: T. pallidum spirokettir; endarterit tipiktir.`,E:`Yanlış: Virus değil, spiral bakteridir.`},bilgi:[17,18],benzer_cikmis:[]},{id:`k1-46-mesane-hastaliklari-ve-tumorleri-k09-q07`,kazanim:9,zorluk:`orta`,soru:`Sifilisin evrelere göre klinik seyri nasıl özetlenir?`,secenekler:{A:`Sert şankr, sekonder döküntü, geç kardiyovasküler tutulum`,B:`Ağrılı çoklu ülser, drenajlı lenfadenopati, darlık`,C:`Vezikül, dev hücre, intranükleer inklüzyon üçlüsü`,D:`Köpüklü akıntı, hareketli protozoon, kaşıntı`,E:`Papiller siğil, koilositoz, servikal displazi`},dogru:`A`,aciklama:`Primer lezyon enfeksiyondan ortalama 21 gün sonra gelişen tabanda indürasyonlu sert şankrdır. Sekonder evre döküntü, mukokutanöz lezyonlar ve lenfadenopatiyle seyreder; kondiloma lata geniştir. Tersiyer evre yıllar sonra kardiyovasküler ve nörolojik tutulum yapar. Tanıda nontreponemal testler izlemde, treponemal testler doğrulamada kullanılır.`,sik_aciklamalari:{A:`Doğru: Evre sırası şankr, sekonder yayılım ve geç tutulumdur.`,B:`Yanlış: Bu tablo şankroid ve LGV'yi tanımlar.`,C:`Yanlış: Bu bulgular genital herpese aittir.`,D:`Yanlış: Bu tablo trikomoniyazı tanımlar.`,E:`Yanlış: Bu bulgular HPV enfeksiyonuna aittir.`},bilgi:[19,20,22],benzer_cikmis:[`0be5e7c85f2e`]},{id:`k1-46-mesane-hastaliklari-ve-tumorleri-k09-q08`,kazanim:9,zorluk:`kolay`,soru:`"Konjenital sifilis" ifadesi ile ilgili aşağıdakilerden hangisi doğrudur?`,secenekler:{D:`Gebeliğin herhangi bir döneminde plasenta yoluyla bulaşır; intrauterin/perinatal ölüm ~%25 olabilir. Erken form hepatosplenomegali, snuffles, döküntü ve iskelet lezyonları; geç form Hutchinson triadı (interstisyel keratit, Hutchinson dişleri, sinir işitme kaybı).`,E:`En sık etkenler E. coli (koliformlar), Proteus, Klebsiella ve Enterobacter türleridir.`,C:`En sık bulgu ağrısız makroskopik veya mikroskopik hematüridir; tanıda sistoskopi + biyopsi ve idrar sitolojisi (özellikle yüksek dereceli ve CIS) kullanılır.`,B:`Histolojide yüzeyde nötrofiller ve fibrin kaplı ülser, altta granülasyon dokusu, nekroz ve tromboze damarlar, periferde lenfoplazmasitik infiltrat; lenf nodlarında nekrotizan inflamasyon, apse ve drenaj ülserleri.`,A:`Düşük dereceli papiller yol FGFR3 ve HRAS ile; yüksek dereceli CIS-invaziv yol TP53 ve RB ile ilişkilidir.`},dogru:`D`,aciklama:`Doğru: Gebeliğin herhangi bir döneminde plasenta yoluyla bulaşır; intrauterin/perinatal ölüm ~%25 olabilir. Erken form hepatosplenomegali, snuffles, döküntü ve iskelet lezyonları; geç form Hutchinson triadı (interstisyel keratit, Hutchinson dişleri, sinir işitme kaybı).`,sik_aciklamalari:{D:`Doğru. Gebeliğin herhangi bir döneminde plasenta yoluyla bulaşır; intrauterin/perinatal ölüm ~%25 olabilir. Erken form hepatosplenomegali, snuffles, döküntü ve iskelet lezyonları; geç form Hutchinson triadı (interstisyel keratit, Hutchinson dişleri, sinir işitme kaybı).`,E:`Yanlış. En sık etkenler E. coli (koliformlar), Proteus, Klebsiella ve Enterobacter türleridir.`,C:`Yanlış. En sık bulgu ağrısız makroskopik veya mikroskopik hematüridir; tanıda sistoskopi + biyopsi ve idrar sitolojisi (özellikle yüksek dereceli ve CIS) kullanılır.`,B:`Yanlış. Histolojide yüzeyde nötrofiller ve fibrin kaplı ülser, altta granülasyon dokusu, nekroz ve tromboze damarlar, periferde lenfoplazmasitik infiltrat; lenf nodlarında nekrotizan inflamasyon, apse ve drenaj ülserleri.`,A:`Yanlış. Düşük dereceli papiller yol FGFR3 ve HRAS ile; yüksek dereceli CIS-invaziv yol TP53 ve RB ile ilişkilidir.`},bilgi:[21],benzer_cikmis:[]},{id:`k1-46-mesane-hastaliklari-ve-tumorleri-k09-q09`,kazanim:9,zorluk:`orta`,soru:`"Kronik irritasyon ve metaplezi" ile ilgili aşağıdakilerden hangisi yanlıştır?`,secenekler:{A:`Uzun süreli enfeksiyon, taş, kateter ve şistozomiyazis ürotelyumda reaktif değişikliklere ve skuamöz metaplaziye yol açar.`,D:`C. trachomatis'in farklı (L1-L3) serovarlarına bağlı kronik, ülseratif CYBE; özellikle erkeklerle cinsel ilişkiye giren erkeklerde kasık lenfadenopatisi ve proktit görülür, HIV koinfeksiyonuyla güçlü ilişkilidir.`,C:`Etken Neisseria gonorrhoeae (Gram negatif diplokok); Chlamydia trachomatis'ten sonra ikinci sık bakteriyel CYBE'dir; cinsel temasla ve enfekte mukozaya doğrudan temasla bulaşır.`,E:`Etken HSV-1 ve HSV-2; genital olgular çoğunlukla HSV-2 ile oluşur ancak HSV-1 ile genital olgular artmaktadır. Bulaş enfekte mukoza/deri ile doğrudan temasla olur; virüs çevrede hızlı inaktive olur.`,B:`Mesane kanserlerinin ~%90'ı ürotelyal karsinomdur; majör risk faktörleri sigara, aromatik aminler (boya, kauçuk, tekstil), siklofosfamid ve pelvik radyoterapidir.`},dogru:`A`,aciklama:`Doğru: Uzun süreli enfeksiyon, taş, kateter ve şistozomiyazis ürotelyumda reaktif değişikliklere ve skuamöz metaplaziye yol açar.`,sik_aciklamalari:{A:`Doğru. Uzun süreli enfeksiyon, taş, kateter ve şistozomiyazis ürotelyumda reaktif değişikliklere ve skuamöz metaplaziye yol açar.`,D:`Yanlış. C. trachomatis'in farklı (L1-L3) serovarlarına bağlı kronik, ülseratif CYBE; özellikle erkeklerle cinsel ilişkiye giren erkeklerde kasık lenfadenopatisi ve proktit görülür, HIV koinfeksiyonuyla güçlü ilişkilidir.`,C:`Yanlış. Etken Neisseria gonorrhoeae (Gram negatif diplokok); Chlamydia trachomatis'ten sonra ikinci sık bakteriyel CYBE'dir; cinsel temasla ve enfekte mukozaya doğrudan temasla bulaşır.`,E:`Yanlış. Etken HSV-1 ve HSV-2; genital olgular çoğunlukla HSV-2 ile oluşur ancak HSV-1 ile genital olgular artmaktadır. Bulaş enfekte mukoza/deri ile doğrudan temasla olur; virüs çevrede hızlı inaktive olur.`,B:`Yanlış. Mesane kanserlerinin ~%90'ı ürotelyal karsinomdur; majör risk faktörleri sigara, aromatik aminler (boya, kauçuk, tekstil), siklofosfamid ve pelvik radyoterapidir.`},bilgi:[12],benzer_cikmis:[]},{id:`k1-46-mesane-hastaliklari-ve-tumorleri-k09-q10`,kazanim:9,zorluk:`orta`,soru:`"Gonore etken ve bulaş" ile ilgili aşağıdakilerden hangisi yanlıştır?`,secenekler:{B:`Etken Neisseria gonorrhoeae (Gram negatif diplokok); Chlamydia trachomatis'ten sonra ikinci sık bakteriyel CYBE'dir; cinsel temasla ve enfekte mukozaya doğrudan temasla bulaşır.`,E:`Endemik şistozomiyazis bölgelerinde kronik sistit, skuamöz metaplazi ve skuamöz hücreli karsinom insidansı artar; patogenez kronik inflamasyon + metaplazi → displazi → karsinomdur.`,C:`Gebeliğin herhangi bir döneminde plasenta yoluyla bulaşır; intrauterin/perinatal ölüm ~%25 olabilir. Erken form hepatosplenomegali, snuffles, döküntü ve iskelet lezyonları; geç form Hutchinson triadı (interstisyel keratit, Hutchinson dişleri, sinir işitme kaybı).`,A:`Etken Haemophilus ducreyi (Gram negatif kokobasil); 4-7 gün inkübasyondan sonra dış genitalde papül hızla ağrılı ülsere dönüşür, çoklu ülserler sıktır ve sert indürasyon yoktur.`,D:`Erkekte epididimit ve prostatit; kadında infertilite ve ektopik gebelik; yenidoğanda konjonktivit ve pnömoni (vajinal doğumda bulaş).`},dogru:`B`,aciklama:`Doğru: Etken Neisseria gonorrhoeae (Gram negatif diplokok); Chlamydia trachomatis'ten sonra ikinci sık bakteriyel CYBE'dir; cinsel temasla ve enfekte mukozaya doğrudan temasla bulaşır.`,sik_aciklamalari:{B:`Doğru. Etken Neisseria gonorrhoeae (Gram negatif diplokok); Chlamydia trachomatis'ten sonra ikinci sık bakteriyel CYBE'dir; cinsel temasla ve enfekte mukozaya doğrudan temasla bulaşır.`,E:`Yanlış. Endemik şistozomiyazis bölgelerinde kronik sistit, skuamöz metaplazi ve skuamöz hücreli karsinom insidansı artar; patogenez kronik inflamasyon + metaplazi → displazi → karsinomdur.`,C:`Yanlış. Gebeliğin herhangi bir döneminde plasenta yoluyla bulaşır; intrauterin/perinatal ölüm ~%25 olabilir. Erken form hepatosplenomegali, snuffles, döküntü ve iskelet lezyonları; geç form Hutchinson triadı (interstisyel keratit, Hutchinson dişleri, sinir işitme kaybı).`,A:`Yanlış. Etken Haemophilus ducreyi (Gram negatif kokobasil); 4-7 gün inkübasyondan sonra dış genitalde papül hızla ağrılı ülsere dönüşür, çoklu ülserler sıktır ve sert indürasyon yoktur.`,D:`Yanlış. Erkekte epididimit ve prostatit; kadında infertilite ve ektopik gebelik; yenidoğanda konjonktivit ve pnömoni (vajinal doğumda bulaş).`},bilgi:[23],benzer_cikmis:[]},{id:`k1-46-mesane-hastaliklari-ve-tumorleri-k09-q11`,kazanim:9,zorluk:`zor`,soru:`"Mesane divertikülü" klinik bağlamda aşağıdakilerden hangisi doğrudur?`,secenekler:{E:`Mesane duvarında mukozanın kese benzeri invajinasyonudur; konjenital (kas tabakasında fokal zayıflık) veya edinilmiş (distal obstrüksiyon: BPH, üretra darlığı) olabilir.`,B:`Böbrek pelvisi, üreter, mesane ve üretra ürotelyum (geçiş epiteli) ile kaplıdır; altında lamina propria ve muskularis propria (mesanede detrusor kası) vardır.`,C:`Etken Haemophilus ducreyi (Gram negatif kokobasil); 4-7 gün inkübasyondan sonra dış genitalde papül hızla ağrılı ülsere dönüşür, çoklu ülserler sıktır ve sert indürasyon yoktur.`,D:`HPV genital sistemde kondiloma akuminatum, prekanseröz skuamöz lezyonlar ve karsinomlar (serviks, penis, vulva, orofaringeal tonsil, konjonktiva) yapar. Kondiloma akuminatum etkeni düşük riskli HPV tip 6 ve 11'dir.`,A:`Siklofosfamidin akrolein metaboliti ve adenovirus enfeksiyonları ile ilişkilidir.`},dogru:`E`,aciklama:`Doğru: Mesane duvarında mukozanın kese benzeri invajinasyonudur; konjenital (kas tabakasında fokal zayıflık) veya edinilmiş (distal obstrüksiyon: BPH, üretra darlığı) olabilir.`,sik_aciklamalari:{E:`Doğru. Mesane duvarında mukozanın kese benzeri invajinasyonudur; konjenital (kas tabakasında fokal zayıflık) veya edinilmiş (distal obstrüksiyon: BPH, üretra darlığı) olabilir.`,B:`Yanlış. Böbrek pelvisi, üreter, mesane ve üretra ürotelyum (geçiş epiteli) ile kaplıdır; altında lamina propria ve muskularis propria (mesanede detrusor kası) vardır.`,C:`Yanlış. Etken Haemophilus ducreyi (Gram negatif kokobasil); 4-7 gün inkübasyondan sonra dış genitalde papül hızla ağrılı ülsere dönüşür, çoklu ülserler sıktır ve sert indürasyon yoktur.`,D:`Yanlış. HPV genital sistemde kondiloma akuminatum, prekanseröz skuamöz lezyonlar ve karsinomlar (serviks, penis, vulva, orofaringeal tonsil, konjonktiva) yapar. Kondiloma akuminatum etkeni düşük riskli HPV tip 6 ve 11'dir.`,A:`Yanlış. Siklofosfamidin akrolein metaboliti ve adenovirus enfeksiyonları ile ilişkilidir.`},bilgi:[6],benzer_cikmis:[]}],ilgili_cikmis:[{id:`608fd8157f3b`,soru:`e fizik muayenede 1-2 cm, tabanı sert ülser saptanan, LAP saptanmayan hastada öncelikle düşünülmesi gerek enfeksiyon hastalığı hangisidir?`,secenekler:{A:`HSV enfeksiyonu`,B:`Lenfogranüloma venerum`,C:`Sifiliz`,D:`Şankroid`,E:`Granüloma inguinale`},cevap:`C`},{id:`84eda84539cb`,soru:`Sifiliz ile ilgili hangisi doğrudur?`,secenekler:{A:`Sekonder sifilizde anogenital bölgede kondiloma aküminata adı verilen lezyonlar görülür (terminal dönem)`,B:`El ayaları ve ayak tabanlarında deri tutulumu sık görülür (sekonder sifiliz doğru)`,C:`Gomlarda bulaşıcılık yüksektir (tersiyer sifiliz)`,D:`Primer sfilizde yumuşak şankr görülür`,E:`Tersiyer sifiliz vakalarının %80’inden fazlasını nörosifiliz`},cevap:`B`},{id:`14db0e045e06`,soru:`Sifiliz kliniği için hangisi yanlıştır?`,secenekler:{A:`Primer sifilizde şankr mevcuttur`,B:`Sekonder si asemtomatiktir`,C:`Latent sifilizde treponemal testler pozitiftir`,D:`Tersiyer sifilizde nörolojik tutulum görülür`,E:`Tersiyer sifilizde gommatöz lezyonlar görülür`},cevap:`B`}]},{no:10,metin:`Konjenital sifilisi ve Hutchinson triadını bilmek`,sorular:[{id:`k1-46-q29`,kazanim:10,zorluk:`kolay`,soru:`Konjenital sifiliste görülen Hutchinson triadında aşağıdakilerden hangisi yer almaz?`,secenekler:{A:`İnterstisyel keratit`,B:`Hutchinson dişleri`,C:`Sinir tipi işitme kaybı`,D:`Hepatosplenomegali`,E:`Sekizinci kranial sinir tutulumuna bağlı sağırlık`},dogru:`D`,aciklama:`Hutchinson triadı interstisyel keratit, Hutchinson dişleri ve sensörinöral işitme kaybıdır; hepatosplenomegali erken konjenital sifilis bulgusudur.`,sik_aciklamalari:{A:`Triadın bileşenidir.`,B:`Triadın bileşenidir; kesici dişler tornavida/çivi şeklindedir.`,C:`Triadın bileşenidir.`,D:`Doğru: hepatosplenomegali erken form bulgusudur, triadda yer almaz.`,E:`Sinir tipi işitme kaybının bir ifadesidir ve triadın bileşenidir.`},bilgi:[21],benzer_cikmis:[]},{id:`k1-46-q30`,kazanim:10,zorluk:`orta`,soru:`Konjenital sifilis ile ilgili aşağıdakilerden hangisi doğrudur?`,secenekler:{A:`Erken formda Hutchinson dişleri görülür`,B:`Yalnızca doğum kanalından geçişte bulaşır`,C:`İntrauterin ölüme yol açmaz`,D:`Gebeliğin herhangi bir döneminde plasenta yoluyla bulaşabilir`,E:`Treponema pallidum penisiline dirençlidir`},dogru:`D`,aciklama:`Konjenital sifilis gebeliğin herhangi bir döneminde transplasental bulaşır; intrauterin/perinatal ölüm ~%25 olabilir.`,sik_aciklamalari:{A:`Hutchinson dişleri geç form bulgusudur.`,B:`Bulaş plasenta yoluyladır, yalnız doğumda değil.`,C:`İntrauterin/perinatal ölüm önemli bir sonuçtur.`,D:`Doğru: transplasental bulaş temel yoldur.`,E:`Etken penisiline son derece duyarlıdır.`},bilgi:[21,22],benzer_cikmis:[]},{id:`k1-46-q31`,kazanim:10,zorluk:`zor`,soru:`Yenidoğan bir bebekte burun akıntısı (snuffles), deri döküntüsü, hepatosplenomegali ve iskelet lezyonları saptanıyor. Annenin gebelikte izlemi yapılmamış.

Bu bebekte ileride gelişebilecek geç bulgu hangisidir?`,secenekler:{A:`Hunner ülseri`,B:`Kondiloma akuminata`,C:`İnterstisyel keratit`,D:`Yıldızsı apseler`,E:`Koilositoz`},dogru:`C`,aciklama:`Tablo erken konjenital sifilistir; geç formda Hutchinson triadı (interstisyel keratit, Hutchinson dişleri, işitme kaybı) gelişebilir.`,sik_aciklamalari:{A:`Hunner ülseri interstisyel sistitin lezyonudur.`,B:`Kondiloma akuminata HPV 6/11 ile ilişkilidir.`,C:`Doğru: interstisyel keratit Hutchinson triadının bileşenidir.`,D:`Yıldızsı apseler LGV'nin histolojik bulgusudur.`,E:`Koilositoz HPV'nin sitopatik etkisidir.`},bilgi:[21],benzer_cikmis:[]},{id:`k1-46-mesane-hastaliklari-ve-tumorleri-k10-q04`,kazanim:10,zorluk:`orta`,soru:`Tedavisiz sifilizli gebenin bebeğinde hepatosplenomegali ve döküntü izleniyor. Aşağıdakilerden hangisi doğrudur?`,secenekler:{A:`Konjenital sifilis yalnızca doğum sonrası bulaşır`,B:`Konjenital sifilis plasenta yoluyla bulaşır; geç form Hutchinson triadıdır (interstisyel keratit, Hutchinson dişleri, sinirsel işitme kaybı)`,C:`Hutchinson triadı akciğer bulgusudur`,D:`İntrauterin ölüm riski yoktur`,E:`Erken formda iskelet tutulumu olmaz`},dogru:`B`,aciklama:`Plasental geçiş intrauterin/perinatal ölüme yol açabilir; triad göz-diş-kulaktır.`,sik_aciklamalari:{A:`Yanlış: bu seçenek vakadaki tabloyla uyumlu değildir; doğru yanıt 'Konjenital sifilis plasenta yoluyla bulaşır; geç form Hutchinson triadıdır (interstisyel keratit, Hutchinson dişleri, sinirsel işitme kaybı)' seçeneğidir.`,B:`Doğru: Plasental geçiş intrauterin/perinatal ölüme yol açabilir; triad göz-diş-kulaktır.`,C:`Yanlış: bu seçenek vakadaki tabloyla uyumlu değildir; doğru yanıt 'Konjenital sifilis plasenta yoluyla bulaşır; geç form Hutchinson triadıdır (interstisyel keratit, Hutchinson dişleri, sinirsel işitme kaybı)' seçeneğidir.`,D:`Yanlış: bu seçenek vakadaki tabloyla uyumlu değildir; doğru yanıt 'Konjenital sifilis plasenta yoluyla bulaşır; geç form Hutchinson triadıdır (interstisyel keratit, Hutchinson dişleri, sinirsel işitme kaybı)' seçeneğidir.`,E:`Yanlış: bu seçenek vakadaki tabloyla uyumlu değildir; doğru yanıt 'Konjenital sifilis plasenta yoluyla bulaşır; geç form Hutchinson triadıdır (interstisyel keratit, Hutchinson dişleri, sinirsel işitme kaybı)' seçeneğidir.`},bilgi:[21],benzer_cikmis:[]},{id:`k1-46-mesane-hastaliklari-ve-tumorleri-k10-q05`,kazanim:10,zorluk:`zor`,soru:`Erken ve geç konjenital bulgular karşılaştırılıyor. Aşağıdakilerden hangisi yanlıştır?`,secenekler:{A:`Geç form: interstisyel keratit, Hutchinson dişleri, işitme kaybı`,B:`İntrauterin/perinatal ölüm ~%25 olabilir`,C:`Erken form: hepatosplenomegali, snuffles, döküntü, iskelet lezyonları`,D:`Konjenital sifilis cinsel yolla bulaşan erişkin hastalıktır ve plasentadan geçmez; triad barsak bulgusudur`,E:`Hutchinson dişleri ön kesicileri etkiler`},dogru:`C`,aciklama:`Konjenital geçiş plasentaldir; triad göz-diş-kulaktır.`,sik_aciklamalari:{A:`Yanlış: bu seçenek vakadaki tabloyla uyumlu değildir; doğru yanıt 'Erken form: hepatosplenomegali, snuffles, döküntü, iskelet lezyonları' seçeneğidir.`,B:`Yanlış: bu seçenek vakadaki tabloyla uyumlu değildir; doğru yanıt 'Erken form: hepatosplenomegali, snuffles, döküntü, iskelet lezyonları' seçeneğidir.`,C:`Doğru: Konjenital geçiş plasentaldir; triad göz-diş-kulaktır.`,D:`Yanlış: bu seçenek vakadaki tabloyla uyumlu değildir; doğru yanıt 'Erken form: hepatosplenomegali, snuffles, döküntü, iskelet lezyonları' seçeneğidir.`,E:`Yanlış: bu seçenek vakadaki tabloyla uyumlu değildir; doğru yanıt 'Erken form: hepatosplenomegali, snuffles, döküntü, iskelet lezyonları' seçeneğidir.`},bilgi:[21],benzer_cikmis:[]},{id:`k1-46-mesane-hastaliklari-ve-tumorleri-k10-q06`,kazanim:10,zorluk:`orta`,soru:`Konjenital sifilisin bulaş yolu ve fetal riski nedir?`,secenekler:{A:`Yalnızca doğum sırasında bulaşır`,B:`Plasenta bariyeri bulaşı tamamen engeller`,C:`Plasentayla bulaşır; perinatal ölüm ~%25'tir`,D:`Anne enfeksiyonu fetüsü hiç etkilemez`,E:`Bulaş yalnızca emzirmeyle olur`},dogru:`C`,aciklama:`Konjenital sifilis gebeliğin herhangi bir döneminde plasenta yoluyla bulaşır; intrauterin veya perinatal ölüm %25'e ulaşabilir. Erken formda hepatosplenomegali, snuffles, döküntü ve iskelet lezyonları görülür. Erken tanı ve penisilin tedavisi sekelleri önler.`,sik_aciklamalari:{A:`Yanlış: Bulaş gebeliğin her döneminde transplasentaldir.`,B:`Yanlış: Spiroket plasentayı geçerek fetüsü enfekte eder.`,C:`Doğru: Transplasental bulaş yüksek fetal kayıpla seyreder.`,D:`Yanlış: Fetal enfeksiyon multisistem tutulum yapar.`,E:`Yanlış: Emzirme bulaş yolu değildir.`},bilgi:[21],benzer_cikmis:[]},{id:`k1-46-mesane-hastaliklari-ve-tumorleri-k10-q07`,kazanim:10,zorluk:`orta`,soru:`Hutchinson triadını oluşturan bulgular hangileridir?`,secenekler:{A:`Şankr, döküntü ve lenfadenopati üçlüsü`,B:`Ateş, artralji ve üveit üçlüsü`,C:`Vezikül, ülser ve nöralji üçlüsü`,D:`Akıntı, dizüri ve epididimit üçlüsü`,E:`Keratit, Hutchinson dişi ve sağırlık`},dogru:`E`,aciklama:`Geç konjenital sifiliste Hutchinson triadı interstisyel keratit, Hutchinson dişleri ve sekizinci sinir sağırlığından oluşur. Triad geç tutulumun kalıcı sekellerini yansıtır. Diş ve göz bulguları gelişim dönemindeki hasarı gösterir.`,sik_aciklamalari:{A:`Yanlış: Bunlar edinsel sifilisin evre bulgularıdır.`,B:`Yanlış: Bu üçlü Hutchinson triadını oluşturmaz.`,C:`Yanlış: Bu bulgular herpetik enfeksiyona aittir.`,D:`Yanlış: Bu tablo gonore ve klamidyaya uyar.`,E:`Doğru: Keratit, diş anomalisi ve sağırlık geç triadı oluşturur.`},bilgi:[21],benzer_cikmis:[]},{id:`k1-46-mesane-hastaliklari-ve-tumorleri-k10-q08`,kazanim:10,zorluk:`kolay`,soru:`"Alt idrar yolu yapısı" ifadesi ile ilgili aşağıdakilerden hangisi doğrudur?`,secenekler:{E:`Böbrek pelvisi, üreter, mesane ve üretra ürotelyum (geçiş epiteli) ile kaplıdır; altında lamina propria ve muskularis propria (mesanede detrusor kası) vardır.`,A:`Erkekte epididimit ve prostatit; kadında infertilite ve ektopik gebelik; yenidoğanda konjonktivit ve pnömoni (vajinal doğumda bulaş).`,D:`Etken penisiline son derece duyarlıdır. Nontreponemal testler (RPR, VDRL; antikardiyolipin) tedavi izleminde kullanılır ve titre düşer; treponemal testler (T. pallidum spesifik antikor) genellikle ömür boyu pozitif kalır.`,C:`Gebeliğin herhangi bir döneminde plasenta yoluyla bulaşır; intrauterin/perinatal ölüm ~%25 olabilir. Erken form hepatosplenomegali, snuffles, döküntü ve iskelet lezyonları; geç form Hutchinson triadı (interstisyel keratit, Hutchinson dişleri, sinir işitme kaybı).`,B:`Pürülan inflamasyon; erkekte ödemli hiperemik üretral meatus; Gram boyasında nötrofiller içinde Gram negatif diplokoklar. Tanıda NAAT tercih edilir; kültür antibiyotik duyarlılığı için kullanılır.`},dogru:`E`,aciklama:`Doğru: Böbrek pelvisi, üreter, mesane ve üretra ürotelyum (geçiş epiteli) ile kaplıdır; altında lamina propria ve muskularis propria (mesanede detrusor kası) vardır.`,sik_aciklamalari:{E:`Doğru. Böbrek pelvisi, üreter, mesane ve üretra ürotelyum (geçiş epiteli) ile kaplıdır; altında lamina propria ve muskularis propria (mesanede detrusor kası) vardır.`,A:`Yanlış. Erkekte epididimit ve prostatit; kadında infertilite ve ektopik gebelik; yenidoğanda konjonktivit ve pnömoni (vajinal doğumda bulaş).`,D:`Yanlış. Etken penisiline son derece duyarlıdır. Nontreponemal testler (RPR, VDRL; antikardiyolipin) tedavi izleminde kullanılır ve titre düşer; treponemal testler (T. pallidum spesifik antikor) genellikle ömür boyu pozitif kalır.`,C:`Yanlış. Gebeliğin herhangi bir döneminde plasenta yoluyla bulaşır; intrauterin/perinatal ölüm ~%25 olabilir. Erken form hepatosplenomegali, snuffles, döküntü ve iskelet lezyonları; geç form Hutchinson triadı (interstisyel keratit, Hutchinson dişleri, sinir işitme kaybı).`,B:`Yanlış. Pürülan inflamasyon; erkekte ödemli hiperemik üretral meatus; Gram boyasında nötrofiller içinde Gram negatif diplokoklar. Tanıda NAAT tercih edilir; kültür antibiyotik duyarlılığı için kullanılır.`},bilgi:[1],benzer_cikmis:[]},{id:`k1-46-mesane-hastaliklari-ve-tumorleri-k10-q09`,kazanim:10,zorluk:`orta`,soru:`"Gonore etken ve bulaş" kavramı hakkında verilen aşağıdakilerden hangisi doğrudur?`,secenekler:{A:`Etken Neisseria gonorrhoeae (Gram negatif diplokok); Chlamydia trachomatis'ten sonra ikinci sık bakteriyel CYBE'dir; cinsel temasla ve enfekte mukozaya doğrudan temasla bulaşır.`,D:`Mesane mukozasının inflamasyonudur; etiyolojisi çoğunlukla bakteriyeldir, ayrıca kimyasal (ilaç), radyasyon, cihaz ve otoimmün nedenler olabilir.`,E:`Kronik pelvik ağrı ve Hunner ülseri ile seyreder; kültür negatiftir ve daha çok kadınlarda görülür.`,B:`Retroperitoneal yapıları saran fibroinflamatuar doku tablosudur; üreter daralması veya tıkanıklığına yol açabilir; orta-ileri yaşta ve erkeklerde daha sık görülür.`,C:`Erkekte üretrit (dizüri, sık idrara çıkma, mukopürülan akıntı), kadında çoğu zaman asemptomatik seyir; tedavi edilmezse PID, infertilite ve ektopik gebelik gelişir.`},dogru:`A`,aciklama:`Doğru: Etken Neisseria gonorrhoeae (Gram negatif diplokok); Chlamydia trachomatis'ten sonra ikinci sık bakteriyel CYBE'dir; cinsel temasla ve enfekte mukozaya doğrudan temasla bulaşır.`,sik_aciklamalari:{A:`Doğru. Etken Neisseria gonorrhoeae (Gram negatif diplokok); Chlamydia trachomatis'ten sonra ikinci sık bakteriyel CYBE'dir; cinsel temasla ve enfekte mukozaya doğrudan temasla bulaşır.`,D:`Yanlış. Mesane mukozasının inflamasyonudur; etiyolojisi çoğunlukla bakteriyeldir, ayrıca kimyasal (ilaç), radyasyon, cihaz ve otoimmün nedenler olabilir.`,E:`Yanlış. Kronik pelvik ağrı ve Hunner ülseri ile seyreder; kültür negatiftir ve daha çok kadınlarda görülür.`,B:`Yanlış. Retroperitoneal yapıları saran fibroinflamatuar doku tablosudur; üreter daralması veya tıkanıklığına yol açabilir; orta-ileri yaşta ve erkeklerde daha sık görülür.`,C:`Yanlış. Erkekte üretrit (dizüri, sık idrara çıkma, mukopürülan akıntı), kadında çoğu zaman asemptomatik seyir; tedavi edilmezse PID, infertilite ve ektopik gebelik gelişir.`},bilgi:[23],benzer_cikmis:[]},{id:`k1-46-mesane-hastaliklari-ve-tumorleri-k10-q10`,kazanim:10,zorluk:`orta`,soru:`"Chlamydia trachomatis enfeksiyonu" ile ilgili aşağıdakilerden hangisi yanlıştır?`,secenekler:{A:`Zorunlu hücre içi Gram negatif bakteri; elementer cisim (enfeksiyöz, ekstraselüler) ve retiküler cisim (metabolik aktif, hücre içi) formları vardır; kolumnar epitel tropizmi gösterir.`,B:`En sık bulgu ağrısız makroskopik veya mikroskopik hematüridir; tanıda sistoskopi + biyopsi ve idrar sitolojisi (özellikle yüksek dereceli ve CIS) kullanılır.`,E:`Etken Trichomonas vaginalis (kamçılı protozoon); genellikle cinsel temasla bulaşır. Kadında pruritus, bol köpüklü sarı-yeşil vajinal akıntı, üretral kolonizasyona bağlı dizüri; erkekte genelde hafif üretrit.`,D:`Mesane duvarında mukozanın kese benzeri invajinasyonudur; konjenital (kas tabakasında fokal zayıflık) veya edinilmiş (distal obstrüksiyon: BPH, üretra darlığı) olabilir.`,C:`Erkekte epididimit ve prostatit; kadında infertilite ve ektopik gebelik; yenidoğanda konjonktivit ve pnömoni (vajinal doğumda bulaş).`},dogru:`A`,aciklama:`Doğru: Zorunlu hücre içi Gram negatif bakteri; elementer cisim (enfeksiyöz, ekstraselüler) ve retiküler cisim (metabolik aktif, hücre içi) formları vardır; kolumnar epitel tropizmi gösterir.`,sik_aciklamalari:{A:`Doğru. Zorunlu hücre içi Gram negatif bakteri; elementer cisim (enfeksiyöz, ekstraselüler) ve retiküler cisim (metabolik aktif, hücre içi) formları vardır; kolumnar epitel tropizmi gösterir.`,B:`Yanlış. En sık bulgu ağrısız makroskopik veya mikroskopik hematüridir; tanıda sistoskopi + biyopsi ve idrar sitolojisi (özellikle yüksek dereceli ve CIS) kullanılır.`,E:`Yanlış. Etken Trichomonas vaginalis (kamçılı protozoon); genellikle cinsel temasla bulaşır. Kadında pruritus, bol köpüklü sarı-yeşil vajinal akıntı, üretral kolonizasyona bağlı dizüri; erkekte genelde hafif üretrit.`,D:`Yanlış. Mesane duvarında mukozanın kese benzeri invajinasyonudur; konjenital (kas tabakasında fokal zayıflık) veya edinilmiş (distal obstrüksiyon: BPH, üretra darlığı) olabilir.`,C:`Yanlış. Erkekte epididimit ve prostatit; kadında infertilite ve ektopik gebelik; yenidoğanda konjonktivit ve pnömoni (vajinal doğumda bulaş).`},bilgi:[27],benzer_cikmis:[]},{id:`k1-46-mesane-hastaliklari-ve-tumorleri-k10-q11`,kazanim:10,zorluk:`zor`,soru:`"Yenidoğan herpesi" ile ilgili bir hastada bulunacak aşağıdaki bulgulardan hangisi beklenmez?`,secenekler:{B:`Doğumda bulaşır; SEM (deri, göz, ağız) tutulumu, MSS tutulumu veya yaygın hastalık şeklinde olabilir.`,D:`Zorunlu hücre içi Gram negatif bakteri; elementer cisim (enfeksiyöz, ekstraselüler) ve retiküler cisim (metabolik aktif, hücre içi) formları vardır; kolumnar epitel tropizmi gösterir.`,A:`Erkekte epididimit ve prostatit; kadında infertilite ve ektopik gebelik; yenidoğanda konjonktivit ve pnömoni (vajinal doğumda bulaş).`,C:`Etken Trichomonas vaginalis (kamçılı protozoon); genellikle cinsel temasla bulaşır. Kadında pruritus, bol köpüklü sarı-yeşil vajinal akıntı, üretral kolonizasyona bağlı dizüri; erkekte genelde hafif üretrit.`,E:`Erkekte üretrit (dizüri, sık idrara çıkma, mukopürülan akıntı), kadında çoğu zaman asemptomatik seyir; tedavi edilmezse PID, infertilite ve ektopik gebelik gelişir.`},dogru:`B`,aciklama:`Doğru: Doğumda bulaşır; SEM (deri, göz, ağız) tutulumu, MSS tutulumu veya yaygın hastalık şeklinde olabilir.`,sik_aciklamalari:{B:`Doğru. Doğumda bulaşır; SEM (deri, göz, ağız) tutulumu, MSS tutulumu veya yaygın hastalık şeklinde olabilir.`,D:`Yanlış. Zorunlu hücre içi Gram negatif bakteri; elementer cisim (enfeksiyöz, ekstraselüler) ve retiküler cisim (metabolik aktif, hücre içi) formları vardır; kolumnar epitel tropizmi gösterir.`,A:`Yanlış. Erkekte epididimit ve prostatit; kadında infertilite ve ektopik gebelik; yenidoğanda konjonktivit ve pnömoni (vajinal doğumda bulaş).`,C:`Yanlış. Etken Trichomonas vaginalis (kamçılı protozoon); genellikle cinsel temasla bulaşır. Kadında pruritus, bol köpüklü sarı-yeşil vajinal akıntı, üretral kolonizasyona bağlı dizüri; erkekte genelde hafif üretrit.`,E:`Yanlış. Erkekte üretrit (dizüri, sık idrara çıkma, mukopürülan akıntı), kadında çoğu zaman asemptomatik seyir; tedavi edilmezse PID, infertilite ve ektopik gebelik gelişir.`},bilgi:[37],benzer_cikmis:[]}],ilgili_cikmis:[]},{no:11,metin:`Gonorenin etkenini, kliniğini, komplikasyonlarını ve tanısını açıklayabilmek`,sorular:[{id:`k1-46-q32`,kazanim:11,zorluk:`kolay`,soru:`Erkekte üretral akıntının Gram boyamasında nötrofiller içinde Gram negatif diplokoklar görülüyor.

En olası etken hangisidir?`,secenekler:{A:`Chlamydia trachomatis`,B:`Neisseria gonorrhoeae`,C:`Treponema pallidum`,D:`Trichomonas vaginalis`,E:`Haemophilus ducreyi`},dogru:`B`,aciklama:`Hücre içi Gram negatif diplokoklar gonore için tipiktir.`,sik_aciklamalari:{A:`Klamidya zorunlu hücre içi bakteridir, Gram boyamada görülmez.`,B:`Doğru: N. gonorrhoeae Gram negatif diplokoktur.`,C:`T. pallidum spirokettir ve Gram boyamada görülmez.`,D:`Trichomonas kamçılı protozoondur.`,E:`H. ducreyi Gram negatif kokobasildir.`},bilgi:[23,25],benzer_cikmis:[]},{id:`k1-46-q33`,kazanim:11,zorluk:`orta`,soru:`Gonore ile ilgili aşağıdakilerden hangisi yanlıştır?`,secenekler:{A:`Kadınlarda çoğunlukla asemptomatik seyreder`,B:`Tedavi edilmezse pelvik inflamatuar hastalık ve infertiliteye yol açabilir`,C:`Tanıda NAAT tercih edilir; kültür antibiyotik duyarlılığı için kullanılır`,D:`Yenidoğanda konjonktivit körlük riski taşır`,E:`Yalnızca üretrayı tutar; rektum ve orofarenks tutulumu olmaz`},dogru:`E`,aciklama:`Gonokok üretra, serviks, rektum, orofarenks ve konjonktivaya yerleşebilir.`,sik_aciklamalari:{A:`Doğru ifade: kadında asemptomatik seyir sıktır.`,B:`Doğru ifade: PID, infertilite ve ektopik gebelik komplikasyonlardır.`,C:`Doğru ifade: NAAT tanıda, kültür duyarlılık testinde kullanılır.`,D:`Doğru ifade: doğumda bulaşan konjonktivit körlük yapabilir.`,E:`Yanlış ifade (aranan cevap): ekstragenital tutulum olur.`},bilgi:[23,24,25],benzer_cikmis:[]},{id:`k1-46-q34`,kazanim:11,zorluk:`zor`,soru:`Yenidoğanlarda gonokokal konjonktiviti önlemek için doğumda uygulanan profilaksi ve bunun gerekçesi hangisidir?`,secenekler:{A:`Gümüş nitrat veya antibiyotikli göz damlası; doğum kanalında bulaşan enfeksiyonun körlüğe yol açabilmesi`,B:`HPV aşısı; kondilom önlenmesi`,C:`Penisilin enjeksiyonu; konjenital sifilisin tedavisi`,D:`Asiklovir; herpes keratiti`,E:`Profilaksi gerekmez; enfeksiyon kendiliğinden geçer`},dogru:`A`,aciklama:`Doğumda bulaşan gonokokal konjonktivit körlük riski taşır; gümüş nitrat veya antibiyotikli göz damlası ile profilaksi yapılır.`,sik_aciklamalari:{A:`Doğru: profilaksi körlüğü önlemeye yöneliktir.`,B:`HPV aşısı ergenlikte uygulanır ve göz profilaksisi değildir.`,C:`Konjenital sifilis tedavisi ayrı bir konudur.`,D:`Asiklovir rutin göz profilaksisi değildir.`,E:`Gonokokal konjonktivit ağır seyredebilir; profilaksi gerekir.`},bilgi:[25],benzer_cikmis:[]},{id:`k1-46-mesane-hastaliklari-ve-tumorleri-k11-q04`,kazanim:11,zorluk:`orta`,soru:`Genç erkekte mukopürülan üretral akıntı ve dizüri var; Gram boyamada nötrofil içi diplokoklar görülüyor. Aşağıdakilerden hangisi doğrudur?`,secenekler:{A:`Etken T. pallidum'dur`,B:`Tanıda yalnızca kültür yapılır`,C:`Kadında hep semptomatiktir`,D:`Etken Neisseria gonorrhoeae'dir (Gram negatif diplokok); tanıda NAAT tercih edilir; yenidoğanda konjonktivit körlük riski taşır`,E:`Komplikasyon yapmaz`},dogru:`D`,aciklama:`Gonore Gram negatif diplokoktur; NAAT tanıda tercih edilir; neonatal profilaksi körlüğü önler.`,sik_aciklamalari:{A:`Yanlış: bu seçenek vakadaki tabloyla uyumlu değildir; doğru yanıt 'Etken Neisseria gonorrhoeae'dir (Gram negatif diplokok); tanıda NAAT tercih edilir; yenidoğanda konjonktivit körlük riski taşır' seçeneğidir.`,B:`Yanlış: bu seçenek vakadaki tabloyla uyumlu değildir; doğru yanıt 'Etken Neisseria gonorrhoeae'dir (Gram negatif diplokok); tanıda NAAT tercih edilir; yenidoğanda konjonktivit körlük riski taşır' seçeneğidir.`,C:`Yanlış: bu seçenek vakadaki tabloyla uyumlu değildir; doğru yanıt 'Etken Neisseria gonorrhoeae'dir (Gram negatif diplokok); tanıda NAAT tercih edilir; yenidoğanda konjonktivit körlük riski taşır' seçeneğidir.`,D:`Doğru: Gonore Gram negatif diplokoktur; NAAT tanıda tercih edilir; neonatal profilaksi körlüğü önler.`,E:`Yanlış: bu seçenek vakadaki tabloyla uyumlu değildir; doğru yanıt 'Etken Neisseria gonorrhoeae'dir (Gram negatif diplokok); tanıda NAAT tercih edilir; yenidoğanda konjonktivit körlük riski taşır' seçeneğidir.`},bilgi:[23,24,25],benzer_cikmis:[]},{id:`k1-46-mesane-hastaliklari-ve-tumorleri-k11-q05`,kazanim:11,zorluk:`zor`,soru:`Tedavisiz kadında PID ve infertilite riski ile klamidya koinfeksiyonu tartışılıyor. Aşağıdakilerden hangisi yanlıştır?`,secenekler:{A:`Kadında çoğu olgu asemptomatiktir; tedavisiz PID, infertilite ve ektopik gebelik gelişir`,B:`Sıklıkla C. trachomatis koinfeksiyonu bulunur`,C:`Antibiyotik direnci artmaktadır`,D:`Gonore yalnızca üst solunumu tutar ve genital komplikasyon yapmaz; NAAT tanıda kullanılmaz`,E:`Morfolojide nötrofil içi Gram negatif diplokok tipiktir`},dogru:`A`,aciklama:`Gonore genital sistem ve yenidoğan gözünü tutar; NAAT kullanılır.`,sik_aciklamalari:{A:`Doğru: Gonore genital sistem ve yenidoğan gözünü tutar; NAAT kullanılır.`,B:`Yanlış: bu seçenek vakadaki tabloyla uyumlu değildir; doğru yanıt 'Kadında çoğu olgu asemptomatiktir; tedavisiz PID, infertilite ve ektopik gebelik gelişir' seçeneğidir.`,C:`Yanlış: bu seçenek vakadaki tabloyla uyumlu değildir; doğru yanıt 'Kadında çoğu olgu asemptomatiktir; tedavisiz PID, infertilite ve ektopik gebelik gelişir' seçeneğidir.`,D:`Yanlış: bu seçenek vakadaki tabloyla uyumlu değildir; doğru yanıt 'Kadında çoğu olgu asemptomatiktir; tedavisiz PID, infertilite ve ektopik gebelik gelişir' seçeneğidir.`,E:`Yanlış: bu seçenek vakadaki tabloyla uyumlu değildir; doğru yanıt 'Kadında çoğu olgu asemptomatiktir; tedavisiz PID, infertilite ve ektopik gebelik gelişir' seçeneğidir.`},bilgi:[23,24,25],benzer_cikmis:[]},{id:`k1-46-mesane-hastaliklari-ve-tumorleri-k11-q06`,kazanim:11,zorluk:`orta`,soru:`Gonore etkeninin morfolojisi ve kadınlardaki tipik seyri nedir?`,secenekler:{A:`Gram pozitif basil; erkekte hep asemptomatik`,B:`Gram negatif diplokok; kadında sıklıkla asemptomatik`,C:`Spiroket; ağrısız sert ülser yapar`,D:`Kamçılı protozoon; köpüklü akıntı yapar`,E:`Zarflı virus; veziküler döküntü yapar`},dogru:`B`,aciklama:`Etken Neisseria gonorrhoeae adlı Gram negatif diplokoktur ve klamidyadan sonra ikinci sık bakteriyel CYBE'dir. Erkekte dizüri ve mukopürülan akıntılı üretrit yapar; kadında çoğu zaman asemptomatiktir. Asemptomatik seyir yayılımı kolaylaştırır.`,sik_aciklamalari:{A:`Yanlış: Etken diplokoktur ve erkek olgular semptomatiktir.`,B:`Doğru: Gonokok diplokoktur; kadın enfeksiyonu sessiz seyreder.`,C:`Yanlış: Spiroket ve şankr sifilize aittir.`,D:`Yanlış: Protozoon trikomoniyaz etkenidir.`,E:`Yanlış: Veziküler tablo herpese aittir.`},bilgi:[23,24],benzer_cikmis:[]},{id:`k1-46-mesane-hastaliklari-ve-tumorleri-k11-q07`,kazanim:11,zorluk:`orta`,soru:`Tedavi edilmeyen gonorenin kadınlardaki geç komplikasyonları nelerdir?`,secenekler:{A:`Tedavisiz enfeksiyon kendiliğinden kısırlığı önler`,B:`PID yalnızca viral etkenlerle gelişir`,C:`Tubal hasar fertiliteyi artırır`,D:`Tedavisiz kalırsa PID, infertilite ve dış gebelik`,E:`Kültür tanıda hiçbir değer taşımaz`},dogru:`D`,aciklama:`Tedavisiz gonore kadında PID, infertilite ve ektopik gebeliğe yol açar. Asendan enfeksiyon tubal hasar ve adezyon oluşturur. Tanıda NAAT tercih edilir; kültür antibiyotik duyarlılığı için kullanılır.`,sik_aciklamalari:{A:`Yanlış: Tedavisizlik tubal hasarla kısırlığa yol açar.`,B:`Yanlış: Gonokok bakteriyel PID'nin başlıca nedenlerindendir.`,C:`Yanlış: Tubal skar fertiliteyi azaltır.`,D:`Doğru: Asendan yayılım PID ve tubal infertilite yapar.`,E:`Yanlış: Kültür direnç tayini için değerlidir.`},bilgi:[24,25],benzer_cikmis:[]},{id:`k1-46-mesane-hastaliklari-ve-tumorleri-k11-q08`,kazanim:11,zorluk:`kolay`,soru:`Aşağıdakilerden "Sifilisin patognomonik lezyonu" ile ilgili doğru olan seçeneği işaretleyiniz.`,secenekler:{D:`Tüm evrelerde proliferatif endarterit ve plazma hücre zengin infiltrat vardır.`,B:`Siklofosfamidin akrolein metaboliti ve adenovirus enfeksiyonları ile ilişkilidir.`,C:`Konjenital bozukluktur; bebek/çocukta hidronefrozun en sık nedenidir ve erkek çocuklarda daha sık görülür.`,A:`Erkekte üretrit (dizüri, sık idrara çıkma, mukopürülan akıntı), kadında çoğu zaman asemptomatik seyir; tedavi edilmezse PID, infertilite ve ektopik gebelik gelişir.`,E:`En sık etkenler E. coli (koliformlar), Proteus, Klebsiella ve Enterobacter türleridir.`},dogru:`D`,aciklama:`Doğru: Tüm evrelerde proliferatif endarterit ve plazma hücre zengin infiltrat vardır.`,sik_aciklamalari:{D:`Doğru. Tüm evrelerde proliferatif endarterit ve plazma hücre zengin infiltrat vardır.`,B:`Yanlış. Siklofosfamidin akrolein metaboliti ve adenovirus enfeksiyonları ile ilişkilidir.`,C:`Yanlış. Konjenital bozukluktur; bebek/çocukta hidronefrozun en sık nedenidir ve erkek çocuklarda daha sık görülür.`,A:`Yanlış. Erkekte üretrit (dizüri, sık idrara çıkma, mukopürülan akıntı), kadında çoğu zaman asemptomatik seyir; tedavi edilmezse PID, infertilite ve ektopik gebelik gelişir.`,E:`Yanlış. En sık etkenler E. coli (koliformlar), Proteus, Klebsiella ve Enterobacter türleridir.`},bilgi:[18],benzer_cikmis:[]},{id:`k1-46-mesane-hastaliklari-ve-tumorleri-k11-q09`,kazanim:11,zorluk:`orta`,soru:`"Hemorajik sistit" ile ilgili aşağıdakilerden hangisi yanlıştır?`,secenekler:{E:`Siklofosfamidin akrolein metaboliti ve adenovirus enfeksiyonları ile ilişkilidir.`,B:`Gebeliğin herhangi bir döneminde plasenta yoluyla bulaşır; intrauterin/perinatal ölüm ~%25 olabilir. Erken form hepatosplenomegali, snuffles, döküntü ve iskelet lezyonları; geç form Hutchinson triadı (interstisyel keratit, Hutchinson dişleri, sinir işitme kaybı).`,C:`IgG4 ilişkili hastalık, maligniteler (lenfoma, ürotelyal karsinom), radyasyon, cerrahi ve bazı ilaçlar (ergot türevleri, adrenerjik blokerler, TNF inhibitörleri) ile ilişkilidir.`,A:`Mesane duvarında mukozanın kese benzeri invajinasyonudur; konjenital (kas tabakasında fokal zayıflık) veya edinilmiş (distal obstrüksiyon: BPH, üretra darlığı) olabilir.`,D:`Böbrek pelvisi, üreter, mesane ve üretra ürotelyum (geçiş epiteli) ile kaplıdır; altında lamina propria ve muskularis propria (mesanede detrusor kası) vardır.`},dogru:`E`,aciklama:`Doğru: Siklofosfamidin akrolein metaboliti ve adenovirus enfeksiyonları ile ilişkilidir.`,sik_aciklamalari:{E:`Doğru. Siklofosfamidin akrolein metaboliti ve adenovirus enfeksiyonları ile ilişkilidir.`,B:`Yanlış. Gebeliğin herhangi bir döneminde plasenta yoluyla bulaşır; intrauterin/perinatal ölüm ~%25 olabilir. Erken form hepatosplenomegali, snuffles, döküntü ve iskelet lezyonları; geç form Hutchinson triadı (interstisyel keratit, Hutchinson dişleri, sinir işitme kaybı).`,C:`Yanlış. IgG4 ilişkili hastalık, maligniteler (lenfoma, ürotelyal karsinom), radyasyon, cerrahi ve bazı ilaçlar (ergot türevleri, adrenerjik blokerler, TNF inhibitörleri) ile ilişkilidir.`,A:`Yanlış. Mesane duvarında mukozanın kese benzeri invajinasyonudur; konjenital (kas tabakasında fokal zayıflık) veya edinilmiş (distal obstrüksiyon: BPH, üretra darlığı) olabilir.`,D:`Yanlış. Böbrek pelvisi, üreter, mesane ve üretra ürotelyum (geçiş epiteli) ile kaplıdır; altında lamina propria ve muskularis propria (mesanede detrusor kası) vardır.`},bilgi:[10],benzer_cikmis:[]},{id:`k1-46-mesane-hastaliklari-ve-tumorleri-k11-q10`,kazanim:11,zorluk:`orta`,soru:`"Alt idrar yolu yapısı" ile ilgili eşleştirmelerden hangisi doğrudur?`,secenekler:{A:`Böbrek pelvisi, üreter, mesane ve üretra ürotelyum (geçiş epiteli) ile kaplıdır; altında lamina propria ve muskularis propria (mesanede detrusor kası) vardır.`,B:`Primer dönemde genitalde spesifik olmayan üretrit, papül veya küçük ülser; sekonder dönemde şiş, hassas ve birleşip fistülize olabilen drenaj lenf düğümleri; uzun dönemde anogenital bölge ve rektumda fibrozis ve darlıklar.`,D:`HPV genital sistemde kondiloma akuminatum, prekanseröz skuamöz lezyonlar ve karsinomlar (serviks, penis, vulva, orofaringeal tonsil, konjonktiva) yapar. Kondiloma akuminatum etkeni düşük riskli HPV tip 6 ve 11'dir.`,E:`En sık bulgu ağrısız makroskopik veya mikroskopik hematüridir; tanıda sistoskopi + biyopsi ve idrar sitolojisi (özellikle yüksek dereceli ve CIS) kullanılır.`,C:`Etken HSV-1 ve HSV-2; genital olgular çoğunlukla HSV-2 ile oluşur ancak HSV-1 ile genital olgular artmaktadır. Bulaş enfekte mukoza/deri ile doğrudan temasla olur; virüs çevrede hızlı inaktive olur.`},dogru:`A`,aciklama:`Doğru: Böbrek pelvisi, üreter, mesane ve üretra ürotelyum (geçiş epiteli) ile kaplıdır; altında lamina propria ve muskularis propria (mesanede detrusor kası) vardır.`,sik_aciklamalari:{A:`Doğru. Böbrek pelvisi, üreter, mesane ve üretra ürotelyum (geçiş epiteli) ile kaplıdır; altında lamina propria ve muskularis propria (mesanede detrusor kası) vardır.`,B:`Yanlış. Primer dönemde genitalde spesifik olmayan üretrit, papül veya küçük ülser; sekonder dönemde şiş, hassas ve birleşip fistülize olabilen drenaj lenf düğümleri; uzun dönemde anogenital bölge ve rektumda fibrozis ve darlıklar.`,D:`Yanlış. HPV genital sistemde kondiloma akuminatum, prekanseröz skuamöz lezyonlar ve karsinomlar (serviks, penis, vulva, orofaringeal tonsil, konjonktiva) yapar. Kondiloma akuminatum etkeni düşük riskli HPV tip 6 ve 11'dir.`,E:`Yanlış. En sık bulgu ağrısız makroskopik veya mikroskopik hematüridir; tanıda sistoskopi + biyopsi ve idrar sitolojisi (özellikle yüksek dereceli ve CIS) kullanılır.`,C:`Yanlış. Etken HSV-1 ve HSV-2; genital olgular çoğunlukla HSV-2 ile oluşur ancak HSV-1 ile genital olgular artmaktadır. Bulaş enfekte mukoza/deri ile doğrudan temasla olur; virüs çevrede hızlı inaktive olur.`},bilgi:[1],benzer_cikmis:[]},{id:`k1-46-mesane-hastaliklari-ve-tumorleri-k11-q11`,kazanim:11,zorluk:`zor`,soru:`"Trichomoniasis" ile ilgili bir hastada bulunacak aşağıdaki bulgulardan hangisi beklenmez?`,secenekler:{B:`Etken Trichomonas vaginalis (kamçılı protozoon); genellikle cinsel temasla bulaşır. Kadında pruritus, bol köpüklü sarı-yeşil vajinal akıntı, üretral kolonizasyona bağlı dizüri; erkekte genelde hafif üretrit.`,E:`Erkekte üretrit (dizüri, sık idrara çıkma, mukopürülan akıntı), kadında çoğu zaman asemptomatik seyir; tedavi edilmezse PID, infertilite ve ektopik gebelik gelişir.`,D:`Düşük dereceli papiller yol FGFR3 ve HRAS ile; yüksek dereceli CIS-invaziv yol TP53 ve RB ile ilişkilidir.`,C:`Sekonder şankr iyileşmesinden ~2 ay sonra döküntü, mukokutanöz lezyonlar ve lenfadenopati ile; kondiloma lata anogenital bölgede geniş tabanlı kabarık lezyonlardır. Tersiyer yıllar sonra (5-20 yıl) kardiyovasküler sifilis, nörosifilis ve gumma ile seyreder.`,A:`C. trachomatis'in farklı (L1-L3) serovarlarına bağlı kronik, ülseratif CYBE; özellikle erkeklerle cinsel ilişkiye giren erkeklerde kasık lenfadenopatisi ve proktit görülür, HIV koinfeksiyonuyla güçlü ilişkilidir.`},dogru:`B`,aciklama:`Doğru: Etken Trichomonas vaginalis (kamçılı protozoon); genellikle cinsel temasla bulaşır. Kadında pruritus, bol köpüklü sarı-yeşil vajinal akıntı, üretral kolonizasyona bağlı dizüri; erkekte genelde hafif üretrit.`,sik_aciklamalari:{B:`Doğru. Etken Trichomonas vaginalis (kamçılı protozoon); genellikle cinsel temasla bulaşır. Kadında pruritus, bol köpüklü sarı-yeşil vajinal akıntı, üretral kolonizasyona bağlı dizüri; erkekte genelde hafif üretrit.`,E:`Yanlış. Erkekte üretrit (dizüri, sık idrara çıkma, mukopürülan akıntı), kadında çoğu zaman asemptomatik seyir; tedavi edilmezse PID, infertilite ve ektopik gebelik gelişir.`,D:`Yanlış. Düşük dereceli papiller yol FGFR3 ve HRAS ile; yüksek dereceli CIS-invaziv yol TP53 ve RB ile ilişkilidir.`,C:`Yanlış. Sekonder şankr iyileşmesinden ~2 ay sonra döküntü, mukokutanöz lezyonlar ve lenfadenopati ile; kondiloma lata anogenital bölgede geniş tabanlı kabarık lezyonlardır. Tersiyer yıllar sonra (5-20 yıl) kardiyovasküler sifilis, nörosifilis ve gumma ile seyreder.`,A:`Yanlış. C. trachomatis'in farklı (L1-L3) serovarlarına bağlı kronik, ülseratif CYBE; özellikle erkeklerle cinsel ilişkiye giren erkeklerde kasık lenfadenopatisi ve proktit görülür, HIV koinfeksiyonuyla güçlü ilişkilidir.`},bilgi:[33],benzer_cikmis:[]}],ilgili_cikmis:[]},{no:12,metin:`Gonokok dışı üretrit/servisit ve Chlamydia trachomatis enfeksiyonunu açıklayabilmek`,sorular:[{id:`k1-46-q35`,kazanim:12,zorluk:`kolay`,soru:`Gonokok dışı üretrit/servisitin en sık etkeni hangisidir?`,secenekler:{A:`Chlamydia trachomatis`,B:`Mycoplasma genitalium`,C:`Trichomonas vaginalis`,D:`Ureaplasma urealyticum`,E:`Neisseria gonorrhoeae`},dogru:`A`,aciklama:`NGU'nun en sık etkeni C. trachomatis'tir; olguların ~%50'sinde spesifik patojen bulunamaz.`,sik_aciklamalari:{A:`Doğru: klamidya NGU'nun en sık etkenidir.`,B:`M. genitalium NGU etkenidir ama daha seyrektir.`,C:`T. vaginalis NGU nedenleri arasındadır, en sık değildir.`,D:`U. urealyticum daha seyrek etkendir.`,E:`Gonokok tanım gereği NGU etkeni değildir.`},bilgi:[26],benzer_cikmis:[]},{id:`k1-46-q36`,kazanim:12,zorluk:`orta`,soru:`Chlamydia trachomatis ile ilgili aşağıdakilerden hangisi doğrudur?`,secenekler:{A:`Elementer cisim enfeksiyöz ve hücre dışı; retiküler cisim metabolik olarak aktif ve hücre içi formdur`,B:`Hücre dışında serbest yaşayan Gram pozitif koktur`,C:`Yassı epitele tropizm gösterir`,D:`Gram boyamada diplokok olarak görülür`,E:`Tanıda ıslak preparat altın standarttır`},dogru:`A`,aciklama:`Zorunlu hücre içi Gram negatif bakteri olan C. trachomatis elementer ve retiküler cisim formlarına sahiptir; kolumnar epitele tropizm gösterir.`,sik_aciklamalari:{A:`Doğru: iki formun özellikleri doğru tanımlanmıştır.`,B:`Zorunlu hücre içi Gram negatif bakteridir.`,C:`Kolumnar epitele tropizm gösterir.`,D:`Gram negatif diplokok gonokoktur.`,E:`Tanıda NAAT kullanılır; ıslak preparat trichomonas içindir.`},bilgi:[27,28],benzer_cikmis:[]},{id:`k1-46-q37`,kazanim:12,zorluk:`zor`,soru:`Klamidya enfeksiyonunun komplikasyonları ile ilgili aşağıdaki eşleştirmelerden hangisi yanlıştır?`,secenekler:{A:`Erkek – epididimit ve prostatit`,B:`Kadın – infertilite ve ektopik gebelik`,C:`Yenidoğan – konjonktivit ve pnömoni`,D:`Tanı – genital sürüntü veya idrarda NAAT`,E:`Kadın – tabanı sert, ağrısız tek genital ülser`},dogru:`E`,aciklama:`Tabanı sert ağrısız ülser primer sifilisin şankrıdır; klamidya üretrit/servisit ve üst genital yol komplikasyonları yapar.`,sik_aciklamalari:{A:`Doğru eşleştirme: erkekte epididimit ve prostatit görülür.`,B:`Doğru eşleştirme: tubal hasar infertilite ve ektopik gebelik yapar.`,C:`Doğru eşleştirme: vajinal doğumda bulaşır.`,D:`Doğru eşleştirme: NAAT tercih edilen tanı yöntemidir.`,E:`Yanlış eşleştirme (aranan cevap): bu lezyon sifilise aittir.`},bilgi:[19,28],benzer_cikmis:[]},{id:`k1-46-mesane-hastaliklari-ve-tumorleri-k12-q04`,kazanim:12,zorluk:`orta`,soru:`Üretritli hastada gonokok saptanmıyor; NGU etkenleri araştırılıyor. Aşağıdakilerden hangisi doğrudur?`,secenekler:{A:`NGU en sık CYBE grubudur; en sık etken C. trachomatis'tir; olguların ~%50'sinde patojen saptanamaz`,B:`NGU nadirdir`,C:`En sık etken T. pallidum'dur`,D:`Klamidya hücre dışı yaşar`,E:`Klamidya yalnızca deriyi tutar`},dogru:`A`,aciklama:`NGU'da C. trachomatis başattır; yarısında etken bulunamaz.`,sik_aciklamalari:{A:`Doğru: NGU'da C. trachomatis başattır; yarısında etken bulunamaz.`,B:`Yanlış: bu seçenek vakadaki tabloyla uyumlu değildir; doğru yanıt 'NGU en sık CYBE grubudur; en sık etken C. trachomatis'tir; olguların ~%50'sinde patojen saptanamaz' seçeneğidir.`,C:`Yanlış: bu seçenek vakadaki tabloyla uyumlu değildir; doğru yanıt 'NGU en sık CYBE grubudur; en sık etken C. trachomatis'tir; olguların ~%50'sinde patojen saptanamaz' seçeneğidir.`,D:`Yanlış: bu seçenek vakadaki tabloyla uyumlu değildir; doğru yanıt 'NGU en sık CYBE grubudur; en sık etken C. trachomatis'tir; olguların ~%50'sinde patojen saptanamaz' seçeneğidir.`,E:`Yanlış: bu seçenek vakadaki tabloyla uyumlu değildir; doğru yanıt 'NGU en sık CYBE grubudur; en sık etken C. trachomatis'tir; olguların ~%50'sinde patojen saptanamaz' seçeneğidir.`},bilgi:[26,27],benzer_cikmis:[]},{id:`k1-46-mesane-hastaliklari-ve-tumorleri-k12-q05`,kazanim:12,zorluk:`zor`,soru:`Elementer/retiküler cisim ve komplikasyonlar (epididimit, infertilite, neonatal pnömoni) soruluyor. Aşağıdakilerden hangisi yanlıştır?`,secenekler:{A:`Kolumnar epitel tropizmi vardır; çoğu olgu asemptomatiktir`,B:`Erkekte epididimit/prostatit, kadında infertilite/ektopik gebelik yapar`,C:`Tanı genital sürüntü/idrarda NAAT ile konur`,D:`Elementer cisim enfeksiyöz-ekstraselüler, retiküler cisim metabolik aktif-hücre içidir`,E:`Klamidya Gram pozitif koktur ve tanısı yalnızca kültüre dayanır; asemptomatik taşıyıcılık olmaz`},dogru:`D`,aciklama:`Klamidya zorunlu hücre içi Gram negatif bakteridir; tanı NAAT'iledir.`,sik_aciklamalari:{A:`Yanlış: bu seçenek vakadaki tabloyla uyumlu değildir; doğru yanıt 'Elementer cisim enfeksiyöz-ekstraselüler, retiküler cisim metabolik aktif-hücre içidir' seçeneğidir.`,B:`Yanlış: bu seçenek vakadaki tabloyla uyumlu değildir; doğru yanıt 'Elementer cisim enfeksiyöz-ekstraselüler, retiküler cisim metabolik aktif-hücre içidir' seçeneğidir.`,C:`Yanlış: bu seçenek vakadaki tabloyla uyumlu değildir; doğru yanıt 'Elementer cisim enfeksiyöz-ekstraselüler, retiküler cisim metabolik aktif-hücre içidir' seçeneğidir.`,D:`Doğru: Klamidya zorunlu hücre içi Gram negatif bakteridir; tanı NAAT'iledir.`,E:`Yanlış: bu seçenek vakadaki tabloyla uyumlu değildir; doğru yanıt 'Elementer cisim enfeksiyöz-ekstraselüler, retiküler cisim metabolik aktif-hücre içidir' seçeneğidir.`},bilgi:[26,27,28],benzer_cikmis:[]},{id:`k1-46-mesane-hastaliklari-ve-tumorleri-k12-q06`,kazanim:12,zorluk:`orta`,soru:`Chlamydia trachomatis'in mikrobiyolojik özellikleri nelerdir?`,secenekler:{A:`Zorunlu hücre içi; elementer ve retiküler cisimli`,B:`Serbest yaşayan Gram pozitif kok`,C:`Kamçılı ekstraselüler protozoon`,D:`Misel oluşturan küf mantarı`,E:`Zarfsız RNA virusu`},dogru:`A`,aciklama:`Chlamydia trachomatis zorunlu hücre içi Gram negatif bakteridir; enfeksiyöz elementer ve metabolik retiküler cisim formları vardır. Kolumnar epitel tropizmi gösterir. Hücre içi yaşamı kültür dışı tanı yöntemlerini gerektirir.`,sik_aciklamalari:{A:`Doğru: İki formlu hücre içi yaşam döngüsü tipiktir.`,B:`Yanlış: Klamidya hücre dışında üreyemez.`,C:`Yanlış: Kamçılı protozoon trikomonastır.`,D:`Yanlış: Mantar morfolojisi klamidyada yoktur.`,E:`Yanlış: Klamidya bakteridir, virus değildir.`},bilgi:[27],benzer_cikmis:[]},{id:`k1-46-mesane-hastaliklari-ve-tumorleri-k12-q07`,kazanim:12,zorluk:`orta`,soru:`Klamidya enfeksiyonunun genital ve neonatal komplikasyonları nelerdir?`,secenekler:{A:`Yalnızca deri döküntüsüyle sınırlıdır`,B:`Komplikasyon yapmadan hep kendini sınırlar`,C:`Epididimit, infertilite ve neonatal pnömoni yapar`,D:`Yalnızca menenjite yol açar`,E:`Kardiyovasküler tutulum başlıca sonuçtur`},dogru:`C`,aciklama:`Klamidya erkekte epididimit ve prostatit, kadında infertilite ve ektopik gebelik yapar; yenidoğanda vajinal doğumda konjonktivit ve pnömoni gelişir. Asendan yayılım tubal skara yol açar. Bu komplikasyonlar tarama ve eş tedavisini zorunlu kılar.`,sik_aciklamalari:{A:`Yanlış: Genital ve neonatal komplikasyonları belirgindir.`,B:`Yanlış: Tedavisiz asendan yayılım ve skar gelişir.`,C:`Doğru: Genital kanal ve neonatal tutulum tipiktir.`,D:`Yanlış: Menenjit klamidya komplikasyonu değildir.`,E:`Yanlış: Kardiyovasküler tutulum sifilize aittir.`},bilgi:[28],benzer_cikmis:[]},{id:`k1-46-mesane-hastaliklari-ve-tumorleri-k12-q08`,kazanim:12,zorluk:`kolay`,soru:`"Lenfogranüloma venereum (LGV)" ifadesi ile ilgili aşağıdakilerden hangisi doğrudur?`,secenekler:{B:`C. trachomatis'in farklı (L1-L3) serovarlarına bağlı kronik, ülseratif CYBE; özellikle erkeklerle cinsel ilişkiye giren erkeklerde kasık lenfadenopatisi ve proktit görülür, HIV koinfeksiyonuyla güçlü ilişkilidir.`,A:`Erkekte epididimit ve prostatit; kadında infertilite ve ektopik gebelik; yenidoğanda konjonktivit ve pnömoni (vajinal doğumda bulaş).`,E:`Düşük dereceli papiller yol FGFR3 ve HRAS ile; yüksek dereceli CIS-invaziv yol TP53 ve RB ile ilişkilidir.`,D:`HPV genital sistemde kondiloma akuminatum, prekanseröz skuamöz lezyonlar ve karsinomlar (serviks, penis, vulva, orofaringeal tonsil, konjonktiva) yapar. Kondiloma akuminatum etkeni düşük riskli HPV tip 6 ve 11'dir.`,C:`Retroperitoneal yapıları saran fibroinflamatuar doku tablosudur; üreter daralması veya tıkanıklığına yol açabilir; orta-ileri yaşta ve erkeklerde daha sık görülür.`},dogru:`B`,aciklama:`Doğru: C. trachomatis'in farklı (L1-L3) serovarlarına bağlı kronik, ülseratif CYBE; özellikle erkeklerle cinsel ilişkiye giren erkeklerde kasık lenfadenopatisi ve proktit görülür, HIV koinfeksiyonuyla güçlü ilişkilidir.`,sik_aciklamalari:{B:`Doğru. C. trachomatis'in farklı (L1-L3) serovarlarına bağlı kronik, ülseratif CYBE; özellikle erkeklerle cinsel ilişkiye giren erkeklerde kasık lenfadenopatisi ve proktit görülür, HIV koinfeksiyonuyla güçlü ilişkilidir.`,A:`Yanlış. Erkekte epididimit ve prostatit; kadında infertilite ve ektopik gebelik; yenidoğanda konjonktivit ve pnömoni (vajinal doğumda bulaş).`,E:`Yanlış. Düşük dereceli papiller yol FGFR3 ve HRAS ile; yüksek dereceli CIS-invaziv yol TP53 ve RB ile ilişkilidir.`,D:`Yanlış. HPV genital sistemde kondiloma akuminatum, prekanseröz skuamöz lezyonlar ve karsinomlar (serviks, penis, vulva, orofaringeal tonsil, konjonktiva) yapar. Kondiloma akuminatum etkeni düşük riskli HPV tip 6 ve 11'dir.`,C:`Yanlış. Retroperitoneal yapıları saran fibroinflamatuar doku tablosudur; üreter daralması veya tıkanıklığına yol açabilir; orta-ileri yaşta ve erkeklerde daha sık görülür.`},bilgi:[29],benzer_cikmis:[]},{id:`k1-46-mesane-hastaliklari-ve-tumorleri-k12-q09`,kazanim:12,zorluk:`orta`,soru:`"Üreteropelvik bileşke (UPJ) tıkanıklığı" ile ilgili aşağıdakilerden hangisi yanlıştır?`,secenekler:{D:`Konjenital bozukluktur; bebek/çocukta hidronefrozun en sık nedenidir ve erkek çocuklarda daha sık görülür.`,A:`Etken Haemophilus ducreyi (Gram negatif kokobasil); 4-7 gün inkübasyondan sonra dış genitalde papül hızla ağrılı ülsere dönüşür, çoklu ülserler sıktır ve sert indürasyon yoktur.`,E:`Düşük dereceli papiller yol FGFR3 ve HRAS ile; yüksek dereceli CIS-invaziv yol TP53 ve RB ile ilişkilidir.`,B:`Divertikül içindeki idrar stazı tekrarlayan idrar yolu enfeksiyonu, taş oluşumu ve nadiren tümör gelişimine yol açar.`,C:`Etken Trichomonas vaginalis (kamçılı protozoon); genellikle cinsel temasla bulaşır. Kadında pruritus, bol köpüklü sarı-yeşil vajinal akıntı, üretral kolonizasyona bağlı dizüri; erkekte genelde hafif üretrit.`},dogru:`D`,aciklama:`Doğru: Konjenital bozukluktur; bebek/çocukta hidronefrozun en sık nedenidir ve erkek çocuklarda daha sık görülür.`,sik_aciklamalari:{D:`Doğru. Konjenital bozukluktur; bebek/çocukta hidronefrozun en sık nedenidir ve erkek çocuklarda daha sık görülür.`,A:`Yanlış. Etken Haemophilus ducreyi (Gram negatif kokobasil); 4-7 gün inkübasyondan sonra dış genitalde papül hızla ağrılı ülsere dönüşür, çoklu ülserler sıktır ve sert indürasyon yoktur.`,E:`Yanlış. Düşük dereceli papiller yol FGFR3 ve HRAS ile; yüksek dereceli CIS-invaziv yol TP53 ve RB ile ilişkilidir.`,B:`Yanlış. Divertikül içindeki idrar stazı tekrarlayan idrar yolu enfeksiyonu, taş oluşumu ve nadiren tümör gelişimine yol açar.`,C:`Yanlış. Etken Trichomonas vaginalis (kamçılı protozoon); genellikle cinsel temasla bulaşır. Kadında pruritus, bol köpüklü sarı-yeşil vajinal akıntı, üretral kolonizasyona bağlı dizüri; erkekte genelde hafif üretrit.`},bilgi:[3],benzer_cikmis:[]},{id:`k1-46-mesane-hastaliklari-ve-tumorleri-k12-q10`,kazanim:12,zorluk:`orta`,soru:`"LGV morfoloji ve sonuçları" ile ilgili aşağıdakilerden hangisi yanlıştır?`,secenekler:{D:`Primer dönemde genitalde spesifik olmayan üretrit, papül veya küçük ülser; sekonder dönemde şiş, hassas ve birleşip fistülize olabilen drenaj lenf düğümleri; uzun dönemde anogenital bölge ve rektumda fibrozis ve darlıklar.`,C:`Konjenital bozukluktur; bebek/çocukta hidronefrozun en sık nedenidir ve erkek çocuklarda daha sık görülür.`,B:`Tüm evrelerde proliferatif endarterit ve plazma hücre zengin infiltrat vardır.`,A:`Mesane duvarında mukozanın kese benzeri invajinasyonudur; konjenital (kas tabakasında fokal zayıflık) veya edinilmiş (distal obstrüksiyon: BPH, üretra darlığı) olabilir.`,E:`Kronik pelvik ağrı ve Hunner ülseri ile seyreder; kültür negatiftir ve daha çok kadınlarda görülür.`},dogru:`D`,aciklama:`Doğru: Primer dönemde genitalde spesifik olmayan üretrit, papül veya küçük ülser; sekonder dönemde şiş, hassas ve birleşip fistülize olabilen drenaj lenf düğümleri; uzun dönemde anogenital bölge ve rektumda fibrozis ve darlıklar.`,sik_aciklamalari:{D:`Doğru. Primer dönemde genitalde spesifik olmayan üretrit, papül veya küçük ülser; sekonder dönemde şiş, hassas ve birleşip fistülize olabilen drenaj lenf düğümleri; uzun dönemde anogenital bölge ve rektumda fibrozis ve darlıklar.`,C:`Yanlış. Konjenital bozukluktur; bebek/çocukta hidronefrozun en sık nedenidir ve erkek çocuklarda daha sık görülür.`,B:`Yanlış. Tüm evrelerde proliferatif endarterit ve plazma hücre zengin infiltrat vardır.`,A:`Yanlış. Mesane duvarında mukozanın kese benzeri invajinasyonudur; konjenital (kas tabakasında fokal zayıflık) veya edinilmiş (distal obstrüksiyon: BPH, üretra darlığı) olabilir.`,E:`Yanlış. Kronik pelvik ağrı ve Hunner ülseri ile seyreder; kültür negatiftir ve daha çok kadınlarda görülür.`},bilgi:[30],benzer_cikmis:[]},{id:`k1-46-mesane-hastaliklari-ve-tumorleri-k12-q11`,kazanim:12,zorluk:`zor`,soru:`"Üreter bozuklukları sınıflaması" ile ilgili bir hastada bulunacak aşağıdaki bulgulardan hangisi beklenmez?`,secenekler:{D:`Nadir fakat önemli üç grup: konjenital darlık (UPJ tıkanıklığı), neoplazmlar (genellikle ürotelyal karsinom) ve reaktif süreçler (retroperitoneal fibrozis).`,B:`C. trachomatis'in farklı (L1-L3) serovarlarına bağlı kronik, ülseratif CYBE; özellikle erkeklerle cinsel ilişkiye giren erkeklerde kasık lenfadenopatisi ve proktit görülür, HIV koinfeksiyonuyla güçlü ilişkilidir.`,C:`Sekonder şankr iyileşmesinden ~2 ay sonra döküntü, mukokutanöz lezyonlar ve lenfadenopati ile; kondiloma lata anogenital bölgede geniş tabanlı kabarık lezyonlardır. Tersiyer yıllar sonra (5-20 yıl) kardiyovasküler sifilis, nörosifilis ve gumma ile seyreder.`,A:`Siklofosfamidin akrolein metaboliti ve adenovirus enfeksiyonları ile ilişkilidir.`,E:`Vajinal kazıntıdan ıslak preparatta hareketli organizmanın gösterilmesiyle konur; genellikle eşzamanlı klamidya ve gonore testleri yapılır.`},dogru:`D`,aciklama:`Doğru: Nadir fakat önemli üç grup: konjenital darlık (UPJ tıkanıklığı), neoplazmlar (genellikle ürotelyal karsinom) ve reaktif süreçler (retroperitoneal fibrozis).`,sik_aciklamalari:{D:`Doğru. Nadir fakat önemli üç grup: konjenital darlık (UPJ tıkanıklığı), neoplazmlar (genellikle ürotelyal karsinom) ve reaktif süreçler (retroperitoneal fibrozis).`,B:`Yanlış. C. trachomatis'in farklı (L1-L3) serovarlarına bağlı kronik, ülseratif CYBE; özellikle erkeklerle cinsel ilişkiye giren erkeklerde kasık lenfadenopatisi ve proktit görülür, HIV koinfeksiyonuyla güçlü ilişkilidir.`,C:`Yanlış. Sekonder şankr iyileşmesinden ~2 ay sonra döküntü, mukokutanöz lezyonlar ve lenfadenopati ile; kondiloma lata anogenital bölgede geniş tabanlı kabarık lezyonlardır. Tersiyer yıllar sonra (5-20 yıl) kardiyovasküler sifilis, nörosifilis ve gumma ile seyreder.`,A:`Yanlış. Siklofosfamidin akrolein metaboliti ve adenovirus enfeksiyonları ile ilişkilidir.`,E:`Yanlış. Vajinal kazıntıdan ıslak preparatta hareketli organizmanın gösterilmesiyle konur; genellikle eşzamanlı klamidya ve gonore testleri yapılır.`},bilgi:[2],benzer_cikmis:[]}],ilgili_cikmis:[]},{no:13,metin:`Lenfogranüloma venereum ve şankroidi tanımlayabilmek`,sorular:[{id:`k1-46-q38`,kazanim:13,zorluk:`kolay`,soru:`Şankroidin (yumuşak şankr) etkeni hangisidir?`,secenekler:{A:`Haemophilus ducreyi`,B:`Treponema pallidum`,C:`Chlamydia trachomatis L1-L3`,D:`Herpes simpleks virüs 2`,E:`Neisseria gonorrhoeae`},dogru:`A`,aciklama:`Şankroid etkeni Gram negatif kokobasil olan Haemophilus ducreyi'dir.`,sik_aciklamalari:{A:`Doğru: H. ducreyi ağrılı yumuşak ülser yapar.`,B:`T. pallidum sert şankr (sifilis) yapar.`,C:`L1–L3 serovarları lenfogranüloma venereum etkenidir.`,D:`HSV-2 ağrılı vezikül ve ülser yapar.`,E:`Gonokok üretrit/servisit yapar.`},bilgi:[31],benzer_cikmis:[]},{id:`k1-46-q39`,kazanim:13,zorluk:`orta`,soru:`Şankroidi sifilitik şankrdan ayırmada en önemli klinik özellik hangisidir?`,secenekler:{A:`Şankroid ülserlerinin ağrılı, çoklu ve sert indürasyonsuz olması`,B:`Şankroid ülserlerinin ağrısız ve tabanı sert olması`,C:`Şankroidde ülser hiç oluşmaması`,D:`Şankroidin yalnızca kadınlarda görülmesi`,E:`Şankroidin inkübasyonunun 5–20 yıl olması`},dogru:`A`,aciklama:`Şankroidde 4–7 gün inkübasyon sonrası papül hızla ağrılı, çoklu ve indürasyonsuz ülsere dönüşür.`,sik_aciklamalari:{A:`Doğru: sert indürasyon yokluğu sifilisten ayrımda anahtardır.`,B:`Ağrısız ve sert taban sifilitik şankrın özelliğidir.`,C:`Şankroidin temel lezyonu ülserdir.`,D:`Her iki cinsiyette görülür.`,E:`İnkübasyon 4–7 gündür; 5–20 yıl tersiyer sifilis süresidir.`},bilgi:[19,31],benzer_cikmis:[]},{id:`k1-46-q40`,kazanim:13,zorluk:`zor`,soru:`HIV pozitif, erkeklerle cinsel ilişkiye giren bir erkekte proktit ve fistülize olmuş hassas kasık lenfadenopatisi gelişiyor. Lenf nodu biyopsisinde yıldızsı apseler içeren nekrotizan granülomlar görülüyor.

En olası tanı ve uzun dönem sekeli hangisidir?`,secenekler:{A:`Lenfogranüloma venereum; anogenital bölge ve rektumda fibrotik darlıklar`,B:`Şankroid; kondiloma lata`,C:`Sekonder sifilis; gumma`,D:`Genital herpes; Hutchinson dişleri`,E:`Gonore; tiroidizasyon`},dogru:`A`,aciklama:`C. trachomatis L1–L3'e bağlı LGV proktit, fistülize lenfadenopati ve yıldızsı apseler yapar; uzun dönemde rektal darlık gelişir.`,sik_aciklamalari:{A:`Doğru: LGV'nin kliniği, histolojisi ve sekeli uyumludur.`,B:`Şankroid ağrılı ülser yapar; kondiloma lata sekonder sifilis lezyonudur.`,C:`Sifiliste plazma hücreli endarterit beklenir, yıldızsı apse değil.`,D:`Hutchinson dişleri konjenital sifilise aittir.`,E:`Tiroidizasyon kronik piyelonefrit bulgusudur.`},bilgi:[29,30],benzer_cikmis:[]},{id:`k1-46-mesane-hastaliklari-ve-tumorleri-k13-q04`,kazanim:13,zorluk:`orta`,soru:`Kasıkta birleşip fistülize olan ağrılı lenf düğümleri ve genital ülserli hasta değerlendiriliyor. Aşağıdakilerden hangisi doğrudur?`,secenekler:{A:`LGV viraldir`,B:`Şankroidde sert indürasyon tipiktir`,C:`LGV C. trachomatis L1-L3 serovarlarına bağlıdır; histolojide yıldızsı apseler görülür; şankroidde H. ducreyi ağrılı yumuşak şankr yapar (sert indürasyon yok)`,D:`Yıldızsı apseler sifilizde görülür`,E:`LGV'de lenfadenopati olmaz`},dogru:`C`,aciklama:`LGV kronik ülseratif CYBE'dir; şankroid ağrılı yumuşak şankrdır.`,sik_aciklamalari:{A:`Yanlış: bu seçenek vakadaki tabloyla uyumlu değildir; doğru yanıt 'LGV C. trachomatis L1-L3 serovarlarına bağlıdır; histolojide yıldızsı apseler görülür; şankroidde H. ducreyi ağrılı yumuşak şankr yapar (sert indürasyon yok)' seçeneğidir.`,B:`Yanlış: bu seçenek vakadaki tabloyla uyumlu değildir; doğru yanıt 'LGV C. trachomatis L1-L3 serovarlarına bağlıdır; histolojide yıldızsı apseler görülür; şankroidde H. ducreyi ağrılı yumuşak şankr yapar (sert indürasyon yok)' seçeneğidir.`,C:`Doğru: LGV kronik ülseratif CYBE'dir; şankroid ağrılı yumuşak şankrdır.`,D:`Yanlış: bu seçenek vakadaki tabloyla uyumlu değildir; doğru yanıt 'LGV C. trachomatis L1-L3 serovarlarına bağlıdır; histolojide yıldızsı apseler görülür; şankroidde H. ducreyi ağrılı yumuşak şankr yapar (sert indürasyon yok)' seçeneğidir.`,E:`Yanlış: bu seçenek vakadaki tabloyla uyumlu değildir; doğru yanıt 'LGV C. trachomatis L1-L3 serovarlarına bağlıdır; histolojide yıldızsı apseler görülür; şankroidde H. ducreyi ağrılı yumuşak şankr yapar (sert indürasyon yok)' seçeneğidir.`},bilgi:[29,30,31,32],benzer_cikmis:[]},{id:`k1-46-mesane-hastaliklari-ve-tumorleri-k13-q05`,kazanim:13,zorluk:`zor`,soru:`LGV seyri (primer ülser, sekonder bubo, tersiyer fibrozis) ile şankroid histolojisi karşılaştırılıyor. Aşağıdakilerden hangisi yanlıştır?`,secenekler:{A:`Uzun dönemde anogenital fibrozis ve darlıklar gelişir`,B:`LGV'de sekonder dönemde şiş-hassas birleşen drenajlı lenf düğümleri olur`,C:`Şankroid histolojisinde nötrofil-fibrinli ülser ve lenfoplazmasitik infiltrat vardır`,D:`LGV yalnızca üst solunumu tutar ve asla lenfadenopati yapmaz; şankroid ağrısız serttir`,E:`Tanıda NAAT yüksek duyarlılık-özgüllüğe sahiptir`},dogru:`B`,aciklama:`LGV lenfadenopati ve proktit yapar; şankroid ağrılı yumuşaktır.`,sik_aciklamalari:{A:`Yanlış: bu seçenek vakadaki tabloyla uyumlu değildir; doğru yanıt 'LGV'de sekonder dönemde şiş-hassas birleşen drenajlı lenf düğümleri olur' seçeneğidir.`,B:`Doğru: LGV lenfadenopati ve proktit yapar; şankroid ağrılı yumuşaktır.`,C:`Yanlış: bu seçenek vakadaki tabloyla uyumlu değildir; doğru yanıt 'LGV'de sekonder dönemde şiş-hassas birleşen drenajlı lenf düğümleri olur' seçeneğidir.`,D:`Yanlış: bu seçenek vakadaki tabloyla uyumlu değildir; doğru yanıt 'LGV'de sekonder dönemde şiş-hassas birleşen drenajlı lenf düğümleri olur' seçeneğidir.`,E:`Yanlış: bu seçenek vakadaki tabloyla uyumlu değildir; doğru yanıt 'LGV'de sekonder dönemde şiş-hassas birleşen drenajlı lenf düğümleri olur' seçeneğidir.`},bilgi:[29,30,31,32],benzer_cikmis:[]},{id:`k1-46-mesane-hastaliklari-ve-tumorleri-k13-q06`,kazanim:13,zorluk:`orta`,soru:`Lenfogranüloma venereumun etkeni ve tipik lenf nodu tablosu nedir?`,secenekler:{A:`Spiroketin yaptığı ağrısız sert ülserdir`,B:`Virusun yaptığı veziküler döküntüdür`,C:`Protozoonun yaptığı köpüklü akıntıdır`,D:`Diplokokun yaptığı pürülan üretritir`,E:`L1-L3 klamidyanın yaptığı fistülizan lenfadenopatidir`},dogru:`E`,aciklama:`LGV, C. trachomatis'in L1-L3 serovarlarına bağlı kronik ülseratif CYBE'dir. Sekonder dönemde şiş, hassas, birleşip fistülize olabilen drenajlı lenf düğümleri görülür. Uzun dönemde fibrozis ve darlık gelişir.`,sik_aciklamalari:{A:`Yanlış: Sert şankr sifilize aittir.`,B:`Yanlış: Veziküler tablo herpese aittir.`,C:`Yanlış: Köpüklü akıntı trikomoniyaza aittir.`,D:`Yanlış: Pürülan üretrit gonoreye aittir.`,E:`Doğru: LGV invaziv serovarlarla lenfatik yayılım yapar.`},bilgi:[29,30],benzer_cikmis:[]},{id:`k1-46-mesane-hastaliklari-ve-tumorleri-k13-q07`,kazanim:13,zorluk:`orta`,soru:`Şankroid ülserinin sifilis şankrından ayıran özellikleri nelerdir?`,secenekler:{A:`Ağrısız tek sert şankr yapar`,B:`Ağrılı çoklu yumuşak ülser yapar`,C:`Vezikül ve dev hücre oluşturur`,D:`Papiller siğil ve koilositoz yapar`,E:`Geniş tabanlı kondiloma lata yapar`},dogru:`B`,aciklama:`Şankroid etkeni Haemophilus ducreyi adlı Gram negatif kokobasildir. 4-7 günlük inkübasyondan sonra ağrılı, çoklu, sert indürasyonsuz ülserler gelişir. Histolojide nötrofil-fibrin kaplı ülser ve nekrotizan lenfadenit görülür.`,sik_aciklamalari:{A:`Yanlış: Sert şankr sifilizin lezyonudur.`,B:`Doğru: Yumuşak şankr ağrılı, çoklu ve indürasyonsuzdur.`,C:`Yanlış: Bu bulgular herpese aittir.`,D:`Yanlış: Bu bulgular HPV enfeksiyonuna aittir.`,E:`Yanlış: Kondiloma lata sekonder sifilize aittir.`},bilgi:[31,32],benzer_cikmis:[]},{id:`k1-46-mesane-hastaliklari-ve-tumorleri-k13-q08`,kazanim:13,zorluk:`kolay`,soru:`Aşağıdakilerden "Sifilis etken ve bulaş" ile ilgili doğru olan seçeneği işaretleyiniz.`,secenekler:{B:`Etken Treponema pallidum (spiroket); bulaş erken evre deri/mukoza lezyonlarıyla temasla ve konjenital olarak plasenta yoluyla olur.`,A:`Zorunlu hücre içi Gram negatif bakteri; elementer cisim (enfeksiyöz, ekstraselüler) ve retiküler cisim (metabolik aktif, hücre içi) formları vardır; kolumnar epitel tropizmi gösterir.`,C:`Dört veya dokuz değerliklidir; düşük riskli tip 6 ve 11'e karşı koruma sağlar, anogenital siğilleri önler ve HPV ilişkili karsinom insidansını (özellikle serviks) azaltır.`,D:`Primer dönemde genitalde spesifik olmayan üretrit, papül veya küçük ülser; sekonder dönemde şiş, hassas ve birleşip fistülize olabilen drenaj lenf düğümleri; uzun dönemde anogenital bölge ve rektumda fibrozis ve darlıklar.`,E:`HPV genital sistemde kondiloma akuminatum, prekanseröz skuamöz lezyonlar ve karsinomlar (serviks, penis, vulva, orofaringeal tonsil, konjonktiva) yapar. Kondiloma akuminatum etkeni düşük riskli HPV tip 6 ve 11'dir.`},dogru:`B`,aciklama:`Doğru: Etken Treponema pallidum (spiroket); bulaş erken evre deri/mukoza lezyonlarıyla temasla ve konjenital olarak plasenta yoluyla olur.`,sik_aciklamalari:{B:`Doğru. Etken Treponema pallidum (spiroket); bulaş erken evre deri/mukoza lezyonlarıyla temasla ve konjenital olarak plasenta yoluyla olur.`,A:`Yanlış. Zorunlu hücre içi Gram negatif bakteri; elementer cisim (enfeksiyöz, ekstraselüler) ve retiküler cisim (metabolik aktif, hücre içi) formları vardır; kolumnar epitel tropizmi gösterir.`,C:`Yanlış. Dört veya dokuz değerliklidir; düşük riskli tip 6 ve 11'e karşı koruma sağlar, anogenital siğilleri önler ve HPV ilişkili karsinom insidansını (özellikle serviks) azaltır.`,D:`Yanlış. Primer dönemde genitalde spesifik olmayan üretrit, papül veya küçük ülser; sekonder dönemde şiş, hassas ve birleşip fistülize olabilen drenaj lenf düğümleri; uzun dönemde anogenital bölge ve rektumda fibrozis ve darlıklar.`,E:`Yanlış. HPV genital sistemde kondiloma akuminatum, prekanseröz skuamöz lezyonlar ve karsinomlar (serviks, penis, vulva, orofaringeal tonsil, konjonktiva) yapar. Kondiloma akuminatum etkeni düşük riskli HPV tip 6 ve 11'dir.`},bilgi:[17],benzer_cikmis:[]},{id:`k1-46-mesane-hastaliklari-ve-tumorleri-k13-q09`,kazanim:13,zorluk:`orta`,soru:`"Ürotelyal karsinom temel noktaları" ile ilgili aşağıdakilerden hangisi yanlıştır?`,secenekler:{B:`Mesane kanserlerinin ~%90'ı ürotelyal karsinomdur; majör risk faktörleri sigara, aromatik aminler (boya, kauçuk, tekstil), siklofosfamid ve pelvik radyoterapidir.`,C:`Nadir fakat önemli üç grup: konjenital darlık (UPJ tıkanıklığı), neoplazmlar (genellikle ürotelyal karsinom) ve reaktif süreçler (retroperitoneal fibrozis).`,D:`Divertikül içindeki idrar stazı tekrarlayan idrar yolu enfeksiyonu, taş oluşumu ve nadiren tümör gelişimine yol açar.`,E:`Tüm evrelerde proliferatif endarterit ve plazma hücre zengin infiltrat vardır.`,A:`Retroperitoneal yapıları saran fibroinflamatuar doku tablosudur; üreter daralması veya tıkanıklığına yol açabilir; orta-ileri yaşta ve erkeklerde daha sık görülür.`},dogru:`B`,aciklama:`Doğru: Mesane kanserlerinin ~%90'ı ürotelyal karsinomdur; majör risk faktörleri sigara, aromatik aminler (boya, kauçuk, tekstil), siklofosfamid ve pelvik radyoterapidir.`,sik_aciklamalari:{B:`Doğru. Mesane kanserlerinin ~%90'ı ürotelyal karsinomdur; majör risk faktörleri sigara, aromatik aminler (boya, kauçuk, tekstil), siklofosfamid ve pelvik radyoterapidir.`,C:`Yanlış. Nadir fakat önemli üç grup: konjenital darlık (UPJ tıkanıklığı), neoplazmlar (genellikle ürotelyal karsinom) ve reaktif süreçler (retroperitoneal fibrozis).`,D:`Yanlış. Divertikül içindeki idrar stazı tekrarlayan idrar yolu enfeksiyonu, taş oluşumu ve nadiren tümör gelişimine yol açar.`,E:`Yanlış. Tüm evrelerde proliferatif endarterit ve plazma hücre zengin infiltrat vardır.`,A:`Yanlış. Retroperitoneal yapıları saran fibroinflamatuar doku tablosudur; üreter daralması veya tıkanıklığına yol açabilir; orta-ileri yaşta ve erkeklerde daha sık görülür.`},bilgi:[14],benzer_cikmis:[]},{id:`k1-46-mesane-hastaliklari-ve-tumorleri-k13-q10`,kazanim:13,zorluk:`orta`,soru:`"Retroperitoneal fibrozis" ile ilgili aşağıdakilerden hangisi yanlıştır?`,secenekler:{A:`Retroperitoneal yapıları saran fibroinflamatuar doku tablosudur; üreter daralması veya tıkanıklığına yol açabilir; orta-ileri yaşta ve erkeklerde daha sık görülür.`,E:`Mesane duvarında mukozanın kese benzeri invajinasyonudur; konjenital (kas tabakasında fokal zayıflık) veya edinilmiş (distal obstrüksiyon: BPH, üretra darlığı) olabilir.`,B:`Tüm evrelerde proliferatif endarterit ve plazma hücre zengin infiltrat vardır.`,C:`Nadir fakat önemli üç grup: konjenital darlık (UPJ tıkanıklığı), neoplazmlar (genellikle ürotelyal karsinom) ve reaktif süreçler (retroperitoneal fibrozis).`,D:`En sık etkenler E. coli (koliformlar), Proteus, Klebsiella ve Enterobacter türleridir.`},dogru:`A`,aciklama:`Doğru: Retroperitoneal yapıları saran fibroinflamatuar doku tablosudur; üreter daralması veya tıkanıklığına yol açabilir; orta-ileri yaşta ve erkeklerde daha sık görülür.`,sik_aciklamalari:{A:`Doğru. Retroperitoneal yapıları saran fibroinflamatuar doku tablosudur; üreter daralması veya tıkanıklığına yol açabilir; orta-ileri yaşta ve erkeklerde daha sık görülür.`,E:`Yanlış. Mesane duvarında mukozanın kese benzeri invajinasyonudur; konjenital (kas tabakasında fokal zayıflık) veya edinilmiş (distal obstrüksiyon: BPH, üretra darlığı) olabilir.`,B:`Yanlış. Tüm evrelerde proliferatif endarterit ve plazma hücre zengin infiltrat vardır.`,C:`Yanlış. Nadir fakat önemli üç grup: konjenital darlık (UPJ tıkanıklığı), neoplazmlar (genellikle ürotelyal karsinom) ve reaktif süreçler (retroperitoneal fibrozis).`,D:`Yanlış. En sık etkenler E. coli (koliformlar), Proteus, Klebsiella ve Enterobacter türleridir.`},bilgi:[4],benzer_cikmis:[]},{id:`k1-46-mesane-hastaliklari-ve-tumorleri-k13-q11`,kazanim:13,zorluk:`zor`,soru:`"LGV morfoloji ve sonuçları" bilgisini içeren doğru kurulum aşağıdakilerden hangisidir?`,secenekler:{B:`Primer dönemde genitalde spesifik olmayan üretrit, papül veya küçük ülser; sekonder dönemde şiş, hassas ve birleşip fistülize olabilen drenaj lenf düğümleri; uzun dönemde anogenital bölge ve rektumda fibrozis ve darlıklar.`,D:`HPV genital sistemde kondiloma akuminatum, prekanseröz skuamöz lezyonlar ve karsinomlar (serviks, penis, vulva, orofaringeal tonsil, konjonktiva) yapar. Kondiloma akuminatum etkeni düşük riskli HPV tip 6 ve 11'dir.`,C:`Zorunlu hücre içi Gram negatif bakteri; elementer cisim (enfeksiyöz, ekstraselüler) ve retiküler cisim (metabolik aktif, hücre içi) formları vardır; kolumnar epitel tropizmi gösterir.`,A:`Mesane mukozasının inflamasyonudur; etiyolojisi çoğunlukla bakteriyeldir, ayrıca kimyasal (ilaç), radyasyon, cihaz ve otoimmün nedenler olabilir.`,E:`Enfeksiyondan ortalama 21 gün sonra gelişir; erkekte penis/skrotum (%70), kadında vulva/serviks (~%50) yerleşir; tabanda belirgin indürasyonlu sert şankr oluşur.`},dogru:`B`,aciklama:`Doğru: Primer dönemde genitalde spesifik olmayan üretrit, papül veya küçük ülser; sekonder dönemde şiş, hassas ve birleşip fistülize olabilen drenaj lenf düğümleri; uzun dönemde anogenital bölge ve rektumda fibrozis ve darlıklar.`,sik_aciklamalari:{B:`Doğru. Primer dönemde genitalde spesifik olmayan üretrit, papül veya küçük ülser; sekonder dönemde şiş, hassas ve birleşip fistülize olabilen drenaj lenf düğümleri; uzun dönemde anogenital bölge ve rektumda fibrozis ve darlıklar.`,D:`Yanlış. HPV genital sistemde kondiloma akuminatum, prekanseröz skuamöz lezyonlar ve karsinomlar (serviks, penis, vulva, orofaringeal tonsil, konjonktiva) yapar. Kondiloma akuminatum etkeni düşük riskli HPV tip 6 ve 11'dir.`,C:`Yanlış. Zorunlu hücre içi Gram negatif bakteri; elementer cisim (enfeksiyöz, ekstraselüler) ve retiküler cisim (metabolik aktif, hücre içi) formları vardır; kolumnar epitel tropizmi gösterir.`,A:`Yanlış. Mesane mukozasının inflamasyonudur; etiyolojisi çoğunlukla bakteriyeldir, ayrıca kimyasal (ilaç), radyasyon, cihaz ve otoimmün nedenler olabilir.`,E:`Yanlış. Enfeksiyondan ortalama 21 gün sonra gelişir; erkekte penis/skrotum (%70), kadında vulva/serviks (~%50) yerleşir; tabanda belirgin indürasyonlu sert şankr oluşur.`},bilgi:[30],benzer_cikmis:[]}],ilgili_cikmis:[]},{no:14,metin:`Trichomoniasis, genital herpes ve HPV enfeksiyonlarının klinik ve mikroskobik özelliklerini bilmek`,sorular:[{id:`k1-46-q41`,kazanim:14,zorluk:`kolay`,soru:`Şeffaf bir halo ile çevrili, homojen intranükleer inklüzyon (Cowdry tip A) ve çok çekirdekli dev hücreler hangi genital enfeksiyonda görülür?`,secenekler:{A:`Herpes simpleks virüs`,B:`HPV`,C:`Trichomonas vaginalis`,D:`Chlamydia trachomatis`,E:`Treponema pallidum`},dogru:`A`,aciklama:`Genital herpeste intraepitelyal veziküller, Cowdry tip A inklüzyonları ve çok çekirdekli dev hücreler görülür.`,sik_aciklamalari:{A:`Doğru: HSV'nin tipik sitopatik etkisidir.`,B:`HPV'nin sitopatik etkisi koilositozdur.`,C:`Trichomonas ıslak preparatta hareketli protozoon olarak görülür.`,D:`Klamidya hücre içi cisimler oluşturur, Cowdry A değil.`,E:`Sifiliste plazma hücreli endarterit görülür.`},bilgi:[36],benzer_cikmis:[`b0b9b653d6e8`]},{id:`k1-46-q42`,kazanim:14,zorluk:`orta`,soru:`Bol, köpüklü, sarı-yeşil vajinal akıntı ve kaşıntı ile başvuran kadında tanı nasıl konur?`,secenekler:{A:`Vajinal kazıntının ıslak preparatında hareketli kamçılı organizmanın görülmesiyle`,B:`Gram boyamada hücre içi diplokoklarla`,C:`Koilositlerin görülmesiyle`,D:`Cowdry A inklüzyonlarıyla`,E:`Karanlık alan mikroskopisinde spiroketlerle`},dogru:`A`,aciklama:`Trichomoniasis tanısı ıslak preparatta hareketli T. vaginalis gösterilerek konur; eşzamanlı klamidya ve gonore testleri yapılır.`,sik_aciklamalari:{A:`Doğru: kamçılı protozoonun hareketli görülmesi tanı koydurur.`,B:`Hücre içi diplokoklar gonoreyi gösterir.`,C:`Koilositler HPV enfeksiyonunda görülür.`,D:`Cowdry A inklüzyonları herpese aittir.`,E:`Spiroketler sifiliste görülür.`},bilgi:[33,34],benzer_cikmis:[`e28693ffa242`]},{id:`k1-46-q43`,kazanim:14,zorluk:`zor`,soru:`Genital enfeksiyonlar ile ilgili aşağıdakilerden hangisi yanlıştır?`,secenekler:{A:`Kondiloma akuminata etkeni düşük riskli HPV tip 6 ve 11'dir`,B:`Kondilomda papiller skuamöz proliferasyon ve koilositoz görülür`,C:`Genital herpes nüksleri primer enfeksiyondan daha hafif ve kısa sürelidir`,D:`Yenidoğan herpesinde mortalite yaygın hastalıkta en yüksektir`,E:`Trichomoniasis gebelikte erken doğum riskini azaltır`},dogru:`E`,aciklama:`Trichomoniasis gebelikte erken membran rüptürü ve erken doğum riskini artırır.`,sik_aciklamalari:{A:`Doğru ifade: HPV 6/11 anogenital siğil yapar.`,B:`Doğru ifade: koilositoz perinükleer halo ve hafif atipidir.`,C:`Doğru ifade: nüksler daha hafiftir; asemptomatik saçılım sıktır.`,D:`Doğru ifade: yaygın hastalıkta mortalite ~%30'dur.`,E:`Yanlış ifade (aranan cevap): risk artar, azalmaz.`},bilgi:[33,36,37,38,39],benzer_cikmis:[]},{id:`k1-46-mesane-hastaliklari-ve-tumorleri-k14-q04`,kazanim:14,zorluk:`orta`,soru:`Köpüklü sarı-yeşil akıntılı kadında ıslak preparatta hareketli organizmalar görülüyor. Aşağıdakilerden hangisi doğrudur?`,secenekler:{A:`Etken bakteridir`,B:`Trichomonas hareketsizdir`,C:`HSV'de inklüzyon görülmez`,D:`Trichomonas gebelikte risksizdir`,E:`Etken Trichomonas vaginalis'tir (kamçılı protozoon); %70 başlangıçta asemptomatiktir; genital HSV'de Cowdry A inklüzyonu ve çok çekirdekli dev hücreler görülür`},dogru:`E`,aciklama:`Trichomonas hareketli protozoondur; HSV'de Cowdry A tipiktir.`,sik_aciklamalari:{A:`Yanlış: bu seçenek vakadaki tabloyla uyumlu değildir; doğru yanıt 'Etken Trichomonas vaginalis'tir (kamçılı protozoon); %70 başlangıçta asemptomatiktir; genital HSV'de Cowdry A inklüzyonu ve çok çekirdekli dev hücreler görülür' seçeneğidir.`,B:`Yanlış: bu seçenek vakadaki tabloyla uyumlu değildir; doğru yanıt 'Etken Trichomonas vaginalis'tir (kamçılı protozoon); %70 başlangıçta asemptomatiktir; genital HSV'de Cowdry A inklüzyonu ve çok çekirdekli dev hücreler görülür' seçeneğidir.`,C:`Yanlış: bu seçenek vakadaki tabloyla uyumlu değildir; doğru yanıt 'Etken Trichomonas vaginalis'tir (kamçılı protozoon); %70 başlangıçta asemptomatiktir; genital HSV'de Cowdry A inklüzyonu ve çok çekirdekli dev hücreler görülür' seçeneğidir.`,D:`Yanlış: bu seçenek vakadaki tabloyla uyumlu değildir; doğru yanıt 'Etken Trichomonas vaginalis'tir (kamçılı protozoon); %70 başlangıçta asemptomatiktir; genital HSV'de Cowdry A inklüzyonu ve çok çekirdekli dev hücreler görülür' seçeneğidir.`,E:`Doğru: Trichomonas hareketli protozoondur; HSV'de Cowdry A tipiktir.`},bilgi:[33,34,35,36],benzer_cikmis:[]},{id:`k1-46-mesane-hastaliklari-ve-tumorleri-k14-q05`,kazanim:14,zorluk:`zor`,soru:`Yenidoğan herpesi mortalitesi ve HPV tipleri soruluyor. Aşağıdakilerden hangisi yanlıştır?`,secenekler:{A:`Kondiloma akuminatum HPV tip 6 ve 11 ile oluşur`,B:`Koilositoz (perinükleer halo) karakteristiktir`,C:`Yenidoğan herpesi selimdir ve HPV 16 düşük risklidir; kondilomlar kansere dönüşür`,D:`Nüksler primerden hafif-kısadır; asemptomatik saçılım sıktır`,E:`Yaygın yenidoğan HSV hastalığında mortalite ~%30'dur`},dogru:`E`,aciklama:`Yaygın neonatal herpes ölümcüldür; HPV 6/11 düşük risklidir; kondilom kansere dönüşmez.`,sik_aciklamalari:{A:`Yanlış: bu seçenek vakadaki tabloyla uyumlu değildir; doğru yanıt 'Yaygın yenidoğan HSV hastalığında mortalite ~%30'dur' seçeneğidir.`,B:`Yanlış: bu seçenek vakadaki tabloyla uyumlu değildir; doğru yanıt 'Yaygın yenidoğan HSV hastalığında mortalite ~%30'dur' seçeneğidir.`,C:`Yanlış: bu seçenek vakadaki tabloyla uyumlu değildir; doğru yanıt 'Yaygın yenidoğan HSV hastalığında mortalite ~%30'dur' seçeneğidir.`,D:`Yanlış: bu seçenek vakadaki tabloyla uyumlu değildir; doğru yanıt 'Yaygın yenidoğan HSV hastalığında mortalite ~%30'dur' seçeneğidir.`,E:`Doğru: Yaygın neonatal herpes ölümcüldür; HPV 6/11 düşük risklidir; kondilom kansere dönüşmez.`},bilgi:[35,36,37,38,39],benzer_cikmis:[]},{id:`k1-46-mesane-hastaliklari-ve-tumorleri-k14-q06`,kazanim:14,zorluk:`orta`,soru:`Trikomoniyaz etkeninin morfolojisi ve pratik tanı yöntemi nedir?`,secenekler:{A:`Gram negatif diplokok; kültürle tanınır`,B:`Spiroket; karanlık alanla tanınır`,C:`Zorunlu hücre içi bakteri; NAAT gerekir`,D:`Kamçılı protozoon; ıslak preparatta hareketlidir`,E:`Zarflı virus; inklüzyon cisimciği yapar`},dogru:`D`,aciklama:`Trichomonas vaginalis kamçılı protozoondur; kadında kaşıntı, bol köpüklü sarı-yeşil akıntı ve dizüri yapar. Tanı ıslak preparatta hareketli organizmanın görülmesiyle konur. Eş zamanlı klamidya ve gonore testi yapılır.`,sik_aciklamalari:{A:`Yanlış: Bu tanım gonokoklara aittir.`,B:`Yanlış: Karanlık alan sifiliz tanısında kullanılır.`,C:`Yanlış: Bu tanım klamidyaya aittir.`,D:`Doğru: Kamçılı hareket ıslak preparatta tanı koydurur.`,E:`Yanlış: İnklüzyon cisimciği herpese aittir.`},bilgi:[33,34],benzer_cikmis:[]},{id:`k1-46-mesane-hastaliklari-ve-tumorleri-k14-q07`,kazanim:14,zorluk:`orta`,soru:`Genital herpes ile HPV enfeksiyonunun tipik sitopatik bulguları nasıl ayrılır?`,secenekler:{A:`Herpes dev hücre; HPV koilositoz oluşturur`,B:`Herpes koilositoz; HPV dev hücre yapar`,C:`Her ikisi de kondiloma lata oluşturur`,D:`Her ikisi de kamçılı protozoondur`,E:`Her ikisi de sert şankr oluşturur`},dogru:`A`,aciklama:`Genital herpes HSV-2 (artan oranda HSV-1) ile ağrılı vezikül-ülser, dizüri ve lenfadenopati yapar. Histolojide intraepitelyal vezikül, Cowdry tip A inklüzyon ve çok çekirdekli dev hücreler görülür. HPV 6 ve 11 ise papiller skuamöz proliferasyon ve koilositozla kondiloma akuminatum oluşturur.`,sik_aciklamalari:{A:`Doğru: Dev hücreli vezikül herpesin, koilositoz HPV'nindir.`,B:`Yanlış: Sitopatik etkiler belirtilenin tersidir.`,C:`Yanlış: Kondiloma lata sifiliz lezyonudur.`,D:`Yanlış: İkisi de viral etkendir.`,E:`Yanlış: Sert şankr sifilize aittir.`},bilgi:[35,36,38,39],benzer_cikmis:[]},{id:`k1-46-mesane-hastaliklari-ve-tumorleri-k14-q08`,kazanim:14,zorluk:`kolay`,soru:`Aşağıdakilerden "Sistit tanımı ve sıklığı" ile ilgili doğru olan seçeneği işaretleyiniz.`,secenekler:{C:`Mesane mukozasının inflamasyonudur; etiyolojisi çoğunlukla bakteriyeldir, ayrıca kimyasal (ilaç), radyasyon, cihaz ve otoimmün nedenler olabilir.`,A:`Tüm evrelerde proliferatif endarterit ve plazma hücre zengin infiltrat vardır.`,B:`Enfeksiyondan ortalama 21 gün sonra gelişir; erkekte penis/skrotum (%70), kadında vulva/serviks (~%50) yerleşir; tabanda belirgin indürasyonlu sert şankr oluşur.`,E:`Mesane duvarında mukozanın kese benzeri invajinasyonudur; konjenital (kas tabakasında fokal zayıflık) veya edinilmiş (distal obstrüksiyon: BPH, üretra darlığı) olabilir.`,D:`Pürülan inflamasyon; erkekte ödemli hiperemik üretral meatus; Gram boyasında nötrofiller içinde Gram negatif diplokoklar. Tanıda NAAT tercih edilir; kültür antibiyotik duyarlılığı için kullanılır.`},dogru:`C`,aciklama:`Doğru: Mesane mukozasının inflamasyonudur; etiyolojisi çoğunlukla bakteriyeldir, ayrıca kimyasal (ilaç), radyasyon, cihaz ve otoimmün nedenler olabilir.`,sik_aciklamalari:{C:`Doğru. Mesane mukozasının inflamasyonudur; etiyolojisi çoğunlukla bakteriyeldir, ayrıca kimyasal (ilaç), radyasyon, cihaz ve otoimmün nedenler olabilir.`,A:`Yanlış. Tüm evrelerde proliferatif endarterit ve plazma hücre zengin infiltrat vardır.`,B:`Yanlış. Enfeksiyondan ortalama 21 gün sonra gelişir; erkekte penis/skrotum (%70), kadında vulva/serviks (~%50) yerleşir; tabanda belirgin indürasyonlu sert şankr oluşur.`,E:`Yanlış. Mesane duvarında mukozanın kese benzeri invajinasyonudur; konjenital (kas tabakasında fokal zayıflık) veya edinilmiş (distal obstrüksiyon: BPH, üretra darlığı) olabilir.`,D:`Yanlış. Pürülan inflamasyon; erkekte ödemli hiperemik üretral meatus; Gram boyasında nötrofiller içinde Gram negatif diplokoklar. Tanıda NAAT tercih edilir; kültür antibiyotik duyarlılığı için kullanılır.`},bilgi:[8],benzer_cikmis:[]},{id:`k1-46-mesane-hastaliklari-ve-tumorleri-k14-q09`,kazanim:14,zorluk:`orta`,soru:`"Sifilis tanı ve tedavi" ile ilgili aşağıdakilerden hangisi yanlıştır?`,secenekler:{C:`Etken penisiline son derece duyarlıdır. Nontreponemal testler (RPR, VDRL; antikardiyolipin) tedavi izleminde kullanılır ve titre düşer; treponemal testler (T. pallidum spesifik antikor) genellikle ömür boyu pozitif kalır.`,A:`Kronik pelvik ağrı ve Hunner ülseri ile seyreder; kültür negatiftir ve daha çok kadınlarda görülür.`,B:`Siklofosfamidin akrolein metaboliti ve adenovirus enfeksiyonları ile ilişkilidir.`,E:`Enfeksiyondan ortalama 21 gün sonra gelişir; erkekte penis/skrotum (%70), kadında vulva/serviks (~%50) yerleşir; tabanda belirgin indürasyonlu sert şankr oluşur.`,D:`Doğumda bulaşır; SEM (deri, göz, ağız) tutulumu, MSS tutulumu veya yaygın hastalık şeklinde olabilir.`},dogru:`C`,aciklama:`Doğru: Etken penisiline son derece duyarlıdır. Nontreponemal testler (RPR, VDRL; antikardiyolipin) tedavi izleminde kullanılır ve titre düşer; treponemal testler (T. pallidum spesifik antikor) genellikle ömür boyu pozitif kalır.`,sik_aciklamalari:{C:`Doğru. Etken penisiline son derece duyarlıdır. Nontreponemal testler (RPR, VDRL; antikardiyolipin) tedavi izleminde kullanılır ve titre düşer; treponemal testler (T. pallidum spesifik antikor) genellikle ömür boyu pozitif kalır.`,A:`Yanlış. Kronik pelvik ağrı ve Hunner ülseri ile seyreder; kültür negatiftir ve daha çok kadınlarda görülür.`,B:`Yanlış. Siklofosfamidin akrolein metaboliti ve adenovirus enfeksiyonları ile ilişkilidir.`,E:`Yanlış. Enfeksiyondan ortalama 21 gün sonra gelişir; erkekte penis/skrotum (%70), kadında vulva/serviks (~%50) yerleşir; tabanda belirgin indürasyonlu sert şankr oluşur.`,D:`Yanlış. Doğumda bulaşır; SEM (deri, göz, ağız) tutulumu, MSS tutulumu veya yaygın hastalık şeklinde olabilir.`},bilgi:[22],benzer_cikmis:[]},{id:`k1-46-mesane-hastaliklari-ve-tumorleri-k14-q10`,kazanim:14,zorluk:`orta`,soru:`"Skuamöz hücreli karsinom patogenezi" ile ilgili eşleştirmelerden hangisi doğrudur?`,secenekler:{A:`Endemik şistozomiyazis bölgelerinde kronik sistit, skuamöz metaplazi ve skuamöz hücreli karsinom insidansı artar; patogenez kronik inflamasyon + metaplazi → displazi → karsinomdur.`,B:`Zorunlu hücre içi Gram negatif bakteri; elementer cisim (enfeksiyöz, ekstraselüler) ve retiküler cisim (metabolik aktif, hücre içi) formları vardır; kolumnar epitel tropizmi gösterir.`,E:`Semptomatik olguda ağrılı vezikül/ülserler, dizüri, akıntı, lenfadenopati, ateş ve miyalji; histolojide intraepitelyal veziküller, Cowdry tip A intranükleer inklüzyon ve çok çekirdekli dev hücreler.`,C:`Vajinal kazıntıdan ıslak preparatta hareketli organizmanın gösterilmesiyle konur; genellikle eşzamanlı klamidya ve gonore testleri yapılır.`,D:`Erkekte üretrit (dizüri, sık idrara çıkma, mukopürülan akıntı), kadında çoğu zaman asemptomatik seyir; tedavi edilmezse PID, infertilite ve ektopik gebelik gelişir.`},dogru:`A`,aciklama:`Doğru: Endemik şistozomiyazis bölgelerinde kronik sistit, skuamöz metaplazi ve skuamöz hücreli karsinom insidansı artar; patogenez kronik inflamasyon + metaplazi → displazi → karsinomdur.`,sik_aciklamalari:{A:`Doğru. Endemik şistozomiyazis bölgelerinde kronik sistit, skuamöz metaplazi ve skuamöz hücreli karsinom insidansı artar; patogenez kronik inflamasyon + metaplazi → displazi → karsinomdur.`,B:`Yanlış. Zorunlu hücre içi Gram negatif bakteri; elementer cisim (enfeksiyöz, ekstraselüler) ve retiküler cisim (metabolik aktif, hücre içi) formları vardır; kolumnar epitel tropizmi gösterir.`,E:`Yanlış. Semptomatik olguda ağrılı vezikül/ülserler, dizüri, akıntı, lenfadenopati, ateş ve miyalji; histolojide intraepitelyal veziküller, Cowdry tip A intranükleer inklüzyon ve çok çekirdekli dev hücreler.`,C:`Yanlış. Vajinal kazıntıdan ıslak preparatta hareketli organizmanın gösterilmesiyle konur; genellikle eşzamanlı klamidya ve gonore testleri yapılır.`,D:`Yanlış. Erkekte üretrit (dizüri, sık idrara çıkma, mukopürülan akıntı), kadında çoğu zaman asemptomatik seyir; tedavi edilmezse PID, infertilite ve ektopik gebelik gelişir.`},bilgi:[13],benzer_cikmis:[]},{id:`k1-46-mesane-hastaliklari-ve-tumorleri-k14-q11`,kazanim:14,zorluk:`zor`,soru:`"Konjenital sifilis" klinik bağlamda aşağıdakilerden hangisi doğrudur?`,secenekler:{C:`Gebeliğin herhangi bir döneminde plasenta yoluyla bulaşır; intrauterin/perinatal ölüm ~%25 olabilir. Erken form hepatosplenomegali, snuffles, döküntü ve iskelet lezyonları; geç form Hutchinson triadı (interstisyel keratit, Hutchinson dişleri, sinir işitme kaybı).`,D:`HPV genital sistemde kondiloma akuminatum, prekanseröz skuamöz lezyonlar ve karsinomlar (serviks, penis, vulva, orofaringeal tonsil, konjonktiva) yapar. Kondiloma akuminatum etkeni düşük riskli HPV tip 6 ve 11'dir.`,A:`Etken Treponema pallidum (spiroket); bulaş erken evre deri/mukoza lezyonlarıyla temasla ve konjenital olarak plasenta yoluyla olur.`,E:`Böbrek pelvisi, üreter, mesane ve üretra ürotelyum (geçiş epiteli) ile kaplıdır; altında lamina propria ve muskularis propria (mesanede detrusor kası) vardır.`,B:`Semptomatik olguda ağrılı vezikül/ülserler, dizüri, akıntı, lenfadenopati, ateş ve miyalji; histolojide intraepitelyal veziküller, Cowdry tip A intranükleer inklüzyon ve çok çekirdekli dev hücreler.`},dogru:`C`,aciklama:`Doğru: Gebeliğin herhangi bir döneminde plasenta yoluyla bulaşır; intrauterin/perinatal ölüm ~%25 olabilir. Erken form hepatosplenomegali, snuffles, döküntü ve iskelet lezyonları; geç form Hutchinson triadı (interstisyel keratit, Hutchinson dişleri, sinir işitme kaybı).`,sik_aciklamalari:{C:`Doğru. Gebeliğin herhangi bir döneminde plasenta yoluyla bulaşır; intrauterin/perinatal ölüm ~%25 olabilir. Erken form hepatosplenomegali, snuffles, döküntü ve iskelet lezyonları; geç form Hutchinson triadı (interstisyel keratit, Hutchinson dişleri, sinir işitme kaybı).`,D:`Yanlış. HPV genital sistemde kondiloma akuminatum, prekanseröz skuamöz lezyonlar ve karsinomlar (serviks, penis, vulva, orofaringeal tonsil, konjonktiva) yapar. Kondiloma akuminatum etkeni düşük riskli HPV tip 6 ve 11'dir.`,A:`Yanlış. Etken Treponema pallidum (spiroket); bulaş erken evre deri/mukoza lezyonlarıyla temasla ve konjenital olarak plasenta yoluyla olur.`,E:`Yanlış. Böbrek pelvisi, üreter, mesane ve üretra ürotelyum (geçiş epiteli) ile kaplıdır; altında lamina propria ve muskularis propria (mesanede detrusor kası) vardır.`,B:`Yanlış. Semptomatik olguda ağrılı vezikül/ülserler, dizüri, akıntı, lenfadenopati, ateş ve miyalji; histolojide intraepitelyal veziküller, Cowdry tip A intranükleer inklüzyon ve çok çekirdekli dev hücreler.`},bilgi:[21],benzer_cikmis:[]}],ilgili_cikmis:[{id:`b0b9b653d6e8`,soru:`Cinsel yolla bulaşan hastalıklar. Şeffaf bir halo ile çevrelenen açık mor, homojen intranükleer Inklüzyon (Cowdry A İnklüzyon) hangisi ile infeksiyonda görülür?`,secenekler:{A:`Human papillomavirus`,B:`Neisseria gonorrhoeae`,C:`Herpes Simpleks`,D:`Trichomonas vaginalis`,E:`Chlamydia`},cevap:`A`},{id:`e28693ffa242`,soru:`Tıbbi Patoloji Tıbbi Patoloji Cinsel Yolla Bulaşan Hastalıklar Hangisi servikovajinal yayma sitolojisinde direkt olarak tesbit edilebilir?`,secenekler:{A:`Treponema pallidum`,B:`Neisseria gonorrhoeae`,C:`HerpesSimpleks`,D:`Trichomonas vaginalis`,E:`Chlamydiatrachomatis`},cevap:`B`}]},{no:15,metin:`HPV aşısının etkisini ve uygulama önerisini açıklayabilmek`,sorular:[{id:`k1-46-q44`,kazanim:15,zorluk:`kolay`,soru:`HPV aşısının uygulanması önerilen grup hangisidir?`,secenekler:{A:`Ergenlik öncesi/ergenlik dönemindeki kız ve erkek çocuklar`,B:`Yalnızca 60 yaş üstü kadınlar`,C:`Yalnızca serviks kanseri tanısı almış hastalar`,D:`Yalnızca yenidoğanlar`,E:`Yalnızca erkekler`},dogru:`A`,aciklama:`HPV aşısı ergenlik öncesi/ergenlikte kız ve erkek çocuklara rutin olarak uygulanmalıdır.`,sik_aciklamalari:{A:`Doğru: cinsel aktivite öncesi aşılama en etkilidir.`,B:`İleri yaş rutin aşılama hedefi değildir.`,C:`Aşı koruyucudur, kanser tedavisi değildir.`,D:`Yenidoğanlara rutin uygulanmaz.`,E:`Her iki cinsiyete önerilir.`},bilgi:[40],benzer_cikmis:[]},{id:`k1-46-q45`,kazanim:15,zorluk:`orta`,soru:`Dört veya dokuz değerlikli HPV aşısının etkileri ile ilgili hangisi doğrudur?`,secenekler:{A:`Tip 6 ve 11'e karşı koruyarak anogenital siğilleri önler ve HPV ilişkili karsinom insidansını azaltır`,B:`Yalnızca anogenital siğilleri önler, kanser riskini etkilemez`,C:`Sifilis ve gonoreye karşı da korur`,D:`Mevcut serviks kanserini tedavi eder`,E:`Yalnızca düşük riskli tipleri içerir`},dogru:`A`,aciklama:`Aşı düşük riskli 6/11'e karşı siğilleri önler; yüksek riskli tiplere karşı koruyarak özellikle serviks kanseri insidansını azaltır.`,sik_aciklamalari:{A:`Doğru: hem siğil hem kanser önleyici etkisi vardır.`,B:`Karsinom insidansını da azaltır.`,C:`Bakteriyel CYBE'lere karşı koruma sağlamaz.`,D:`Aşı koruyucudur, tedavi edici değildir.`,E:`Yüksek riskli tipleri de içerir; kanser önleyici etkisi bundandır.`},bilgi:[38,40],benzer_cikmis:[`61384be5d1e3`]},{id:`k1-46-q46`,kazanim:15,zorluk:`zor`,soru:`HPV ile ilişkili aşağıdaki lezyon/kanserlerden hangisi aşının önleyebileceği hastalık spektrumunda yer almaz?`,secenekler:{A:`Kondiloma akuminata`,B:`Serviks karsinomu`,C:`Orofaringeal tonsil karsinomu`,D:`Vulva karsinomu`,E:`Mesanenin şistozomiyazise bağlı skuamöz hücreli karsinomu`},dogru:`E`,aciklama:`HPV kondiloma ile serviks, penis, vulva, orofarenks ve konjonktiva karsinomlarıyla ilişkilidir; şistozomiyazis ilişkili mesane SCC'si HPV ile ilişkili değildir.`,sik_aciklamalari:{A:`HPV 6/11 kaynaklıdır; aşı ile önlenir.`,B:`Yüksek riskli HPV ile ilişkilidir; aşı insidansı azaltır.`,C:`HPV ilişkili karsinomlar arasındadır.`,D:`HPV ilişkili karsinomlar arasındadır.`,E:`Doğru: kronik irritasyon/şistozomiyazis zemininde gelişir, HPV aşısı ile önlenmez.`},bilgi:[13,38,40],benzer_cikmis:[`1930494e8ed0`]},{id:`k1-46-mesane-hastaliklari-ve-tumorleri-k15-q04`,kazanim:15,zorluk:`orta`,soru:`Adölesan aşılama polikliniğinde HPV aşısı danışmanlığı veriliyor. Aşağıdakilerden hangisi doğrudur?`,secenekler:{A:`Aşı yalnızca erişkine yapılır`,B:`Dört/dokuz değerlikli aşı tip 6 ve 11'e karşı korur, anogenital siğilleri önler ve HPV ilişkili karsinom (özellikle serviks) insidansını azaltır; ergenlik öncesi/ergenlikte kız-erkeklere rutin uygulanır`,C:`Aşı siğilleri artırır`,D:`Aşı yalnızca tedavi amaçlıdır`,E:`Erkek aşılaması önerilmez`},dogru:`B`,aciklama:`Aşı profilaktiktir; adölesan dönemde her iki cinse önerilir.`,sik_aciklamalari:{A:`Yanlış: bu seçenek vakadaki tabloyla uyumlu değildir; doğru yanıt 'Dört/dokuz değerlikli aşı tip 6 ve 11'e karşı korur, anogenital siğilleri önler ve HPV ilişkili karsinom (özellikle serviks) insidansını azaltır; ergenlik öncesi/ergenlikte kız-erkeklere rutin uygulanır' seçeneğidir.`,B:`Doğru: Aşı profilaktiktir; adölesan dönemde her iki cinse önerilir.`,C:`Yanlış: bu seçenek vakadaki tabloyla uyumlu değildir; doğru yanıt 'Dört/dokuz değerlikli aşı tip 6 ve 11'e karşı korur, anogenital siğilleri önler ve HPV ilişkili karsinom (özellikle serviks) insidansını azaltır; ergenlik öncesi/ergenlikte kız-erkeklere rutin uygulanır' seçeneğidir.`,D:`Yanlış: bu seçenek vakadaki tabloyla uyumlu değildir; doğru yanıt 'Dört/dokuz değerlikli aşı tip 6 ve 11'e karşı korur, anogenital siğilleri önler ve HPV ilişkili karsinom (özellikle serviks) insidansını azaltır; ergenlik öncesi/ergenlikte kız-erkeklere rutin uygulanır' seçeneğidir.`,E:`Yanlış: bu seçenek vakadaki tabloyla uyumlu değildir; doğru yanıt 'Dört/dokuz değerlikli aşı tip 6 ve 11'e karşı korur, anogenital siğilleri önler ve HPV ilişkili karsinom (özellikle serviks) insidansını azaltır; ergenlik öncesi/ergenlikte kız-erkeklere rutin uygulanır' seçeneğidir.`},bilgi:[40],benzer_cikmis:[]},{id:`k1-46-mesane-hastaliklari-ve-tumorleri-k15-q05`,kazanim:15,zorluk:`zor`,soru:`Aşının kapsadığı tipler ve etkisi tartışılıyor. Aşağıdakilerden hangisi yanlıştır?`,secenekler:{A:`Anogenital siğilleri önler`,B:`Serviks kanseri insidansını azaltır`,C:`Aşı düşük riskli tip 6/11'e karşı korur`,D:`HPV aşısı serviks kanseri riskini artırır ve yalnızca ileri yaşta tek cinse yapılır`,E:`Rutin uygulama ergenlik öncesi/ergenlik dönemidir`},dogru:`C`,aciklama:`Aşı riski azaltır ve her iki cinse adölesan dönemde uygulanır.`,sik_aciklamalari:{A:`Yanlış: bu seçenek vakadaki tabloyla uyumlu değildir; doğru yanıt 'Aşı düşük riskli tip 6/11'e karşı korur' seçeneğidir.`,B:`Yanlış: bu seçenek vakadaki tabloyla uyumlu değildir; doğru yanıt 'Aşı düşük riskli tip 6/11'e karşı korur' seçeneğidir.`,C:`Doğru: Aşı riski azaltır ve her iki cinse adölesan dönemde uygulanır.`,D:`Yanlış: bu seçenek vakadaki tabloyla uyumlu değildir; doğru yanıt 'Aşı düşük riskli tip 6/11'e karşı korur' seçeneğidir.`,E:`Yanlış: bu seçenek vakadaki tabloyla uyumlu değildir; doğru yanıt 'Aşı düşük riskli tip 6/11'e karşı korur' seçeneğidir.`},bilgi:[38,40],benzer_cikmis:[]},{id:`k1-46-mesane-hastaliklari-ve-tumorleri-k15-q06`,kazanim:15,zorluk:`orta`,soru:`HPV aşısının değerliği ve koruduğu tablolar hangileridir?`,secenekler:{A:`Yalnızca tedavi edici; siğilleri küçültür`,B:`Tek değerlikli; yalnızca HSV'yi önler`,C:`Dört-dokuz değerlikli; siğil ve kanseri azaltır`,D:`Canlı virus; kondilomu tedavi eder`,E:`Antibiyotik içerir; bakteriyi öldürür`},dogru:`C`,aciklama:`HPV aşısı dört veya dokuz değerliklidir; düşük riskli tip 6 ve 11'e karşı koruyarak anogenital siğilleri önler. Yüksek riskli tiplere karşı koruma serviks kanseri insidansını azaltır. Aşı profilaktik etkilidir, terapötik değildir.`,sik_aciklamalari:{A:`Yanlış: Aşı profilaktiktir, mevcut lezyonu tedavi etmez.`,B:`Yanlış: Çok değerliklidir ve HPV tiplerine yöneliktir.`,C:`Doğru: Tip 6-11 koruması siğili, diğer tipler kanseri azaltır.`,D:`Yanlış: Aşı virus benzeri parçacık içerir, canlı değildir.`,E:`Yanlış: Aşıda antibiyotik bulunmaz.`},bilgi:[40],benzer_cikmis:[]},{id:`k1-46-mesane-hastaliklari-ve-tumorleri-k15-q07`,kazanim:15,zorluk:`orta`,soru:`Kondiloma akuminatumun etkeni ve aşıyle ilişkisi nedir?`,secenekler:{A:`Kondilom yüksek riskli tip 16'ya bağlıdır`,B:`Kondilom sifilizin geç lezyonudur`,C:`Koilositoz herpesin tipik bulgusudur`,D:`Aşı mevcut kondilomu tamamen eritir`,E:`Kondilom tip 6-11 papiller siğildir; aşı önler`},dogru:`E`,aciklama:`Kondiloma akuminatum düşük riskli HPV 6 ve 11'e bağlı papiller siğildir; erkekte koronal sulkus, kadında vulva-perianal yerleşir. Aşı bu tiplere karşı bağışıklık sağlayarak siğil insidansını düşürür. Mikroskopide koilositik atipi tanıyı destekler.`,sik_aciklamalari:{A:`Yanlış: Tip 16 karsinomla ilişkilidir, siğille değil.`,B:`Yanlış: Kondiloma akuminatum HPV lezyonudur.`,C:`Yanlış: Koilositoz HPV sitopatisidir.`,D:`Yanlış: Aşı profilaktiktir, terapötik etkisi yoktur.`,E:`Doğru: Tip 6-11 papiller proliferasyon yapar; aşı korur.`},bilgi:[38,39],benzer_cikmis:[]},{id:`k1-46-mesane-hastaliklari-ve-tumorleri-k15-q08`,kazanim:15,zorluk:`kolay`,soru:`"HPV ve kondiloma akuminatum" ifadesi ile ilgili aşağıdakilerden hangisi doğrudur?`,secenekler:{C:`HPV genital sistemde kondiloma akuminatum, prekanseröz skuamöz lezyonlar ve karsinomlar (serviks, penis, vulva, orofaringeal tonsil, konjonktiva) yapar. Kondiloma akuminatum etkeni düşük riskli HPV tip 6 ve 11'dir.`,B:`Semptomatik olguda ağrılı vezikül/ülserler, dizüri, akıntı, lenfadenopati, ateş ve miyalji; histolojide intraepitelyal veziküller, Cowdry tip A intranükleer inklüzyon ve çok çekirdekli dev hücreler.`,A:`Nadir fakat önemli üç grup: konjenital darlık (UPJ tıkanıklığı), neoplazmlar (genellikle ürotelyal karsinom) ve reaktif süreçler (retroperitoneal fibrozis).`,E:`En sık etkenler E. coli (koliformlar), Proteus, Klebsiella ve Enterobacter türleridir.`,D:`Etken Trichomonas vaginalis (kamçılı protozoon); genellikle cinsel temasla bulaşır. Kadında pruritus, bol köpüklü sarı-yeşil vajinal akıntı, üretral kolonizasyona bağlı dizüri; erkekte genelde hafif üretrit.`},dogru:`C`,aciklama:`Doğru: HPV genital sistemde kondiloma akuminatum, prekanseröz skuamöz lezyonlar ve karsinomlar (serviks, penis, vulva, orofaringeal tonsil, konjonktiva) yapar. Kondiloma akuminatum etkeni düşük riskli HPV tip 6 ve 11'dir.`,sik_aciklamalari:{C:`Doğru. HPV genital sistemde kondiloma akuminatum, prekanseröz skuamöz lezyonlar ve karsinomlar (serviks, penis, vulva, orofaringeal tonsil, konjonktiva) yapar. Kondiloma akuminatum etkeni düşük riskli HPV tip 6 ve 11'dir.`,B:`Yanlış. Semptomatik olguda ağrılı vezikül/ülserler, dizüri, akıntı, lenfadenopati, ateş ve miyalji; histolojide intraepitelyal veziküller, Cowdry tip A intranükleer inklüzyon ve çok çekirdekli dev hücreler.`,A:`Yanlış. Nadir fakat önemli üç grup: konjenital darlık (UPJ tıkanıklığı), neoplazmlar (genellikle ürotelyal karsinom) ve reaktif süreçler (retroperitoneal fibrozis).`,E:`Yanlış. En sık etkenler E. coli (koliformlar), Proteus, Klebsiella ve Enterobacter türleridir.`,D:`Yanlış. Etken Trichomonas vaginalis (kamçılı protozoon); genellikle cinsel temasla bulaşır. Kadında pruritus, bol köpüklü sarı-yeşil vajinal akıntı, üretral kolonizasyona bağlı dizüri; erkekte genelde hafif üretrit.`},bilgi:[38],benzer_cikmis:[]},{id:`k1-46-mesane-hastaliklari-ve-tumorleri-k15-q09`,kazanim:15,zorluk:`orta`,soru:`"İnterstisyel sistit" kavramı hakkında verilen aşağıdakilerden hangisi doğrudur?`,secenekler:{D:`Kronik pelvik ağrı ve Hunner ülseri ile seyreder; kültür negatiftir ve daha çok kadınlarda görülür.`,B:`Etken HSV-1 ve HSV-2; genital olgular çoğunlukla HSV-2 ile oluşur ancak HSV-1 ile genital olgular artmaktadır. Bulaş enfekte mukoza/deri ile doğrudan temasla olur; virüs çevrede hızlı inaktive olur.`,A:`Etken Trichomonas vaginalis (kamçılı protozoon); genellikle cinsel temasla bulaşır. Kadında pruritus, bol köpüklü sarı-yeşil vajinal akıntı, üretral kolonizasyona bağlı dizüri; erkekte genelde hafif üretrit.`,E:`IgG4 ilişkili hastalık, maligniteler (lenfoma, ürotelyal karsinom), radyasyon, cerrahi ve bazı ilaçlar (ergot türevleri, adrenerjik blokerler, TNF inhibitörleri) ile ilişkilidir.`,C:`Pürülan inflamasyon; erkekte ödemli hiperemik üretral meatus; Gram boyasında nötrofiller içinde Gram negatif diplokoklar. Tanıda NAAT tercih edilir; kültür antibiyotik duyarlılığı için kullanılır.`},dogru:`D`,aciklama:`Doğru: Kronik pelvik ağrı ve Hunner ülseri ile seyreder; kültür negatiftir ve daha çok kadınlarda görülür.`,sik_aciklamalari:{D:`Doğru. Kronik pelvik ağrı ve Hunner ülseri ile seyreder; kültür negatiftir ve daha çok kadınlarda görülür.`,B:`Yanlış. Etken HSV-1 ve HSV-2; genital olgular çoğunlukla HSV-2 ile oluşur ancak HSV-1 ile genital olgular artmaktadır. Bulaş enfekte mukoza/deri ile doğrudan temasla olur; virüs çevrede hızlı inaktive olur.`,A:`Yanlış. Etken Trichomonas vaginalis (kamçılı protozoon); genellikle cinsel temasla bulaşır. Kadında pruritus, bol köpüklü sarı-yeşil vajinal akıntı, üretral kolonizasyona bağlı dizüri; erkekte genelde hafif üretrit.`,E:`Yanlış. IgG4 ilişkili hastalık, maligniteler (lenfoma, ürotelyal karsinom), radyasyon, cerrahi ve bazı ilaçlar (ergot türevleri, adrenerjik blokerler, TNF inhibitörleri) ile ilişkilidir.`,C:`Yanlış. Pürülan inflamasyon; erkekte ödemli hiperemik üretral meatus; Gram boyasında nötrofiller içinde Gram negatif diplokoklar. Tanıda NAAT tercih edilir; kültür antibiyotik duyarlılığı için kullanılır.`},bilgi:[11],benzer_cikmis:[]},{id:`k1-46-mesane-hastaliklari-ve-tumorleri-k15-q10`,kazanim:15,zorluk:`orta`,soru:`"Mesane divertikülünün klinik önemi" ile ilgili eşleştirmelerden hangisi doğrudur?`,secenekler:{B:`Divertikül içindeki idrar stazı tekrarlayan idrar yolu enfeksiyonu, taş oluşumu ve nadiren tümör gelişimine yol açar.`,A:`Doğumda bulaşır; SEM (deri, göz, ağız) tutulumu, MSS tutulumu veya yaygın hastalık şeklinde olabilir.`,E:`En sık etkenler E. coli (koliformlar), Proteus, Klebsiella ve Enterobacter türleridir.`,C:`HPV genital sistemde kondiloma akuminatum, prekanseröz skuamöz lezyonlar ve karsinomlar (serviks, penis, vulva, orofaringeal tonsil, konjonktiva) yapar. Kondiloma akuminatum etkeni düşük riskli HPV tip 6 ve 11'dir.`,D:`Etken Trichomonas vaginalis (kamçılı protozoon); genellikle cinsel temasla bulaşır. Kadında pruritus, bol köpüklü sarı-yeşil vajinal akıntı, üretral kolonizasyona bağlı dizüri; erkekte genelde hafif üretrit.`},dogru:`B`,aciklama:`Doğru: Divertikül içindeki idrar stazı tekrarlayan idrar yolu enfeksiyonu, taş oluşumu ve nadiren tümör gelişimine yol açar.`,sik_aciklamalari:{B:`Doğru. Divertikül içindeki idrar stazı tekrarlayan idrar yolu enfeksiyonu, taş oluşumu ve nadiren tümör gelişimine yol açar.`,A:`Yanlış. Doğumda bulaşır; SEM (deri, göz, ağız) tutulumu, MSS tutulumu veya yaygın hastalık şeklinde olabilir.`,E:`Yanlış. En sık etkenler E. coli (koliformlar), Proteus, Klebsiella ve Enterobacter türleridir.`,C:`Yanlış. HPV genital sistemde kondiloma akuminatum, prekanseröz skuamöz lezyonlar ve karsinomlar (serviks, penis, vulva, orofaringeal tonsil, konjonktiva) yapar. Kondiloma akuminatum etkeni düşük riskli HPV tip 6 ve 11'dir.`,D:`Yanlış. Etken Trichomonas vaginalis (kamçılı protozoon); genellikle cinsel temasla bulaşır. Kadında pruritus, bol köpüklü sarı-yeşil vajinal akıntı, üretral kolonizasyona bağlı dizüri; erkekte genelde hafif üretrit.`},bilgi:[7],benzer_cikmis:[]},{id:`k1-46-mesane-hastaliklari-ve-tumorleri-k15-q11`,kazanim:15,zorluk:`zor`,soru:`"Genital HSV morfoloji ve kliniği" ile ilgili bir hastada bulunacak aşağıdaki bulgulardan hangisi beklenmez?`,secenekler:{E:`Semptomatik olguda ağrılı vezikül/ülserler, dizüri, akıntı, lenfadenopati, ateş ve miyalji; histolojide intraepitelyal veziküller, Cowdry tip A intranükleer inklüzyon ve çok çekirdekli dev hücreler.`,B:`Sekonder şankr iyileşmesinden ~2 ay sonra döküntü, mukokutanöz lezyonlar ve lenfadenopati ile; kondiloma lata anogenital bölgede geniş tabanlı kabarık lezyonlardır. Tersiyer yıllar sonra (5-20 yıl) kardiyovasküler sifilis, nörosifilis ve gumma ile seyreder.`,D:`En sık bulgu ağrısız makroskopik veya mikroskopik hematüridir; tanıda sistoskopi + biyopsi ve idrar sitolojisi (özellikle yüksek dereceli ve CIS) kullanılır.`,A:`Divertikül içindeki idrar stazı tekrarlayan idrar yolu enfeksiyonu, taş oluşumu ve nadiren tümör gelişimine yol açar.`,C:`Uzun süreli enfeksiyon, taş, kateter ve şistozomiyazis ürotelyumda reaktif değişikliklere ve skuamöz metaplaziye yol açar.`},dogru:`E`,aciklama:`Doğru: Semptomatik olguda ağrılı vezikül/ülserler, dizüri, akıntı, lenfadenopati, ateş ve miyalji; histolojide intraepitelyal veziküller, Cowdry tip A intranükleer inklüzyon ve çok çekirdekli dev hücreler.`,sik_aciklamalari:{E:`Doğru. Semptomatik olguda ağrılı vezikül/ülserler, dizüri, akıntı, lenfadenopati, ateş ve miyalji; histolojide intraepitelyal veziküller, Cowdry tip A intranükleer inklüzyon ve çok çekirdekli dev hücreler.`,B:`Yanlış. Sekonder şankr iyileşmesinden ~2 ay sonra döküntü, mukokutanöz lezyonlar ve lenfadenopati ile; kondiloma lata anogenital bölgede geniş tabanlı kabarık lezyonlardır. Tersiyer yıllar sonra (5-20 yıl) kardiyovasküler sifilis, nörosifilis ve gumma ile seyreder.`,D:`Yanlış. En sık bulgu ağrısız makroskopik veya mikroskopik hematüridir; tanıda sistoskopi + biyopsi ve idrar sitolojisi (özellikle yüksek dereceli ve CIS) kullanılır.`,A:`Yanlış. Divertikül içindeki idrar stazı tekrarlayan idrar yolu enfeksiyonu, taş oluşumu ve nadiren tümör gelişimine yol açar.`,C:`Yanlış. Uzun süreli enfeksiyon, taş, kateter ve şistozomiyazis ürotelyumda reaktif değişikliklere ve skuamöz metaplaziye yol açar.`},bilgi:[36],benzer_cikmis:[]}],ilgili_cikmis:[{id:`61384be5d1e3`,soru:`Kadınlarda servikal Üriner Sistem Enfeksiyonu ve Cinsel Yolla Bulaşan Hastalıklar kansere yol açabilen cinsel yolla bulaşan hastalık hangisidir?`,secenekler:{A:`Klamidya Trachomatis`,B:`Genital Herpes Enfeksiyonları`,C:`Şankroid`,D:`Trikomoniasiz`,E:`Gonore`},cevap:`B`},{id:`1930494e8ed0`,soru:`Üroloji Üriner Sistem Enfeksiyonu ve Cinsel Yolla Bulaşan Hastalıklar kansere yol açabilen cinsel yolla bulaşan hastalık hangisidir?`,secenekler:{A:`Klamidya`,B:`Trachomatis`,C:`Genital Herpes Enfeksiyonları`,D:`Şankroid`},cevap:`C`}]}]};export{e as default};